OPOSICIONES.push({"id": "ehu-administrativa", "nombre": "Administrativo/a · UPV/EHU", "sub": "Batería oficial de 500 preguntas. Examen 21/11, BEC, 10:00. 60 preguntas + 20 de reserva, 80 min, sin penalización.", "sim": {"n": 60, "min": 80, "pena": "0"}, "temas": [{"id": "b01", "sig": "Bloque 1", "titulo": "Bloque 1. Constitución, Estatuto de Autonomía y Unión Europea", "sub": "Preguntas 1–32 de la batería oficial (sin respuestas oficiales: resueltas por Claude).", "preguntas": [{"id": "ehu001", "q": "La Constitución se fundamenta:", "o": ["En la unidad de la Nación Española.", "En el compromiso de unidad de todos los pueblos y nacionalidades integrantes de la Nación Española.", "En la indisoluble unidad de la Nación Española.", "En la pluralidad de pueblos integrantes de la Nación Española."], "c": 2, "e": "La Constitución se fundamenta en la indisoluble unidad de la Nación española, patria común e indivisible.", "r": "CE art. 2 · batería oficial, pregunta 1"}, {"id": "ehu002", "q": "Los valores superiores del ordenamiento jurídico propugnados desde la Constitución son:", "o": ["La libertad, la justicia, la igualdad y el pluralismo político.", "La libertad, la justicia y la libre competencia.", "La libertad, la igualdad y el pluralismo político y sindical.", "La libertad, la igualdad y la fraternidad."], "c": 0, "e": "España propugna como valores superiores la libertad, la justicia, la igualdad y el pluralismo político.", "r": "CE art. 1.1 · batería oficial, pregunta 2"}, {"id": "ehu003", "q": "La forma política del estado español es:", "o": ["El Parlamentarismo Bicameral.", "La Monarquía Parlamentaria.", "El Parlamentarismo Democrático.", "La Monarquía Institucional."], "c": 1, "e": "La forma política del Estado español es la Monarquía parlamentaria.", "r": "CE art. 1.3 · batería oficial, pregunta 3"}, {"id": "ehu004", "q": "La soberanía nacional:", "o": ["Reside en los/as ciudadanos/as mayores de edad.", "Reside en el Congreso y en el Senado.", "Reside en el pueblo.", "Reside en el Rey."], "c": 2, "e": "La soberanía nacional reside en el pueblo español, del que emanan los poderes del Estado.", "r": "CE art. 1.2 · batería oficial, pregunta 4"}, {"id": "ehu005", "q": "Según la Constitución Española, el estado español se ha constituido:", "o": ["En una Nación socialdemocrática de Derecho.", "En una Monarquía democrática de Derecho.", "Enun Estado social y democrático de Derecho.", "Enun Estado respetuoso del Derecho y de la Democracia."], "c": 2, "e": "España se constituye en un Estado social y democrático de Derecho.", "r": "CE art. 1.1 · batería oficial, pregunta 5"}, {"id": "ehu006", "q": "La enseñanza:", "o": ["Básica es obligatoria y gratuita.", "Primaria es potestativa.", "Media es gratuita.", "Universitaria es gratuita."], "c": 0, "e": "La enseñanza básica es obligatoria y gratuita.", "r": "CE art. 27.4 · batería oficial, pregunta 6"}, {"id": "ehu007", "q": "La educación tendrá por objeto:", "o": ["El pleno desarrollo de la personalidad humana conforme a los planes educativos aprobados por el Consejo Escolar Nacional a instancia de las Asociaciones Nacionales de Padres de Alumnos.", "El pleno desarrollo de la personalidad humana en el respeto de los principios democráticos de convivencia, y a los derechos y libertades culturales.", "El desarrollo de la personalidad humana conforme a las líneas educativas marcadas por el Consejo Escolar Nacional.", "El pleno desarrollo de la personalidad humana en el respeto a los principios democráticos de convivencia y a los derechos y libertades fundamentales"], "c": 3, "e": "La educación tendrá por objeto el pleno desarrollo de la personalidad humana en el respeto a los principios democráticos de convivencia y a los derechos y libertades fundamentales.", "r": "CE art. 27.2 · batería oficial, pregunta 7"}, {"id": "ehu008", "q": "El derecho de reunión reconocido constitucionalmente:", "o": ["Sólo precisará autorización previa cuando se prevea que la reunión no va a discurrir por cauces pacíficos.", "Sólo precisará autorización previa cuando en la reunión a celebrar se vayan a utilizar armas.", "No precisará autorización previa cuando la reunión sea pacífica y sin armas.", "Precisará para su ejercicio autorización previa."], "c": 2, "e": "Se reconoce el derecho de reunión pacífica y sin armas; su ejercicio no necesitará autorización previa.", "r": "CE art. 21.1 · batería oficial, pregunta 8"}, {"id": "ehu009", "q": "Según la Constitución, en torno al medio ambiente:", "o": ["Se encuentra reconocido como Derecho en el artículo 44 de la Constitución.", "La Constitución no impone el deber de conservarlo.", "El derecho a disfrutarlo es fundamental para las personas.", "Todas las personas tienen derecho a disfrutar de un medio ambiente adecuado para el desarrollo de la persona."], "c": 3, "e": "Todos tienen el derecho a disfrutar de un medio ambiente adecuado para el desarrollo de la persona, así como el deber de conservarlo. Está en el art. 45, no en el 44.", "r": "CE art. 45.1 · batería oficial, pregunta 9"}, {"id": "ehu010", "q": "De acuerdo con el artículo 44 de la Constitución, los poderes públicos:", "o": ["Promoverán la ciencia y la investigación científica y técnica.", "Admitirán la federación de Comunidades Autónomas.", "No sancionarán los atentados contra el patrimonio histórico, cultural y artístico.", "Ninguna de las opciones anteriores es correcta."], "c": 0, "e": "Los poderes públicos promoverán la ciencia y la investigación científica y técnica en beneficio del interés general.", "r": "CE art. 44.2 · batería oficial, pregunta 10"}, {"id": "ehu011", "q": "De conformidad con el artículo 82 de la Constitución, los decretos legislativos son:", "o": ["Normas con fuerza de ley dictadas por el Gobierno.", "Disposiciones legislativas provisionales.", "Disposiciones legislativas que cubren supuestos de urgente necesidad.", "Disposiciones legislativas dictadas por el Rey y convalidadas posteriormente por el Congreso."], "c": 0, "e": "Los decretos legislativos son normas con rango de ley dictadas por el Gobierno por delegación de las Cortes. Las opciones b y c describen los decretos-leyes.", "r": "CE art. 82 y 85 · batería oficial, pregunta 11"}, {"id": "ehu012", "q": "Señale la afirmación correcta según el artículo 6 del Estatuto de autonomía del País Vasco:", "o": ["El euskera es lengua propia del Pueblo Vasco y es oficial junto al castellano.", "El euskera y el castellano son lenguas propias del País Vasco y ambas oficiales.", "El castellano es lengua propia del País Vasco, y será, además del euskera, oficial.", "Ninguna de las afirmaciones anteriores es correcta."], "c": 0, "e": "El euskera, lengua propia del Pueblo Vasco, tendrá, como el castellano, carácter de lengua oficial en Euskadi.", "r": "EAPV art. 6.1 · batería oficial, pregunta 12"}, {"id": "ehu013", "q": "Según LO establecido en el artículo 1 del Estatuto de autonomía del País Vasco, ¿Cuál o cuáles son las normas institucionales básicas del pueblo Vasco o euskal herria?", "o": ["La Constitución.", "ElEstatuto.", "La Ley de Territorios Históricos y la Ley Básica de Normalización Lingüística.", "La Ley del Parlamento Vasco y La Ley de Ordenación del Territorio."], "c": 1, "e": "El Pueblo Vasco se constituye en Comunidad Autónoma de acuerdo con la Constitución y con el Estatuto, que es su norma institucional básica.", "r": "EAPV art. 1 · batería oficial, pregunta 13"}, {"id": "ehu014", "q": "De conformidad con LO establecido en el artículo 9 del Estatuto de autonomía del País Vasco, ¿Quién velará y garantizará el adecuado ejercicio: De los derechos y deberes fundamentales de los/as ciudadanos/as del País Vasco?", "o": ["El Lehendakari.", "Los poderes públicos vascos.", "El Parlamento Vasco.", "El Ararteko."], "c": 1, "e": "Los poderes públicos vascos, en el ámbito de su competencia, velarán y garantizarán el adecuado ejercicio de los derechos y deberes fundamentales.", "r": "EAPV art. 9.2.a · batería oficial, pregunta 14"}, {"id": "ehu015", "q": "DE ACUERDO CON EL ESTATUTO DE AUTONOMÍA DEL PAÍS VASCO, CORRESPONDE A LA COMUNIDAD AUTONOMA LA EJECUCIÓN DE LA LEGISLACIÓN DEL ESTADO EN: e) Propiedad intelectual e industrial. f) Legislación penitenciaria. 8) Legislación laboral.", "o": ["Propiedad intelectual e industrial.", "Legislación penitenciaria.", "Legislación laboral.", "Todas las opciones anteriores son correctas."], "c": 3, "e": "Corresponde a la CAPV la ejecución de la legislación del Estado en legislación penitenciaria, legislación laboral y propiedad intelectual e industrial, entre otras.", "r": "EAPV art. 12 · batería oficial, pregunta 15"}, {"id": "ehu016", "q": "Según el Estatuto de autonomía del País Vasco, la Real academia de la lengua vasca euskaltzaindia es:", "o": ["Institución del Gobierno Vasco para servir de archivo oficial del euskera.", "Institución consultiva oficial en lo referente al Euskera.", "Institución oficial de estudio, análisis e investigación del euskera.", "Institución cultural oficial del Gobierno Vasco para el desarrollo e impulso del E.uskera."], "c": 1, "e": "La Real Academia de la Lengua Vasca-Euskaltzaindia es institución consultiva oficial en lo referente al euskera.", "r": "EAPV art. 6.4 · batería oficial, pregunta 16"}, {"id": "ehu017", "q": "Según el Estatuto de autonomía del País Vasco, las competencias de desarrollo legislativo y ejecución son materias:", "o": ["En las que al Estado corresponde la fijación de las normas básicas y a la Comunidad Autónoma el desarrollo legislativo.", "En las que al Estado corresponde la fijación de las normas básicas y al Territorio Histórico el desarrollo legislativo y ejecución.", "En las que el Estado no tiene ninguna competencia y, por tanto, corresponde al Gobierno Vasco el desarrollo normativo y ejecución.", "En las que a la Comunidad Autónoma corresponde la fijación de las bases generales y a los Territorios Históricos el desarrollo normativo."], "c": 0, "e": "En estas materias el Estado fija las bases y la Comunidad Autónoma asume el desarrollo legislativo y la ejecución.", "r": "EAPV art. 11 · batería oficial, pregunta 17"}, {"id": "ehu018", "q": "En materia de investigación científica y técnica la comunidad autónoma del País Vasco tiene competencia:", "o": ["Exclusiva en coordinación con el Estado.", "Absoluta en coordinación con el Estado.", "De desarrollo legislativo y de ejecución dentro de su territorio de la legislación básica del Estado.", "Ejecutiva."], "c": 0, "e": "La investigación científica y técnica es competencia exclusiva de la CAPV en coordinación con el Estado.", "r": "EAPV art. 10.16 · batería oficial, pregunta 18"}, {"id": "ehu019", "q": "El Tribunal Vasco de cuentas públicas depende directamente de:", "o": ["De las Juntas Generales de los tres Territorios Históricos.", "Del Parlamento Vasco.", "Del Gobierno Vasco.", "Del Departamento de Hacienda y Economía del Gobierno Vasco."], "c": 1, "e": "El Tribunal Vasco de Cuentas Públicas depende directamente del Parlamento Vasco.", "r": "Ley 1/1988 TVCP art. 1 · batería oficial, pregunta 19"}, {"id": "ehu020", "q": "De acuerdo con la Ley 12/2002, de 23 de mayo, por la que se aprueba el concierto económico con la comunidad autónoma del País Vasco, el impuesto sobre sociedades es:", "o": ["Un tributo concertado de normativa autónoma para los sujetos pasivos que tengan su domicilio fiscal en el País Vasco.", "Una competencia exclusiva del Estado.", "Un tributo concertado de normativa común para aquellas sociedades que operen exclusivamente en territorio vasco.", "El Concierto Económico no considera el Impuesto sobre Sociedades como ámbito de aplicación."], "c": 0, "e": "El Impuesto sobre Sociedades es un tributo concertado de normativa autónoma para los sujetos pasivos con domicilio fiscal en el País Vasco (con las reglas de volumen de operaciones).", "r": "Concierto Económico (Ley 12/2002) art. 14 · batería oficial, pregunta 20"}, {"id": "ehu021", "q": "Señale la respuesta incorrecta. El Reglamento europeo:", "o": ["Es obligatorio en todos sus elementos.", "Es directamente aplicable en cada Estado Miembro.", "Es obligatorio para el Estados miembro destinatario en cuanto al resultado que deba conseguirse.", "Tiene alcance general."], "c": 2, "e": "Obligar al destinatario solo en cuanto al resultado es propio de la directiva, no del reglamento.", "r": "TFUE art. 288 · batería oficial, pregunta 21"}, {"id": "ehu022", "q": "EL CONSEJO EUROPEO: e) Ejercerá juntamente con el Parlamento Europeo la función legislativa y la función presupuestaria.", "o": ["Ejercerá juntamente con el Parlamento Europeo la función legislativa y la función presupuestaria.", "Dará a la Unión los impulsos necesarios para su desarrollo y definirá sus orientaciones y prioridades políticas generales.", "Supervisará la aplicación del Derecho de la Unión bajo el control del Tribunal de Justicia de la Unión Europea.", "Estará compuesto por un representante de cada Estado miembro, de rango ministerial."], "c": 1, "e": "El Consejo Europeo da a la Unión los impulsos necesarios para su desarrollo y define sus orientaciones y prioridades políticas generales.", "r": "TUE art. 15.1 · batería oficial, pregunta 22"}, {"id": "ehu023", "q": "Señale la respuesta correcta:", "o": ["El Consejo Europeo no tiene competencia legislativa.", "El Consejo Europeo estará compuesto por los Ministros de Asuntos Exteriores de los Estados miembros.", "Participará en los trabajos del Consejo Europeo el Alto Representante de la Unión para Asuntos Fiscales y Política Económica.", "El Consejo Europeo se reunirá una vez por semestre por convocatoria de su Presidente."], "c": 0, "e": "El Consejo Europeo no ejerce función legislativa. Lo componen los Jefes de Estado o de Gobierno, se reúne dos veces por semestre y participa el Alto Representante para Asuntos Exteriores y Política de Seguridad.", "r": "TUE art. 15 · batería oficial, pregunta 23"}, {"id": "ehu024", "q": "En relación con las instituciones europeas, señale la respuesta incorrecta:", "o": ["Cuando el orden del día lo exija, los miembros del Consejo Europeo podrán decidir contar, cada uno de ellos, con la asistencia de un ministro.", "Cuando la situación lo exija, el Presidente convocará una reunión extraordinaria del Consejo Europeo.", "El Consejo Europeo se pronunciará siempre por consenso.", "El Consejo Europeo elegirá a su Presidente por mayoría cualificada para un mandato de dos años y medio."], "c": 2, "e": "El Consejo Europeo se pronuncia por consenso, excepto cuando los Tratados dispongan otra cosa; por eso «siempre» es incorrecto.", "r": "TUE art. 15.3-15.5 · batería oficial, pregunta 24"}, {"id": "ehu025", "q": "Para ejercer las competencias de la Unión, las instituciones de la Unión Europea adoptarán:", "o": ["Decretos.", "Dictámenes, que serán vinculantes.", "Leyes.", "Directivas."], "c": 3, "e": "Las instituciones adoptan reglamentos, directivas, decisiones, recomendaciones y dictámenes; los dictámenes no son vinculantes.", "r": "TFUE art. 288 · batería oficial, pregunta 25"}, {"id": "ehu026", "q": "El Reglamento comunitario:", "o": ["Se integra en el Derecho Interno de cada miembro comunitario, sin que se requiera ningún otro trámite.", "No son de aplicación directa, por lo que obliga a los Estados miembros a aprobar una serie de medidas para incorporarlo a su Derecho Nacional.", "Puede dirigirse a uno a varios Estados miembros.", "Son correctas las respuestas a) y Cc)."], "c": 0, "e": "El reglamento es obligatorio en todos sus elementos y directamente aplicable en cada Estado miembro, sin necesidad de trasposición.", "r": "TFUE art. 288 · batería oficial, pregunta 26"}, {"id": "ehu027", "q": "Señale la afirmación correcta en relación con el Tribunal de justicia de la Unión Europea.", "o": ["El Tribunal de Justicia de la Unión Europea comprenderá el Tribunal de Justicia, el Tribunal General y los tribunales especializados.", "El Tribunal General estará asistido por abogados generales.", "El Tribunal de Justicia dispondrá al menos de un juez por Estado miembro.", "El Tribunal General dispondrá de un juez por Estado miembro."], "c": 0, "e": "El TJUE comprende el Tribunal de Justicia, el Tribunal General y los tribunales especializados. Los abogados generales asisten al Tribunal de Justicia.", "r": "TUE art. 19.1-19.2 · batería oficial, pregunta 27"}, {"id": "ehu028", "q": "El Tribunal de justicia de la Unión Europea se pronunciará, de conformidad con los tratados sobre los recursos interpuestos por:", "o": ["Un Estado miembro.", "Una institución.", "Por personas físicas o jurídicas.", "Las tres respuestas anteriores con correctas."], "c": 3, "e": "El TJUE se pronuncia sobre los recursos interpuestos por un Estado miembro, por una institución o por personas físicas o jurídicas.", "r": "TUE art. 19.3.a · batería oficial, pregunta 28"}, {"id": "ehu029", "q": "La aprobación de una Ley Orgánica exige:", "o": ["La mayoría simple del Congreso y del Senado reunidos en sesión conjunta.", "La mayoría de 2/3 del Congreso y la mayoría absoluta del Senado sobre el conjunto del proyecto.", "La mayoría absoluta del Congreso en una votación final sobre el conjunto del proyecto.", "La mayoría simple del Congreso, pero sólo podrá aprobarse cuando verse sobre determinadas materias relacionadas con los derechos fundamentales y las libertades públicas, la aprobación de los Estatutos de Autonomía y el régimen electoral general."], "c": 2, "e": "La aprobación, modificación o derogación de las leyes orgánicas exige mayoría absoluta del Congreso en una votación final sobre el conjunto del proyecto.", "r": "CE art. 81.2 · batería oficial, pregunta 29"}, {"id": "ehu030", "q": "Los decretos-leves:", "o": ["Son Disposiciones Legislativas provisionales emanadas por el Gobierno y dictadas en casos de extraordinaria y urgente necesidad.", "Son Disposiciones Legislativas definitivas emanadas por el Gobierno y dictadas en casos de extraordinaria y urgente necesidad.", "Son Disposiciones Legislativas emanadas por el Gobierno sobre cualquier materia excepto los derechos y libertades de los ciudadanos.", "Son Disposiciones Legislativas provisionales emanadas por el Gobierno y dictadas en casos de extraordinaria y urgente necesidad que requieren la convalidación posterior del Congreso y el Senado reunidos en sesión conjunta."], "c": 0, "e": "En caso de extraordinaria y urgente necesidad, el Gobierno puede dictar disposiciones legislativas provisionales (decretos-leyes). Los convalida solo el Congreso, no ambas cámaras.", "r": "CE art. 86 · batería oficial, pregunta 30"}, {"id": "ehu031", "q": "¿Qué tipos de interoperabilidad se distinguen en el esquema nacional de interoperabilidad (eni)?:", "o": ["Organizativa.", "Léxica.", "Técnica.", "Las respuestas a) y c) son correctas."], "c": 3, "e": "El ENI contempla las dimensiones organizativa, semántica y técnica de la interoperabilidad (además de la temporal); no existe la «léxica».", "r": "RD 4/2010 (ENI) · batería oficial, pregunta 31"}, {"id": "ehu032", "q": "En virtud del principio de reserva de lev:", "o": ["Un reglamento no puede regular determinadas materias para las cuales la Constitución exige una norma con rango de ley.", "Un reglamento no puede regular materias que, aunque la Constitución no exija para su regulación rango de ley, ya hayan sido reguladas por una norma de este rango.", "Una materia puede regularse mediante reglamento únicamente cuando haya sido recogido así en una norma habilitante con rango de ley.", "Tanto la a) como la b) son correctas."], "c": 0, "e": "La reserva de ley impide que el reglamento regule materias que la Constitución reserva a una norma con rango de ley.", "r": "CE (principio de reserva de ley) · batería oficial, pregunta 32"}]}, {"id": "b02", "sig": "Bloque 2", "titulo": "Bloque 2. Patrimonio, presupuesto y financiación universitaria", "sub": "Preguntas 33–44 de la batería oficial (sin respuestas oficiales: resueltas por Claude).", "preguntas": [{"id": "ehu033", "q": "Conforme a la Ley 33/2003, de 3 de noviembre, del patrimonio de las administraciones públicas, señale la respuesta incorrecta. La gestión y administración de los bienes y ] derechos demaniales por las administraciones publicas se ajustaran a los siguientes principios:", "o": ["Inalienabilidad.", "Inembargabilidad.", "Imprescriptibilidad.", "Dedicación preferente al uso privativo frente a su uso común."], "c": 3, "e": "El principio es la dedicación preferente al uso común frente a su uso privativo, justo al revés de lo que dice la opción d.", "r": "Ley 33/2003 art. 6.d · batería oficial, pregunta 33"}, {"id": "ehu034", "q": "Según LO establecido en la Ley 11/2022, de 1 de dciembre de empleo público Vasco, las personas empleadas públicas son responsables de la buena gestión de los servicios encomendados:", "o": ["Sin perjuicio de la responsabilidad que corresponde a sus superiores jerárquicos.", "En todo momento deberán dar cuenta de las anomalías que hubieran observado en el servicio.", "Ambas respuestas son correctas.", "Ninguna respuesta es correcta."], "c": 2, "e": "Son responsables de la buena gestión de los servicios encomendados, sin perjuicio de la responsabilidad de sus superiores, y deben dar cuenta de las anomalías observadas.", "r": "Ley 11/2022 de Empleo Público Vasco (deberes y código de conducta) · batería oficial, pregunta 34"}, {"id": "ehu035", "q": "Conforme a la Ley 33/2003, de 3 de noviembre, del patrimonio de las administraciones públicas, señale la respuesta incorrecta. La gestión y administración de los bienes y derechos patrimoniales por las administraciones públicas se ajustarán a los siguientes principios:", "o": ["Eficiencia y economía en su gestión.", "Eficacia y rentabilidad en la explotación de estos bienes y derechos.", "Publicidad, transparencia, concurrencia y objetividad en la adquisición, explotación y enajenación de estos bienes.", "Gestión y administración dirigida a la rentabilidad económica a través de transmisiones onerosas."], "c": 3, "e": "Los principios son eficiencia y economía, eficacia y rentabilidad, publicidad, transparencia, concurrencia y objetividad, identificación y control, y colaboración. No figura la rentabilidad mediante transmisiones onerosas.", "r": "Ley 33/2003 art. 8.1 · batería oficial, pregunta 35"}, {"id": "ehu036", "q": "Se considera patrimonio de la EHU:", "o": ["El conjunto de bienes cuya propiedad ostente la EHU.", "El conjunto de bienes y derechos cuya propiedad ostente la EHU.", "Elconjunto de bienes y derechos cuya propiedad o titularidad ostente la EHU y cuantos otros adquiera o le sean atribuidos en el futuro.", "El conjunto de bienes cuya propiedad ostente la EHU y cuantos adquiera en el futuro."], "c": 2, "e": "El patrimonio de la Universidad lo forman los bienes y derechos de los que es titular y cuantos otros adquiera o le sean atribuidos en el futuro.", "r": "Estatutos UPV/EHU (patrimonio); LOSU · batería oficial, pregunta 36"}, {"id": "ehu037", "q": "Además del patrimonio ya constituido podrán incorporarse:", "o": ["Las donaciones que se reciban según el procedimiento establecido por la EHU y el material inventariable que se adquiera.", "El material inventariable que se adquiera y el bibliográfico.", "Las donaciones que reciba, el material inventariable y el bibliográfico.", "Las donaciones que reciba, el material inventariable y el bibliográfico exceptuando las publicaciones periódicas."], "c": 2, "e": "Respuesta probable: se incorporan las donaciones que reciba y el material inventariable y bibliográfico que adquiera. Compruébalo en los Estatutos.", "r": "Estatutos UPV/EHU (patrimonio) · batería oficial, pregunta 37"}, {"id": "ehu038", "q": "La conservación y correcta utilización del patrimonio de la EHU incumbe a:", "o": ["Atoda la comunidad universitaria.", "Al Servicio de Patrimonio y Contratación.", "Al profesorado y PTGAS de la EHU.", "A los centros, departamentos y servicios."], "c": 0, "e": "Respuesta probable: la conservación y correcta utilización del patrimonio incumbe a toda la comunidad universitaria.", "r": "Estatutos UPV/EHU (patrimonio) · batería oficial, pregunta 38"}, {"id": "ehu039", "q": "Según la Ley 33/2003, de 3 de noviembre, del patrimonio de las administraciones públicas, el uso privativo de los bienes de dominio público:", "o": ["Determina la ocupación de una porción del dominio público, de modo que se limita o excluye la utilización del mismo por otros interesados.", "Puede determinar la ocupación con obras o instalaciones fijas sin concesión administrativa.", "Noes posible el uso privativo de los bienes de dominio público.", "Corresponde por igual y de forma indistinta a todos los ciudadanos, de modo que el uso por unos no impide el de los demás interesados."], "c": 0, "e": "El uso privativo es el que determina la ocupación de una porción del dominio público, de modo que se limita o excluye su utilización por otros interesados.", "r": "Ley 33/2003 art. 85.3 · batería oficial, pregunta 39"}, {"id": "ehu040", "q": "Según la Ley 33/2003, de 3 de noviembre, del patrimonio de las administraciones públicas, el aprovechamiento especial de los bienes de dominio público, así como su uso privativo cuando la ocupación se efectúe únicamente con instalaciones desmontables:", "o": ["Es un aprovechamiento especial sujeto a concesión si la duración del aprovechamiento o uso excede de un año.", "Estarán sujetos a autorización o, si la duración del aprovechamiento o uso excede de cuatro años, a concesión.", "Deberá estar amparado por la correspondiente concesión administrativa.", "Podrá realizarse libremente, sin más limitaciones que las derivadas de su naturaleza."], "c": 1, "e": "Están sujetos a autorización o, si la duración excede de cuatro años, a concesión.", "r": "Ley 33/2003 art. 86.2 · batería oficial, pregunta 40"}, {"id": "ehu041", "q": "Los precios públicos de las enseñanzas universitarias oficiales los fijará:", "o": ["El Consejo de Gobierno de la universidad para las titulaciones que imparta.", "El Ministerio de Educación y Formación Profesional.", "La Comunidad Autónoma.", "El Consejo Social de la universidad."], "c": 2, "e": "Los precios públicos de las enseñanzas oficiales los fija la Comunidad Autónoma, dentro de los límites que establezca la Conferencia General de Política Universitaria.", "r": "LOSU (LO 2/2023) art. 10 y DA · batería oficial, pregunta 41"}, {"id": "ehu042", "q": "La LOSU reconoce a la Universidad como agente clave en:", "o": ["La regulación del mercado laboral.", "La gestión sanitaria.", "La transferencia del conocimiento y la ciencia abierta.", "La universidad facilitará la compatibilidad en el ejercicio de la docencia y la investigación."], "c": 2, "e": "La LOSU sitúa a la universidad como agente clave de la transferencia del conocimiento y la ciencia abierta.", "r": "LOSU (LO 2/2023), preámbulo y Título I · batería oficial, pregunta 42"}, {"id": "ehu043", "q": "¿Qué busca la LOSU al fomentar la cooperación entre universidades?", "o": ["Competencia por recursos.", "Reducción de la oferta académica.", "Sinergias en docencia, investigación e innovación.", "Centralización de todos los servicios."], "c": 2, "e": "Fomenta la cooperación para generar sinergias en docencia, investigación e innovación.", "r": "LOSU (LO 2/2023) · batería oficial, pregunta 43"}, {"id": "ehu044", "q": "¿Qué principio rige la financiación universitaria según LOSU?", "o": ["Competencia directa entre universidades.", "Financiación exclusivamente por matrícula.", "Financiación suficiente, estable y plurianual.", "Financiación condicionada a rankings internacionales."], "c": 2, "e": "La LOSU establece un modelo de financiación suficiente, estable y plurianual.", "r": "LOSU (LO 2/2023) art. 55 · batería oficial, pregunta 44"}]}, {"id": "b03", "sig": "Bloque 3", "titulo": "Bloque 3. Procedimiento administrativo y régimen jurídico", "sub": "Preguntas 45–80 de la batería oficial (sin respuestas oficiales: resueltas por Claude).", "preguntas": [{"id": "ehu045", "q": "Según la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el ejercicio de la potestad reglamentaria corresponde:", "o": ["Al Gobierno de la Nación, a los órganos de Gobierno de las Comunidades Autónomas y a los órganos de gobierno locales.", "Al Gobierno de la Nación y a los órganos de Gobierno de las Comunidades Autónomas, pero no a los órganos de gobiernos locales.", "Exclusivamente al Gobierno de la Nación.", "Solo al Gobierno de la Nación y a las Cortes Generales."], "c": 0, "e": "La potestad reglamentaria corresponde al Gobierno de la Nación, a los órganos de gobierno de las CCAA y a los órganos de gobierno locales.", "r": "Ley 39/2015 art. 128.1 · batería oficial, pregunta 45"}, {"id": "ehu046", "q": "Respeto a la potestad reglamentaria, señale la respuesta incorrecta:", "o": ["Los reglamentos y disposiciones administrativas no podrán tipificar delitos, faltas o infracciones administrativas, establecer penas o sanciones.", "Los reglamentos y disposiciones administrativas no podrán establecer tributos, exacciones parafiscales u otras cargas o prestaciones personales o patrimoniales de carácter público.", "Los reglamentos y disposiciones administrativas pueden establecer nuevas normativas sobre cualquier materia si cuentan con la ratificación del Consejo General del Poder Judicial.", "Ninguna disposición administrativa podrá vulnerar los preceptos de otra de rango superior."], "c": 2, "e": "Los reglamentos no pueden vulnerar la Constitución ni las leyes; no existe ninguna ratificación del CGPJ que les permita regular cualquier materia.", "r": "Ley 39/2015 art. 128.2-3 · batería oficial, pregunta 46"}, {"id": "ehu047", "q": "Señale cuál de estas afirmaciones es correcta:", "o": ["La encomienda de gestión, la delegación de firma y la suplencia no suponen alteración de la titularidad de la competencia.", "Cuando se produzca una delegación de competencias a favor de un órgano no jerárquicamente dependiente del delegante, tanto el órgano delegante como los superiores jerárquicos del delegado podrán avocar para sí el conocimiento del asunto.", "Contra el acuerdo de avocación podrá interponerse recurso de alzada ante el superior jerárquico del órgano que ejercita la misma.", "Los titulares de los órganos administrativos podrán ser suplidos temporalmente en los supuestos de ausencia o enfermedad por quien designe el órgano que va a ser suplido."], "c": 0, "e": "La encomienda de gestión, la delegación de firma y la suplencia no alteran la titularidad de la competencia. Contra la avocación no cabe recurso.", "r": "Ley 40/2015 arts. 8-13 · batería oficial, pregunta 47"}, {"id": "ehu048", "q": "Según la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común, ¿Cuál de los siguientes no tiene la consideración de persona interesada en el procedimiento administrativo?", "o": ["Quienes lo promuevan como titulares de derechos o intereses legítimos individuales o colectivos.", "Aquellos/as cuyos intereses legítimos, individuales o colectivos, puedan resultar afectados por la resolución y se personen en el procedimiento en tanto no haya recaído resolución definitiva.", "Los/as que, sin haber iniciado el procedimiento, tengan derechos que puedan resultar afectados por la instrucción que en el mismo se adopte y comparezcan, exclusivamente de forma personal, ante la autoridad competente.", "Todas las respuestas son incorrectas."], "c": 2, "e": "Son interesados quienes tengan derechos que puedan resultar afectados por la decisión (no la instrucción) que se adopte, aunque no hayan iniciado el procedimiento.", "r": "Ley 39/2015 art. 4.1 · batería oficial, pregunta 48"}, {"id": "ehu049", "q": "Según la Ley 39/2015, de 1 de octubre, de procedimiento administrativo común, con respecto a la ordenación del procedimiento, cuando en virtud de una norma sea preciso remitir el expediente electrónico:", "o": ["Se hará de acuerdo con las características y medios disponibles del empleado/a público/a que lo tramite.", "No es necesario en su tramitación que vaya acompañado del índice.", "Se hará de acuerdo con lo previsto en el Esquema Nacional de Interoperabilidad y en las correspondientes normas técnicas de interoperabilidad y se enviará completo, foliado, autentificado y acompañado de un índice, así mismo autenticado, de los documentos que contenga.", "Ninguna de las anteriores es correcta."], "c": 2, "e": "El expediente electrónico se remite según el ENI, completo, foliado, autentificado y con un índice autenticado.", "r": "Ley 39/2015 art. 70.3 · batería oficial, pregunta 49"}, {"id": "ehu050", "q": "Las nuevas obligaciones introducidas por la Ley 39/2015, de 1 de octubre, del procedimiento administrativo comun de las administraciones publicas y por la Ley 40/2015, de 1 de octubre, de regimen juridico del sector publico se pueden resumir en:", "o": ["Garantizar la seguridad en la tramitación electrónica.", "Tramitar electrónicamente los expedientes.", "Garantizar la agilidad en la tramitación.", "Ninguna de las respuestas anteriores es correcta."], "c": 1, "e": "Respuesta probable: la gran novedad de ambas leyes es la tramitación electrónica de los expedientes como regla general.", "r": "Leyes 39/2015 y 40/2015, preámbulos · batería oficial, pregunta 50"}, {"id": "ehu051", "q": "El derecho y obligación de relacionarse electrónicamente con la administración, viene recogido en el:", "o": ["Art. 14 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, y por la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público.", "Art. 14 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público.", "Art. 15 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, y por la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público.", "Ninguna de las respuestas anteriores es correcta."], "c": 0, "e": "El derecho y la obligación de relacionarse electrónicamente con las Administraciones se regula en el art. 14 de la Ley 39/2015.", "r": "Ley 39/2015 art. 14 · batería oficial, pregunta 51"}, {"id": "ehu052", "q": "Según la Ley 39/2015, de 1 de octubre, de procedimiento administrativo común, pondrán fin al procedimiento administrativo:", "o": ["La resolución y el desistimiento.", "La imposibilidad material de continuarlo por causas sobrevenidas. La resolución que se dicte deberá ser motivada en todo caso.", "La renuncia al derecho en que se funde la solicitud, cuando tal renuncia no esté prohibida por el ordenamiento jurídico y la declaración de caducidad.", "Todas las anteriores son correctas."], "c": 3, "e": "Ponen fin al procedimiento la resolución, el desistimiento, la renuncia, la declaración de caducidad y la imposibilidad material de continuarlo por causas sobrevenidas.", "r": "Ley 39/2015 art. 84 · batería oficial, pregunta 52"}, {"id": "ehu053", "q": "Según la Ley 39/2015, de 1 de octubre, de procedimiento administrativo comun, ¿Donde deben las administraciones publicas publicar y mantener actualizadas a efectos informativos las relaciones de procedimientos de su competencia con indicación de los plazos máximos de duración de los mismos, asi como de los efectos que produzca el silencio administrativo?", "o": ["En sus portales web.", "En el Boletín Oficial del Estado.", "En el Boletín Oficial que corresponda.", "En sus portales web y en el Boletín Oficial que corresponda."], "c": 0, "e": "Las Administraciones publican y mantienen actualizadas en su portal web las relaciones de procedimientos con su plazo máximo y el efecto del silencio.", "r": "Ley 39/2015 art. 21.4 · batería oficial, pregunta 53"}, {"id": "ehu054", "q": "Según el artículo 23 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, son motivos de abstención:", "o": ["Tener interés personal en el asunto de que se trate o en otro en cuya resolución pudiera influir la de aquél.", "Ser administrador de sociedad o entidad interesada.", "Tener cuestión litigiosa pendiente con algún interesado.", "Todas las opciones anteriores son correctas."], "c": 3, "e": "Son motivos de abstención, entre otros, el interés personal, ser administrador de sociedad interesada y tener cuestión litigiosa pendiente con algún interesado.", "r": "Ley 40/2015 art. 23.2 · batería oficial, pregunta 54"}, {"id": "ehu055", "q": "Según la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuál de los siguientes requisitos exigirá la creación de cualquier órgano administrativo:", "o": ["Determinación de su forma de integración en la Administración Pública de que se trate y su dependencia jerárquica.", "Delimitación de sus funciones y competencias.", "Dotación de los créditos necesarios para su puesta en marcha y funcionamiento.", "Todas las opciones anteriores son correctas."], "c": 3, "e": "La creación de un órgano exige determinar su integración y dependencia, delimitar sus funciones y competencias y dotarlo de los créditos necesarios.", "r": "Ley 40/2015 art. 5.3 · batería oficial, pregunta 55"}, {"id": "ehu056", "q": "De acuerdo con el artículo 9 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, los órganos de la administración general del estado podrán delegar el ejercicio de sus competencias propias en sus organismos públicos y entidades vinculados o de pendientes:", "o": ["Cuando resulte conveniente para alcanzar los fines que tengan asignados y mejorar la eficacia de su gestión.", "Para mejorar la eficacia de gestión de su personal.", "Los órganos de las diferentes Administraciones Públicas no podrán delegar el ejercicio de las competencias que tengan atribuidas.", "Cuando se trate de competencias relativas a la adopción de disposiciones de carácter general."], "c": 0, "e": "Pueden delegar en sus organismos públicos vinculados o dependientes cuando resulte conveniente para alcanzar sus fines y mejorar la eficacia de su gestión.", "r": "Ley 40/2015 art. 9.1 · batería oficial, pregunta 56"}, {"id": "ehu057", "q": "De acuerdo con LO establecido en el artículo 103 de la Ley 40/2015 de régimen jurídico del sector público, las entidades públicas empresariales de ámbito estatal son entidades:", "o": ["Que no tienen personalidad jurídica propia.", "De Derecho público.", "Que no dependen de la Administración General del Estado o de un Organismo autónomo vinculado o dependiente de ésta.", "Que no desarrollan actividades prestacionales, de gestión de servicios o de producción de bienes de interés público."], "c": 1, "e": "Son entidades de Derecho público, con personalidad jurídica propia, que dependen de la AGE o de un organismo autónomo.", "r": "Ley 40/2015 art. 103.1 · batería oficial, pregunta 57"}, {"id": "ehu058", "q": "De conformidad con LO establecido en el artículo 35 de la Ley 39/2015, de 1 de octubre, de procedimiento administrativo comun, no necesitan necesariamente ser motivados:", "o": ["Los acuerdos de suspensión de actos.", "Los actos sancionadores.", "Los actos que se separen del dictamen de un órgano consultivo.", "Los actos favorables para los interesados."], "c": 3, "e": "El art. 35 obliga a motivar los actos que limitan derechos, los sancionadores, los de suspensión o los que se apartan de dictámenes, entre otros; los actos favorables no figuran.", "r": "Ley 39/2015 art. 35.1 · batería oficial, pregunta 58"}, {"id": "ehu059", "q": "La jubilación del personal funcionario no podrá ser:", "o": ["Voluntaria.", "Parcial con contrato de relevo.", "Forzosa, al cumplir la edad legalmente establecida.", "Por declaración de una incapacidad."], "c": 1, "e": "El contrato de relevo es una figura del personal laboral; la jubilación del funcionariado puede ser voluntaria, forzosa o por incapacidad permanente.", "r": "TREBEP art. 67 · batería oficial, pregunta 59"}, {"id": "ehu060", "q": "Según la Ley 39/2015, de 1 de octubre, de procedimiento administrativo común, ¿En qué momento del procedimiento pueden elegir las personas físicas si se comunican con las administraciones publicas para el ejercicio de sus derechos y obligaciones a traves de medios electrónicos?", "o": ["Mientras el procedimiento se encuentre en la fase de ordenación.", "Antes de la finalización de la instrucción", "Antes del trámite de audiencia.", "En todo momento."], "c": 3, "e": "Las personas físicas pueden elegir en todo momento si se comunican con la Administración por medios electrónicos o no.", "r": "Ley 39/2015 art. 14.1 · batería oficial, pregunta 60"}, {"id": "ehu061", "q": "El mantenimiento del registro general de la EHU es función de", "o": ["La Secretaría o Secretario General.", "La Rectora o Rector.", "Los/as jefes de servicio correspondientes.", "Los Vicerrectorados de Campus."], "c": 0, "e": "Respuesta probable: la Secretaría General tiene encomendada la custodia y el mantenimiento del Registro General.", "r": "Estatutos UPV/EHU (Secretaría General) · batería oficial, pregunta 61"}, {"id": "ehu062", "q": "La tramitación simplificada del procedimiento podrá ser acordada por las administraciones publicas", "o": ["De oficio, cuando la falta de complejidad del procedimiento así lo aconsejen.", "De oficio, cuando razones de interés público así lo aconsejen.", "De oficio o a solicitud del interesado, cuando la falta de complejidad del procedimiento así lo aconsejen.", "De oficio o a solicitud del interesado, cuando razones de interés público o la falta de complejidad del procedimiento así lo aconsejen."], "c": 3, "e": "La tramitación simplificada puede acordarse de oficio o a solicitud del interesado cuando razones de interés público o la falta de complejidad lo aconsejen.", "r": "Ley 39/2015 art. 96.1 · batería oficial, pregunta 62"}, {"id": "ehu063", "q": "Según LO dispuesto en la Ley 39/2015, de 1 de octubre, de procedimiento administrativo común, como regla general, señale en qué lengua se tramitarán los procedimientos administrativos por parte de la EHU.", "o": ["En castellano.", "En castellano y en las demás lenguas cooficiales.", "En este supuesto el uso de la lengua se ajustará a lo previsto en la legislación autonómica correspondiente.", "En este supuesto el uso de la lengua será elegido por la EHU."], "c": 2, "e": "En los procedimientos de las Administraciones autonómicas y locales, el uso de la lengua se ajusta a lo previsto en la legislación autonómica correspondiente.", "r": "Ley 39/2015 art. 15.1 · batería oficial, pregunta 63"}, {"id": "ehu064", "q": "Desde que se dictó el acto administrativo, la declaración de lesividad no podra adoptarse una vez transcurrido:", "o": ["3meses.", "1año.", "2años.", "4años."], "c": 3, "e": "La declaración de lesividad no puede adoptarse una vez transcurridos cuatro años desde que se dictó el acto.", "r": "Ley 39/2015 art. 107.2 · batería oficial, pregunta 64"}, {"id": "ehu065", "q": "El recurso extraordinario de revisión se interpondrá dentro de un plazo de 4 años siguientes a la fecha de la notificación de la resolución impugnada cuando:", "o": ["Al dictarlos se hubiera incurrido en error de hecho, que resulte de los propios documentos incorporados al expediente.", "Aparezcan documentos de valor esencial para la resolución del asunto que, aunque sean posteriores, evidencie el error de la resolución recurrida.", "En la resolución hayan influido esencialmente documentos o testimonios declarados falsos por sentencia judicial firme, anterior o posterior a aquella resolución.", "La resolución se hubiera dictado como consecuencia de prevaricación, cohecho, violencia, maquinación fraudulenta u otra conducta punible y se haya declarado así en virtud de sentencia judicial firme."], "c": 0, "e": "El plazo de cuatro años es solo para el error de hecho que resulte de los documentos del expediente; en los demás casos es de tres meses.", "r": "Ley 39/2015 art. 125.2 · batería oficial, pregunta 65"}, {"id": "ehu066", "q": "Ante las administraciones públicas, podrán actuar en representación de otras:", "o": ["Las personas físicas con o sin capacidad de obrar y las personas jurídicas, aunque no esté previsto en sus Estatutos.", "Las personas físicas con capacidad de obrar y las personas jurídicas, siempre que ello esté previsto en sus Estatutos.", "Las personas físicas con capacidad de obrar y las personas jurídicas, siempre que ello no esté previsto en sus Estatutos.", "Las personas físicas con o sin capacidad de obrar y las personas jurídicas, siempre que ello esté previsto en sus Estatutos"], "c": 1, "e": "Puede representar cualquier persona física con capacidad de obrar y las personas jurídicas, siempre que ello esté previsto en sus Estatutos.", "r": "Ley 39/2015 art. 5.2 · batería oficial, pregunta 66"}, {"id": "ehu067", "q": "La interposición de un recurso deberá expresar:", "o": ["El nombre y apellidos del recurrente, así como la identificación personal del mismo, junto con el acto que se recurre y la razón de su impugnación.", "Lugar, fecha, firma del recurrente, identificación del medio y, en su caso, del lugar que se señale a efectos de notificaciones, así como el órgano, centro o unidad administrativa al que se dirige y su correspondiente código de identificación.", "Las demás particularidades exigidas, su caso, por las disposiciones específicas.", "Todas las opciones anteriores son correctas."], "c": 3, "e": "El escrito de recurso debe expresar todos esos datos: recurrente, acto recurrido y motivo, lugar, fecha, firma, medio de notificación, órgano al que se dirige y demás particularidades.", "r": "Ley 39/2015 art. 115.1 · batería oficial, pregunta 67"}, {"id": "ehu068", "q": "Según la Ley 39/2015, de 1 de octubre, de procedimiento administrativo común, los registros electrónicos de todas y cada una de las administraciones deben cumplir una característica esencial:", "o": ["Que sean técnicamente intercambiables, de modo que se garantice su compatibilidad informática e interconexión, así como la transmisión telemática de los asientos registrales y de los documentos que se presenten en cualquiera de los registros.", "Que deberán ser plenamente interoperables, de modo que se garantice su compatibilidad informática e interconexión, así como la transmisión telemática de los asientos registrales y de los documentos que se presenten en cualquiera de los registros.", "Que sean plenamente interoperables, con independencia de su compatibilidad informática", "Que estén normalizados según la norma UNE-EN ISO 19160-4:2017."], "c": 1, "e": "Los registros electrónicos deben ser plenamente interoperables, garantizando su compatibilidad informática, su interconexión y la transmisión telemática de asientos y documentos.", "r": "Ley 39/2015 art. 16.4 · batería oficial, pregunta 68"}, {"id": "ehu069", "q": "De acuerdo con la Ley 39/2015 PAC, de 1 de octubre, de procedimiento administrativo comun, ¿En qué procedimiento — tienen las administraciones públicas obligación de resolver?", "o": ["Especialmente en todos los procedimientos que se inicien de oficio por denuncia.", "Como regla general, en todos los procedimientos que se inicien de oficio.", "En todos los procedimientos cualquiera que sea su forma de iniciación.", "Sólo en los procedimientos sancionadores, con independencia de su forma de finalización."], "c": 2, "e": "La Administración está obligada a dictar resolución expresa en todos los procedimientos, cualquiera que sea su forma de iniciación.", "r": "Ley 39/2015 art. 21.1 · batería oficial, pregunta 69"}, {"id": "ehu070", "q": "Según el artículo 40 de la Ley 39/2015, de 1 de octubre, de procedimiento administrativo comun, ¿Cual es el plazo de notificación de los actos administrativos desde que son dictados?", "o": ["Tdías.", "10días.", "15 días", "20días."], "c": 1, "e": "La notificación debe cursarse en el plazo de diez días desde que se dictó el acto.", "r": "Ley 39/2015 art. 40.2 · batería oficial, pregunta 70"}, {"id": "ehu071", "q": "Según el artículo 41 de la Ley 39/2015, de 1 de octubre, de procedimiento administrativo comun, las notificaciones se practicarán preferentemente:", "o": ["Porla vía postal.", "Porla vía telefónica.", "Por medios electrónicos.", "Por el medio más rápido y económico para la Administración."], "c": 2, "e": "Las notificaciones se practicarán preferentemente por medios electrónicos.", "r": "Ley 39/2015 art. 41.1 · batería oficial, pregunta 71"}, {"id": "ehu072", "q": "Según la Ley 39/2015, de 1 de octubre, de procedimiento administrativo comun, las resoluciones administrativas que vulneren LO establecido en una disposición reglamentaria son:", "o": ["Válidas.", "Nulas.", "Anulables.", "Convalidables."], "c": 1, "e": "Son nulas las resoluciones administrativas que vulneren lo establecido en una disposición reglamentaria.", "r": "Ley 39/2015 art. 37.2 · batería oficial, pregunta 72"}, {"id": "ehu073", "q": "Según el artículo 21 de la Ley 39/2015, de 1 de octubre, de procedimiento administrativo común, ¿Cual es el plazo de notificación de la resolución expresa, si el procedimiento tiene norma reguladora específica pero no fija el plazo?", "o": ["En el plazo fijado por la norma reguladora específica de una materia afín.", "En el plazo de 3 meses.", "En el plazo de 6 meses.", "En el plazo de 1 año."], "c": 1, "e": "Si la norma reguladora no fija plazo máximo, este será de tres meses.", "r": "Ley 39/2015 art. 21.3 · batería oficial, pregunta 73"}, {"id": "ehu074", "q": "Según la Ley 39/2015, de 1 de octubre, de procedimiento administrativo común, los actos administrativos producidos por silencio administrativo pueden hacerse valer ante:", "o": ["Exclusivamente ante la Administración instructora del expediente.", "Ante la Administración, así como ante cualquier persona física o jurídica, pública o privada.", "Sólo ante personas físicas.", "Sólo ante personas físicas o jurídicas públicas."], "c": 1, "e": "Los actos producidos por silencio pueden hacerse valer ante la Administración y ante cualquier persona física o jurídica, pública o privada.", "r": "Ley 39/2015 art. 24.4 · batería oficial, pregunta 74"}, {"id": "ehu075", "q": "El artículo 35 de la Ley 39/2015, de 1 de octubre, de procedimiento administrativo común, establece que serán motivados, con sucinta referencia de hechos y fundamentos de derecho:", "o": ["Los que resuelvan procedimientos de revisión de oficio de disposiciones o actos administrativos.", "Los que resuelvan recursos administrativos.", "Los que resuelvan procedimientos de arbitraje.", "Todas las anteriores son correctas."], "c": 3, "e": "Deben motivarse, entre otros, los actos que resuelvan procedimientos de revisión de oficio, recursos administrativos y procedimientos de arbitraje.", "r": "Ley 39/2015 art. 35.1.b · batería oficial, pregunta 75"}, {"id": "ehu076", "q": "Según el artículo 27 de la Ley 39/2015, de 1 de octubre, de procedimiento administrativo común, las copias autenticadas realizadas por una administración pública.", "o": ["Surten únicamente efectos administrativos.", "No tendrán ningún efecto administrativo.", "Únicamente tendrán validez en la misma Administración que ha realizado la autenticación.", "Tendrán validez en las restantes Administraciones, siempre que así lo hayan acordado por Resolución del órgano competente."], "c": 3, "e": "Respuesta probable. La ley dice que las copias auténticas de una Administración tienen validez en las restantes Administraciones; d es la opción más próxima.", "r": "Ley 39/2015 art. 27.1 · batería oficial, pregunta 76"}, {"id": "ehu077", "q": "La comparecencia de los/as ciudadanos/as ante las oficinas públicas, ya sea presencialmente o por medios electrónicos, sólo será obligatoria:", "o": ["Cuando razones de interés público así lo aconsejen.", "Cuando esté previsto en una norma con rango de Ley.", "Cuando se crea oportuno para resolver un expediente.", "Nunca."], "c": 1, "e": "La comparecencia solo es obligatoria cuando así esté previsto en una norma con rango de ley.", "r": "Ley 39/2015 art. 19.1 · batería oficial, pregunta 77"}, {"id": "ehu078", "q": "¿Cuándo se entiende practicada una notificación de un acto administrativo por medios electrónicos?", "o": ["Cuando se reciba en la bandeja de entrada del correo electrónico de la persona interesada.", "Cuando se produzca el acceso a su contenido mediante comparecencia en la sede electrónica de la Administración u Organismo actuante.", "Cuando se curse desde cualquiera de las aplicaciones informáticas de la Administración u Organismo actuante.", "Ninguna de las anteriores es correcta."], "c": 1, "e": "La notificación electrónica se entiende practicada cuando se accede a su contenido mediante comparecencia en la sede electrónica.", "r": "Ley 39/2015 art. 43.2 · batería oficial, pregunta 78"}, {"id": "ehu079", "q": "La responsabilidad sobre la gestión de una sede electrónica corresponde:", "o": ["A su titular.", "Al usuario que accede.", "A cualquier órgano administrativo.", "A empresas tecnológicas externas."], "c": 0, "e": "La titularidad de la sede electrónica conlleva la responsabilidad sobre la integridad, veracidad y actualización de la información y los servicios.", "r": "Ley 40/2015 art. 38.2 · batería oficial, pregunta 79"}, {"id": "ehu080", "q": "Serán nulas de pleno derecho las disposiciones administrativas (señale la opción incorrecta):", "o": ["Que vulneren la Constitución.", "Que vulneren las leyes u otras disposiciones administrativas de rango superior.", "Que regulen materias reservadas a la Ley.", "Que establezcan la retroactividad de disposiciones sancionadoras favorables y no restrictivas de derechos individuales."], "c": 3, "e": "Son nulas las que establezcan la retroactividad de disposiciones sancionadoras no favorables o restrictivas de derechos; la opción d dice lo contrario.", "r": "Ley 39/2015 art. 47.2 · batería oficial, pregunta 80"}]}, {"id": "b04", "sig": "Bloque 4", "titulo": "Bloque 4. Empleo público vasco", "sub": "Preguntas 81–100 de la batería oficial (sin respuestas oficiales: resueltas por Claude).", "preguntas": [{"id": "ehu081", "q": "Según la Ley de empleo público Vasco, si a un funcionario interino se le nombra por la existencia de una plaza vacante ésta deberá incluirse, en un principio en:", "o": ["La oferta pública de empleo del ejercicio siguiente al que se produce su nombramiento.", "La oferta pública de empleo del ejercicio en el que se produce su nombramiento.", "Sino es posible incluirla en la del ejercicio en el que se produce su nombramiento se tiene que amortizar.", "Ninguna de las anteriores es correcta"], "c": 1, "e": "Las plazas vacantes ocupadas por personal interino deben incluirse en la oferta de empleo del ejercicio de su nombramiento o, si no es posible, en la siguiente.", "r": "Ley 11/2022 de Empleo Público Vasco; TREBEP art. 10.4 · batería oficial, pregunta 81"}, {"id": "ehu082", "q": "Según la Ley de empleo público Vasco es correcto señalar:", "o": ["El personal funcionario que permanezca en situaciones con o sin derecho a reserva de puesto podrá participar en las convocatorias de provisión de puestos de trabajo y promoción profesional.", "El personal funcionario que permanezca en situaciones con derecho a reserva de puesto podrá participar en las convocatorias de provisión de puestos de trabajo y promoción profesional.", "El personal funcionario que permanezca en situaciones con derecho a reserva de puesto podrá participar en las convocatorias de provisión de puestos de trabajo.", "El personal funcionario que permanezca en situaciones con derecho a reserva de puesto podrá participar en las convocatorias de promoción profesional."], "c": 1, "e": "Respuesta probable: el personal en situaciones con derecho a reserva de puesto puede participar en convocatorias de provisión y de promoción profesional.", "r": "Ley 11/2022 de Empleo Público Vasco (situaciones administrativas) · batería oficial, pregunta 82"}, {"id": "ehu083", "q": "Cuando el personal funcionario prolongue voluntariamente su permanencia en el servicio activo una vez rebasada la edad legal de jubilación ordinaria:", "o": ["No podrá declararse la excedencia forzosa.", "No podrá declararse la situación de expectativa de destino.", "No podrá concederse la excedencia voluntaria por interés particular.", "No podrá concederse la excedencia voluntaria, en cualquiera de sus modalidades."], "c": 2, "e": "Respuesta probable: quien prolonga voluntariamente el servicio activo no puede pasar a excedencia voluntaria por interés particular.", "r": "Ley 11/2022 de Empleo Público Vasco (situaciones administrativas) · batería oficial, pregunta 83"}, {"id": "ehu084", "q": "En virtud de LO establecido en la Ley de empleo púiblico Vasco, un funcionario podrá solicitar una excedencia voluntaria por interés particular:", "o": ["Cuando haya prestado servicios efectivos de forma continuada en cualquiera de las Administraciones Públicas o en el sector público durante los dos años inmediatamente anteriores y en ella no se podrá permanecer menos de dos años continuados.", "Cuando haya prestado servicios efectivos en cualquiera de las Administraciones Públicas durante los tres años inmediatamente anteriores y en ella no se podrá permanecer menos de dos años continuados.", "Cuando haya prestado servicios efectivos en cualquiera de las Administraciones Públicas durante los dos años inmediatamente anteriores, no estableciéndose un período mínimo de permanencia en esta situación.", "Aunque esté sometido a expediente disciplinario o esté pendiente del cumplimiento de una sanción."], "c": 0, "e": "Respuesta probable: se exigen dos años de servicios efectivos continuados inmediatamente anteriores y una permanencia mínima de dos años en la excedencia.", "r": "Ley 11/2022 de Empleo Público Vasco (excedencia voluntaria por interés particular) · batería oficial, pregunta 84"}, {"id": "ehu085", "q": "De acuerdo con la Ley 11/2022, de 1 de diciembre, de empleo público Vasco, no es correcto señalar:", "o": ["Los cambios de situación administrativa se acordarán por resolución del órgano competente en materia de empleo público de la administración u organismo público correspondiente.", "Los cambios de situación administrativa deberán anotarse en el registro de personal.", "Los cambios de situación podrán efectuarse si se reúnen los requisitos exigidos para ello en Cada Caso.", "Los cambios de situación administrativa se producirán con necesidad de reingreso al servicio activo."], "c": 3, "e": "Los cambios de situación administrativa se producen sin necesidad de reingreso al servicio activo.", "r": "Ley 11/2022 de Empleo Público Vasco (situaciones administrativas) · batería oficial, pregunta 85"}, {"id": "ehu086", "q": "Respecto al régimen de incompatibilidades de los funcionarios al servicio de las administraciones públicas vascas:", "o": ["El desempeño de un segundo puesto de trabajo en el sector privado requerirá la previa y expresa autorización de compatibilidad, mientras que si ese segundo puesto de trabajo se desarrolla en el sector público el funcionario únicamente deberá notificar este hecho a las respectivas Administraciones afectadas.", "No podrá autorizarse o reconocerse la compatibilidad de un funcionario cuando en las retribuciones complementarias que tenga derecho a percibir se incluya el factor de incompatibilidad.", "El régimen de incompatibilidades afecta únicamente a los funcionarios, no siendo de aplicación ni al personal eventual ni al personal laboral al servicio de las Administraciones Públicas.", "El desempeño de un segundo puesto de trabajo o actividad en el sector público o privado requerirá su comunicación fehaciente a las Administraciones implicadas, las cuales podrán en el plazo de 3 meses desde su notificación emitir resolución declarando su incompatibilidad. En caso de que no se produzca resolución expresa en el plazo indicado se entenderá este silencio positivo."], "c": 1, "e": "No puede autorizarse la compatibilidad cuando las retribuciones complementarias incluyan el factor de incompatibilidad.", "r": "Ley 53/1984 art. 16.1 y normativa vasca de incompatibilidades · batería oficial, pregunta 86"}, {"id": "ehu087", "q": "Según la Ley 11/2022, de empleo público Vasco, respecto al personal eventual:", "o": ["Su nombramiento se realiza por concurso de méritos.", "Su cese se produce únicamente por decisión expresa de la autoridad que lo nombró.", "Su número no puede superar los límites fijados por los órganos de gobierno correspondientes.", "Tiene las mismas funciones que el personal funcionario de carrera."], "c": 2, "e": "El número máximo de personal eventual lo fijan los órganos de gobierno; su cese es automático cuando cesa la autoridad a la que asesora.", "r": "Ley 11/2022 de Empleo Público Vasco (personal eventual) · batería oficial, pregunta 87"}, {"id": "ehu088", "q": "De acuerdo con el artículo 122 de la Ley 11/2022, de 1 de diciembre, de empleo público Vasco, son retribuciones complementarias:", "o": ["El complemento de destino correspondiente al nivel del puesto que se desempeñe, cuya cuantía se fijará anualmente en los Presupuestos Generales de la Comunidad Autónoma.", "El complemento específico, que, a salvo de norma o pacto en contrario, será único por cada puesto de trabajo que lo tenga asignado. Este complemento retribuye las condiciones particulares de cada puesto en razón de la especial dificultad técnica, responsabilidad, dedicación, penosidad o peligrosidad, así como cualquier otra condición que concurra en el puesto de trabajo.", "EL Complemento de carrera profesional, que retribuirá la progresión profesional del personal funcionario a través de los diferentes grados de desarrollo profesional en los que se articula el sistema de carrera profesional de las administraciones públicas vascas.", "Todas las anteriores son correctas."], "c": 3, "e": "Son retribuciones complementarias el complemento de destino, el específico y el de carrera profesional, entre otras.", "r": "Ley 11/2022 art. 122 · batería oficial, pregunta 88"}, {"id": "ehu089", "q": "Respecto al complemento de especial dedicación en las retribuciones del personal técnico, de gestión y administración y servicios funcionario de la EHU:", "o": ["Su cuantía no podrá exceder del 50% del importe del nivel de clasificación del puesto de trabajo.", "Su percepción no anula otros derechos a compensación por la jornada de trabajo que exceda de la normalizada.", "Exige una jornada de presencia física que exceda en más de 100 horas a la normalizada.", "Corresponde al Consejo Económico y Social el reconocimiento de este derecho."], "c": 0, "e": "Respuesta probable: la cuantía tiene un tope porcentual sobre el nivel del puesto. Compruébalo en la normativa retributiva del PTGAS de la UPV/EHU.", "r": "Normativa retributiva del PTGAS funcionario UPV/EHU · batería oficial, pregunta 89"}, {"id": "ehu090", "q": "Respecto a los procesos de promoción interna del personal técnico, de gestión y administración y servicios funcionario de la EHU:", "o": ["Podrán incluir pruebas de conocimientos generales o específicos.", "Corresponde a la Sección de Personal técnico, de gestión y administración y servicios de la EHU desarrollar la normativa sobre la carrera profesional de este personal.", "Corresponde a la Gerencia de la EHU desarrollar la normativa sobre la carrera profesional de este personal.", "Ninguna de las opciones anteriores es correcta."], "c": 0, "e": "Respuesta probable: los procesos de promoción interna pueden incluir pruebas de conocimientos generales o específicos.", "r": "Normativa del PTGAS UPV/EHU; TREBEP art. 18 · batería oficial, pregunta 90"}, {"id": "ehu091", "q": "De conformidad con el artículo 178 la Ley 11/2022, de 1 de diciembre de empleo público Vasco, se consideran faltas muy graves:", "o": ["La falta grave de consideración con los/as administrados/as.", "Cualquier actuación que suponga discriminación por razón de origen racial o étnico, religión o convicciones, discapacidad, edad, orientación sexual, lengua, opinión, lugar de nacimiento o vecindad, sexo, o cualquier otra condición o circunstancia personal o social.", "El incumplimiento de las órdenes o instrucciones de los/as superiores jerárquicos/as referidas al servicio.", "Originar o tomar parte en altercados en el centro de trabajo."], "c": 1, "e": "Toda actuación que suponga discriminación por esas razones es falta muy grave.", "r": "Ley 11/2022 art. 178 · batería oficial, pregunta 91"}, {"id": "ehu092", "q": "De conformidad con el artículo 179 la Ley 11/2022, de 1 de diciembre de empleo público Vasco, se consideran faltas graves:", "o": ["El abandono del servicio.", "La adopción de resoluciones o acuerdos manifiestamente ¡legales que causen grave perjuicio a la Administración o a los/as ciudadanos/as.", "Elabuso de autoridad en el ejercicio del puesto de trabajo.", "La falta de asistencia injustificada de un día."], "c": 2, "e": "El abuso de autoridad en el ejercicio del puesto es falta grave. El abandono del servicio y las resoluciones manifiestamente ilegales son muy graves.", "r": "Ley 11/2022 art. 179 · batería oficial, pregunta 92"}, {"id": "ehu093", "q": "De conformidad con el artículo 180 la Ley 11/2022, de 1 de diciembre de empleo público Vasco, son faltas leves:", "o": ["El incumplimiento injustificado del horario de trabajo, cuando no suponga falta grave.", "La falta de asistencia injustificada de un día.", "No proporcionar a la ciudadanía la información debida, siempre que sea de la competencia de la unidad en la que presta sus funciones.", "Todas las anteriores son correctas."], "c": 3, "e": "Las tres conductas se tipifican como faltas leves.", "r": "Ley 11/2022 art. 180 · batería oficial, pregunta 93"}, {"id": "ehu094", "q": "De acuerdo con la Ley 11/2022, de 1 de diciembre de empleo público Vasco, es personal laboral el que en virtud de:", "o": ["Contrato de trabajo formalizado por escrito presta servicios retribuidos por las Administraciones Públicas Vascas.", "Contrato de trabajo formalizado por escrito o de forma verbal presta servicios retribuidos por las Administraciones Públicas Vascas.", "Nombramiento presta servicios retribuidos por las Administraciones Públicas Vascas.", "Ninguna respuesta es correcta."], "c": 0, "e": "Es personal laboral el que, en virtud de contrato de trabajo formalizado por escrito, presta servicios retribuidos.", "r": "Ley 11/2022 de Empleo Público Vasco; TREBEP art. 11.1 · batería oficial, pregunta 94"}, {"id": "ehu095", "q": "De acuerdo con la Ley 11/2022, de 1 de diciembre de empleo público Vasco, no es una situación administrativa:", "o": ["El servicio activo.", "La suspensión.", "La jubilación.", "El servicio en otras Administraciones Públicas."], "c": 2, "e": "La jubilación es una causa de pérdida de la condición de funcionario, no una situación administrativa.", "r": "Ley 11/2022 de Empleo Público Vasco (situaciones administrativas) · batería oficial, pregunta 95"}, {"id": "ehu096", "q": "El examen y resolución de cuestiones derivadas de la interpretación del 11! Convenio del personal laboral de administraciones y servicios de la EHU corresponde a:", "o": ["La Comisión Paritaria.", "La Comisión Negociadora.", "El Comité de Empresa.", "La Comisión de Planificación."], "c": 0, "e": "La interpretación del convenio corresponde a la Comisión Paritaria.", "r": "III Convenio del personal laboral de administración y servicios de la UPV/EHU · batería oficial, pregunta 96"}, {"id": "ehu097", "q": "El servicio de prevención de la EHU es:", "o": ["Un servicio propio.", "Un servicio ajeno.", "Un servicio asumido personalmente por el empresario.", "Un servicio mediante trabajador designado."], "c": 0, "e": "La UPV/EHU tiene un servicio de prevención propio.", "r": "Organización preventiva UPV/EHU; RD 39/1997 · batería oficial, pregunta 97"}, {"id": "ehu098", "q": "La EHU en el artículo 5.3 de sus Estatutos reconoce y garantiza:", "o": ["La libertad de expresión.", "La libertad religiosa.", "La libertad de cátedra.", "La libertad de pensamiento."], "c": 2, "e": "Respuesta probable: el art. 5.3 de los Estatutos reconoce y garantiza la libertad de cátedra.", "r": "Estatutos UPV/EHU art. 5.3 · batería oficial, pregunta 98"}, {"id": "ehu099", "q": "La comunidad universitaria está formada por los siguientes colectivos:", "o": ["Alumnado, personal docente e investigador y personal técnico, de gestión y administración y servicios.", "Alumnado y trabajadores/as autónomos/as.", "Personal docente e investigador y personal técnico, de gestión y administración y servicios.", "Alumnado, trabajadores/as autónomos/as y cargos directivos."], "c": 0, "e": "La comunidad universitaria la forman el alumnado, el PDI y el PTGAS.", "r": "LOSU; Estatutos UPV/EHU · batería oficial, pregunta 99"}, {"id": "ehu100", "q": "Según los Estatutos de la EHU, el régimen retributivo del personal técnico, de gestión y administración y servicios LO establecera:", "o": ["El Rector o Rectora.", "El Claustro Universitario.", "El Comité de Empresa.", "El Consejo de Gobierno."], "c": 3, "e": "Respuesta probable: corresponde al Consejo de Gobierno establecer el régimen retributivo del PTGAS, dentro del marco legal y presupuestario.", "r": "Estatutos UPV/EHU · batería oficial, pregunta 100"}]}, {"id": "b05", "sig": "Bloque 5", "titulo": "Bloque 5. EHU: Estatutos, personal y organización (I)", "sub": "Preguntas 101–160 de la batería oficial (sin respuestas oficiales: resueltas por Claude).", "preguntas": [{"id": "ehu101", "q": "Según los Estatutos de la EHU, el personal laboral se clasificará conforme a:", "o": ["Los acuerdos de las Juntas de Centro.", "Su convenio colectivo en vigor.", "La Ley de la Función Pública Vasca.", "El Estatuto Básico del Empleado Público."], "c": 1, "e": "El personal laboral se clasifica conforme a su convenio colectivo.", "r": "Estatutos UPV/EHU (PTGAS laboral) · batería oficial, pregunta 101"}, {"id": "ehu102", "q": "Las recomendaciones del o de la aldezle serán susceptibles de recurso:", "o": ["Siel Rector o Rectora es parte implicada.", "No serán susceptibles de recurso.", "Siempre serán susceptibles de recurso.", "Cuando afecten a un grupo numeroso de la comunidad universitaria."], "c": 1, "e": "Las recomendaciones del Aldezle no son vinculantes ni susceptibles de recurso.", "r": "Estatutos UPV/EHU (Aldezle) · batería oficial, pregunta 102"}, {"id": "ehu103", "q": "La biblioteca universitaria es un centro de recursos para la docencia, el aprendizaje, la investigación y las actividades relacionadas con:", "o": ["El funcionamiento y la gestión de la universidad en su conjunto.", "El desarrollo de la capacidad de estudio del alumnado.", "La capacidad investigadora del personal docente.", "El servicio a la sociedad en su conjunto."], "c": 0, "e": "La biblioteca universitaria es centro de recursos para la docencia, el aprendizaje, la investigación y las actividades relacionadas con el funcionamiento y la gestión de la universidad en su conjunto.", "r": "Definición REBIUN; Estatutos UPV/EHU · batería oficial, pregunta 103"}, {"id": "ehu104", "q": "Según los Estatutos de la EHU, las bases de las convocatorias de pruebas selectivas para el acceso a la condición de personal funcionario o personal contratado laboral fijo al servicio de la EHU debera contener necesariamente:", "o": ["Los requisitos que deben reunir los y las aspirantes.", "Los nombres y apellidos de los miembros del tribunal.", "Las dotaciones objeto de la convocatoria.", "La fecha de publicación de los resultados."], "c": 0, "e": "Respuesta probable: las bases deben recoger, entre otros extremos, los requisitos de las personas aspirantes.", "r": "Estatutos UPV/EHU (acceso del PTGAS) · batería oficial, pregunta 104"}, {"id": "ehu105", "q": "El órgano de representación unitaria del personal técnico, de gestión y administración y servicios funcionario es:", "o": ["La Junta de personal técnico, de gestión y administración y servicios.", "El Comité de Empresa.", "El Consejo de Gobierno.", "El Claustro Universitario."], "c": 0, "e": "El órgano de representación unitaria del PTGAS funcionario es la Junta de Personal.", "r": "Estatutos UPV/EHU; TREBEP art. 39 · batería oficial, pregunta 105"}, {"id": "ehu106", "q": "Las decisiones relativas al régimen disciplinario de estudiantes, personal docente e investigador y personal técnico, de gestión y administración y servicios que la legislación vigente no atribuya a otro organo serán adoptadas por:", "o": ["Elola Aldezle.", "La Rectora o El Rector.", "El Comité Arbitral.", "El Comité de Seguridad y Salud Intercampus."], "c": 1, "e": "Las decisiones disciplinarias no atribuidas a otro órgano corresponden al Rector o Rectora.", "r": "Estatutos UPV/EHU (competencias del Rector) · batería oficial, pregunta 106"}, {"id": "ehu107", "q": "En la EHU, la institución independiente e imparcial que promoverá la utilización de modos alternativos, no adversariales, para prevenir y resolver problemas y conflictos relacionados con la actividad universitaria en todos sus niveles es:", "o": ["Elola Aldezle.", "Comité de Empresa.", "Comité de Seguridad y Salud Laboral.", "La Rectora o El Rector."], "c": 0, "e": "El Aldezle es la institución independiente e imparcial que promueve la mediación y los modos alternativos de resolver conflictos.", "r": "Estatutos UPV/EHU (Aldezle) · batería oficial, pregunta 107"}, {"id": "ehu108", "q": "En la EHU, el órgano que determina las plazas para las que es preceptivo el conocimiento de euskera y castellano es:", "o": ["El Consejo de Gobierno.", "El Claustro Universitario.", "El Comité de Empresa.", "La Junta de Personal."], "c": 0, "e": "Respuesta probable: el Consejo de Gobierno determina las plazas con perfil lingüístico preceptivo.", "r": "Estatutos UPV/EHU · batería oficial, pregunta 108"}, {"id": "ehu109", "q": "En la EHU, la modificación de campus universitarios corresponde a:", "o": ["El Consejo de Gobierno a propuesta del Claustro Universitario.", "El Claustro Universitario a propuesta del Consejo de Gobierno.", "El Consejo de Gobierno a propuesta del Campus Universitario.", "AlCampus Universitario a propuesta propia."], "c": 1, "e": "Respuesta probable: corresponde al Claustro a propuesta del Consejo de Gobierno.", "r": "Estatutos UPV/EHU (campus) · batería oficial, pregunta 109"}, {"id": "ehu110", "q": "Sin perjuicio de las delegaciones que efectúe, el órgano de contratación de la EHU es:", "o": ["Elola Gerente.", "La Rectora o El Rector.", "Elo la Vicegerente de Contratación y Compras.", "El Claustro Universitario."], "c": 1, "e": "El órgano de contratación de la Universidad es el Rector o Rectora, sin perjuicio de las delegaciones.", "r": "LCSP DA 2ª; Estatutos UPV/EHU · batería oficial, pregunta 110"}, {"id": "ehu111", "q": "El derecho a la libertad de cátedra, reconocido en el texto constitucional, implica que:", "o": ["Las/os catedráticas/os y profesoras/es tienen derecho a enseñar conforme a sus propios criterios y con los métodos que consideren más convenientes.", "Los alumnos pueden elegir libremente las asignaturas que estimen más convenientes para su formación universitaria o profesional.", "Las cátedras pueden adjudicarse por libre designación, esto es, sin previa oposición, concurso o concurso-oposición.", "Las/os catedráticas/os tienen derecho a enseñar conforme a sus propios criterios y con los métodos que estimen más convenientes."], "c": 0, "e": "La libertad de cátedra ampara a todo el profesorado (no solo a catedráticos) para enseñar según sus criterios y métodos.", "r": "CE art. 20.1.c · batería oficial, pregunta 111"}, {"id": "ehu112", "q": "El Estatuto básico del empleado público entre otros se aplica a...", "o": ["Únicamente al personal funcionario de las Universidades Públicas.", "Únicamente al personal laboral de las Universidades Públicas.", "Al personal funcionario y en lo que proceda al personal laboral al servicio de las Universidades Públicas.", "Atodo el personal de las Universidades Privadas y únicamente al personal funcionario en las Universidades Públicas."], "c": 2, "e": "El TREBEP se aplica al personal funcionario y, en lo que proceda, al laboral de las Universidades Públicas.", "r": "TREBEP art. 2.1.e · batería oficial, pregunta 112"}, {"id": "ehu113", "q": "El personal empleado público se clasifica en...", "o": ["Personal funcionario de carrera, personal funcionario interino, personal laboral, ya sea fijo, por tiempo indefinido o temporal y personal eventual.", "Personal funcionario de carrera y personal funcionario Interino.", "Personal funcionario de carrera, personal funcionario interino y personal laboral fijo.", "Personal funcionario de carrera, personal laboral fijo y personal eventual."], "c": 0, "e": "Los empleados públicos son funcionarios de carrera, interinos, personal laboral (fijo, indefinido o temporal) y eventual.", "r": "TREBEP art. 8.2 · batería oficial, pregunta 113"}, {"id": "ehu114", "q": "Según el Estatuto básico del empleado público, es personal laboral...", "o": ["Quien, en virtud de nombramiento legal, están vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter permanente.", "Quien, en virtud de contrato de trabajo formalizado por escrito, en cualquiera de las modalidades de contratación de personal previstas en la legislación laboral, presta servicios retribuidos por las Administraciones Pública.", "Quien, por razones expresamente justificadas de necesidad y urgencia, es nombrado como tal para el desempeño de funciones propias de personal funcionario de carrera.", "Quien, en virtud de nombramiento y con carácter no permanente, sólo realiza funciones expresamente calificadas como de confianza o asesoramiento especial, siendo retribuido con cargo a los créditos presupuestarios consignados para este fin."], "c": 1, "e": "Es personal laboral quien presta servicios en virtud de contrato de trabajo formalizado por escrito.", "r": "TREBEP art. 11.1 · batería oficial, pregunta 114"}, {"id": "ehu115", "q": "¿Quién aprueba de forma definitiva el presupuesto de la EHU?", "o": ["La Rectora o El Rector.", "La Decana o El Decano.", "El Consejo de Gobierno.", "El Consejo Social."], "c": 3, "e": "El presupuesto lo aprueba el Consejo Social, a propuesta del Consejo de Gobierno.", "r": "LOSU; Estatutos UPV/EHU · batería oficial, pregunta 115"}, {"id": "ehu116", "q": "Los comités de seguridad y salud de la EHU son:", "o": ["Un Comité Intercampus, un Comité de Seguridad y Salud por cada Campus y un Comité para a Seguridad Medioambiental.", "Un Comité Intercampus, un Comité para la Seguridad Medioambiental e Inspección de Trabajo.", "Un Comité Intercampus y un Comité de Seguridad y Salud por cada Campus.", "Un Comité Intercampus, un Comité de Seguridad y Salud por cada Campus e Inspección de Trabajo."], "c": 2, "e": "Respuesta probable: un Comité Intercampus y un Comité de Seguridad y Salud por cada campus.", "r": "Organización preventiva UPV/EHU · batería oficial, pregunta 116"}, {"id": "ehu117", "q": "Son miembros del personal técnico, de gestión y administración y servicios de la EHU...", "o": ["Personal funcionario, personal contratado laboral y funcionarios y funcionarias de otras Administraciones Públicas que, de acuerdo con la legislación vigente, presten servicio en la", "Personal funcionario y funcionarios y funcionarias de otras Administraciones Públicas que, de acuerdo con la legislación vigente, presten servicio en la EHU.", "Personal laboral y funcionarios y funcionarias de otras Administraciones Públicas que, de acuerdo con la legislación vigente, presten servicio en la EHU.", "Sólo personal funcionario."], "c": 0, "e": "El PTGAS lo forman el personal funcionario, el laboral y los funcionarios de otras Administraciones que presten servicio en la UPV/EHU.", "r": "Estatutos UPV/EHU · batería oficial, pregunta 117"}, {"id": "ehu118", "q": "Según los Estatutos de la EHU, las enseñanzas universitarias oficiales se estructuraran en...", "o": ["Tres ciclos: grado, máster y doctorado.", "Dos ciclos: grado y máster.", "Tres ciclos: grado, máster y formación profesional.", "Dos ciclos: grado y doctorado."], "c": 0, "e": "Las enseñanzas oficiales se estructuran en grado, máster y doctorado.", "r": "Estatutos UPV/EHU; LOSU art. 7 · batería oficial, pregunta 118"}, {"id": "ehu119", "q": "Según los Estatutos de la EHU, la EHU es una Universidad...", "o": ["Multicampus.", "Pluricampus.", "Monocampus.", "Bicampus."], "c": 0, "e": "La UPV/EHU es una universidad multicampus.", "r": "Estatutos UPV/EHU art. 1 · batería oficial, pregunta 119"}, {"id": "ehu120", "q": "Según los Estatutos de la EHU, son centros docentes...", "o": ["Las escuelas y facultades.", "Los campus universitarios.", "Los colegios mayores.", "Los aularios."], "c": 0, "e": "Son centros docentes las facultades y escuelas.", "r": "Estatutos UPV/EHU · batería oficial, pregunta 120"}, {"id": "ehu121", "q": "De acuerdo con el artículo 26 del Real Decreto 412/2014, de 6 de junio, por el que se establece la normativa básica de los procedimientos de admisión a las enseñanzas universitarias oficiales de grado, existe un porcentaje de plazas reservadas a estudiantes con discapacidad. Este porcentaje es:", "o": ["3%.", "4%.", "5%.", "6%."], "c": 2, "e": "Se reserva al menos el 5% de las plazas a estudiantes con discapacidad.", "r": "RD 412/2014 art. 26 · batería oficial, pregunta 121"}, {"id": "ehu122", "q": "En relación con personas con discapacidad. Señale la afirmación correcta:", "o": ["En las ofertas de empleo público se reservará un cupo no inferior al tres por ciento de las vacantes para ser cubiertas entre personas con discapacidad.", "El Estatuto Básico del Empleado Público no contempla ninguna medida respecto al acceso de las personas con discapacidad a la función pública.", "En las ofertas de empleo público podrá reservarse un cupo de vacantes para ser cubiertas entre personas con discapacidad. Cada Administración Pública determinará esa cantidad que no podrá ser inferior al 3% ni superior al 10% del total de plazas ofertadas.", "En las ofertas de empleo público se reservará un cupo no inferior al siete por ciento de las vacantes para ser cubiertas entre personas con discapacidad."], "c": 3, "e": "Se reserva un cupo no inferior al 7% de las vacantes para personas con discapacidad.", "r": "TREBEP art. 59.1 · batería oficial, pregunta 122"}, {"id": "ehu123", "q": "¿Quién tiene competencia para aprobar el Reglamento de un centro docente?", "o": ["La Junta de Centro.", "El Consejo de Dirección.", "La Junta de Campus.", "El Consejo de Gobierno."], "c": 3, "e": "Respuesta probable: el reglamento del centro lo aprueba el Consejo de Gobierno, a propuesta de la Junta de Centro.", "r": "Estatutos UPV/EHU · batería oficial, pregunta 123"}, {"id": "ehu124", "q": "¿Quién nombra a los/as decanos/as y a los/as directores/as de los centros?", "o": ["La Junta de Centro.", "El/ La Rector/a.", "El/la Vicerrector/a de Campus.", "El Gobierno Vasco."], "c": 1, "e": "Decanos y directores de centro los nombra el Rector o Rectora.", "r": "Estatutos UPV/EHU · batería oficial, pregunta 124"}, {"id": "ehu125", "q": "Según los Estatutos de la EHU, la persona responsable de la organización y gestión de los servicios administrativos y económicos de la EHU es:", "o": ["La Rectora o El Rector", "La Gerente o El Gerente.", "El/la Vicerrector/a de Campus.", "El/la Vicegerente/a de Patrimonio y Contratación."], "c": 1, "e": "La gestión de los servicios administrativos y económicos corresponde al Gerente.", "r": "LOSU; Estatutos UPV/EHU (Gerencia) · batería oficial, pregunta 125"}, {"id": "ehu126", "q": "¿Qué es la plantilla de referencia del personal técnico, de gestión y administración y servicios?", "o": ["Esun instrumento de gestión para los recursos humanos.", "Esun instrumento de planificación de los recursos humanos.", "Esun instrumento de control de los recursos humanos.", "Esun instrumento de valoración de puestos de trabajo."], "c": 1, "e": "Respuesta probable: la plantilla de referencia es un instrumento de planificación de los recursos humanos.", "r": "Normativa PTGAS UPV/EHU · batería oficial, pregunta 126"}, {"id": "ehu127", "q": "Las secciones departamentales:", "o": ["Podrán constituirse únicamente en aquellos Departamentos que desarrollen sus actividades en distintos Campus. La creación o supresión de secciones requerirá la reforma del Reglamento.", "Podrán constituirse únicamente en aquellos Departamentos que desarrollen sus actividades en distintos Centros Docentes. La creación o supresión de secciones requerirá la reforma del Reglamento.", "Podrán constituirse en aquellos Departamentos que desarrollen sus actividades en distintos Campus. La creación o supresión de secciones no requerirá la reforma del Reglamento.", "Ninguna de las respuestas anteriores es correcta."], "c": 0, "e": "Respuesta probable: solo en departamentos con actividad en distintos campus, y su creación o supresión exige reformar el reglamento.", "r": "Estatutos UPV/EHU (departamentos) · batería oficial, pregunta 127"}, {"id": "ehu128", "q": "Cuál de las siguientes afirmaciones es incorrecta respecto al Consejo de estudiantes de campus:", "o": ["Estará compuesto por dos representantes del alumnado de cada uno de los Centros Docentes pertenecientes al Campus.", "Lo integrarán, entre otros, la representación del alumnado del respectivo Campus en el Consejo de Gobierno.", "La representación de los Centros Docentes en este Consejo se elegirá por y de entre la representación del alumnado en la Junta de Centro.", "Lao el Presidente de cada Consejo de Estudiantes de Campus integrará el Consejo de Estudiantes de la EHU."], "c": 1, "e": "Respuesta probable. Compruébalo en los Estatutos.", "r": "Estatutos UPV/EHU (Consejo de Estudiantes) · batería oficial, pregunta 128"}, {"id": "ehu129", "q": "Cuál de los siguientes se considera un órgano colegiado de Gobierno y representación de la EHU:", "o": ["El Consejo Jurídico.", "El Consejo Económico.", "El Consejo Sindical.", "El Consejo Permanente de la Escuela de Doctorado."], "c": 3, "e": "Respuesta probable: de las opciones, solo el Consejo Permanente de la Escuela de Doctorado es órgano colegiado de la Universidad.", "r": "Estatutos UPV/EHU · batería oficial, pregunta 129"}, {"id": "ehu130", "q": "El Consejo de Gobierno dictará las normas reguladoras de las convocatorias de concurso de acceso de profesorado:", "o": ["A propuesta del Vicerrector o Vicerrectora de Personal Docente e Investigador.", "A propuesta directa del Rector o Rectora.", "A propuesta del Consejo de Departamento correspondiente.", "A propuesta de la Comisión de Profesorado."], "c": 0, "e": "Respuesta probable: a propuesta del Vicerrectorado de PDI.", "r": "Estatutos UPV/EHU (profesorado) · batería oficial, pregunta 130"}, {"id": "ehu131", "q": "La aprobación de la normativa reguladora de doctorado y sus efectos en el encargo docente corresponde a:", "o": ["El Consejo de Gobierno, a propuesta del Consejo de Departamento correspondiente.", "La Comisión de Postgrado.", "La Comisión de Estudios de Doctorado.", "Ninguna de las opciones anteriores es correcta."], "c": 3, "e": "Respuesta probable. Compruébalo en los Estatutos.", "r": "Estatutos UPV/EHU (doctorado) · batería oficial, pregunta 131"}, {"id": "ehu132", "q": "Constituyen el Consejo de Gobierno de la EHU:", "o": ["7representantes del profesorado Doctor con vinculación permanente a la Universidad.", "7representantes del PERSONAL técnico, de gestión y administración y servicios.", "7 representantes de los Departamentos, Institutos y Escuelas de Doctorado.", "Ninguna de las opciones anteriores es correcta."], "c": 3, "e": "Respuesta probable. Compruébalo en los Estatutos.", "r": "Estatutos UPV/EHU (Consejo de Gobierno) · batería oficial, pregunta 132"}, {"id": "ehu133", "q": "Con relación al personal eventual:", "o": ["Su nombramiento y cese son libres.", "Es personal con carácter no permanente.", "Sólo realiza funciones expresamente calificadas como de confianza o asesoramiento especial.", "Las tres respuestas anteriores son correctas."], "c": 3, "e": "El personal eventual es de nombramiento y cese libres, no permanente y solo realiza funciones de confianza o asesoramiento especial.", "r": "TREBEP art. 12 · batería oficial, pregunta 133"}, {"id": "ehu134", "q": "La Comisión de profesorado de la EHU:", "o": ["Estará presidida por el Decano o la Decana de Facultad de mayor antiguedad en la EHU.", "Estará presidida por el Vicerrector o Vicerrectora de Personal Docente e Investigador.", "Estará presidida por el Rector o la Rectora.", "Estará compuesta por 10 personas del profesorado permanente doctor con, al menos, 10 años de experiencia, pertenecientes a diferentes áreas de conocimiento."], "c": 1, "e": "Respuesta probable: la preside el Vicerrector o Vicerrectora de PDI.", "r": "Estatutos UPV/EHU · batería oficial, pregunta 134"}, {"id": "ehu135", "q": "En relación con el profesorado funcionario de la EHU, las reclamaciones planteadas por divergencias frente al horario y calendario académicos serán estudiadas y resueltas por:", "o": ["El Consejo de Departamento.", "El Consejo Social.", "El Decano o la Decana de Facultad o Director o Directora de Escuela.", "El Consejo de Gobierno."], "c": 0, "e": "Respuesta probable. Compruébalo en la normativa del PDI.", "r": "Normativa PDI UPV/EHU · batería oficial, pregunta 135"}, {"id": "ehu136", "q": "Respecto al anticipo de nómina del personal docente e investigador laboral de la EHU:", "o": ["El importe máximo del adelanto a conceder será de 6.000 euros.", "Deberá transcurrir un periodo mínimo de un año entre la cancelación de un adelanto de nómina y la solicitud de otro.", "No se podrán solicitar anticipos por conceptos ya solicitados con anterioridad en más de tres ocasiones.", "En solicitudes de anticipo para adquisición de vivienda habitual, el plazo máximo de reintegro será de 36 mensualidades."], "c": 0, "e": "Respuesta probable. Compruébalo en la normativa de anticipos.", "r": "Normativa de anticipos UPV/EHU · batería oficial, pregunta 136"}, {"id": "ehu137", "q": "Cuál de las siguientes afirmaciones es cierta respecto a la jornada laboral del profesorado de la EHU:", "o": ["Las obligaciones docentes semanales de los Titulares de Universidad con régimen de dedicación a tiempo completo serán de un máximo de 12 horas lectivas.", "Las obligaciones docentes semanales de los Asociados de Escuela Universitaria con régimen de dedicación a tiempo completo contemplan un máximo de 8 horas de tutoría.", "Las horas lectivas dedicadas a programas de doctorado se computarán el triple.", "Ninguna de las opciones anteriores es correcta."], "c": 3, "e": "Respuesta probable. Compruébalo en la normativa de dedicación del profesorado.", "r": "Normativa PDI UPV/EHU · batería oficial, pregunta 137"}, {"id": "ehu138", "q": "Respecto a la duración del contrato del personal laboral docente e investigador de la EHU:", "o": ["El contrato de profesorado adjunto tendrá una duración máxima de 4 años.", "El contrato de profesorado ayudante tendrá una duración mínima de 2 años.", "El contrato de profesorado agregado tendrá una duración indefinida.", "El contrato de profesorado asociado tendrá una duración máxima de 4 años, sin perjuicio de que una vez finalizado se pueda obtener un nuevo contrato."], "c": 2, "e": "Respuesta probable: el contrato de profesorado agregado es indefinido.", "r": "Normativa PDI laboral UPV/EHU · batería oficial, pregunta 138"}, {"id": "ehu139", "q": "En los procesos selectivos de personal funcionario de carrera podrá aplicarse unicamente el sistema de concurso:", "o": ["En ningún caso.", "Sólo en virtud de ley podrá aplicarse, y con carácter excepcional.", "El Estatuto Básico del Empleado Público no lo detalla.", "Sí asilo aprueba el máximo órgano responsable de cada Administración Pública."], "c": 1, "e": "Solo excepcionalmente, y en virtud de ley, puede aplicarse únicamente el concurso de méritos.", "r": "TREBEP art. 61.6 · batería oficial, pregunta 139"}, {"id": "ehu140", "q": "¿Qué universidades componen el sistema universitario Vasco?", "o": ["El Sistema Universitario Vasco está formado por las universidades públicas con sede en el territorio de la Comunidad Autónoma Vasca.", "El Sistema Universitario Vasco está formado por todas las universidades con sede en el territorio de la Comunidad Autónoma del País Vasco.", "El Sistema Universitario Vasco está formado por la EHU, la Universidad de Deusto, la Universidad de Mondragón y el Instituto de Máquina Herramienta.", "El Sistema Universitario Vasco está formado por todas las universidades con sede en el territorio de la Comunidad Autónoma del País Vasco, y aquellas cuya sede esté en la Comunidad Foral de Navarra y sea admitida su solicitud de adhesión, según lo dispuesto en a disposición transitoria cuarta de la Ley 3/2004, de 25 febrero."], "c": 1, "e": "Respuesta probable: lo forman todas las universidades con sede en la CAPV.", "r": "Ley 3/2004 del Sistema Universitario Vasco · batería oficial, pregunta 140"}, {"id": "ehu141", "q": "Los actos administrativos sujetos a derecho administrativo:", "o": ["Se presumen válidos.", "Se presumen expresos.", "Se presumen desfavorables.", "Se presumen motivados."], "c": 0, "e": "Los actos de las Administraciones sujetos a Derecho administrativo se presumen válidos y producen efectos desde que se dictan.", "r": "Ley 39/2015 art. 39.1 · batería oficial, pregunta 141"}, {"id": "ehu142", "q": "De acuerdo con la Ley 3/2004 del sistema universitario Vasco una de estas afirmaciones es falsa:", "o": ["La comunidad universitaria está integrada por los estudiantes matriculados, el personal investigador, el personal docente e investigador y el PERSONAL técnico, de gestión y administración y servicios.", "El reconocimiento de Universidades privadas se hará mediante ley.", "La organización y funcionamiento de las universidades serán democráticos de acuerdo con las normas existentes en su organización.", "La autonomía de la Universidad se fundamenta en la libertad académica que se manifiesta en las libertades de pensamiento, investigación y conciencia."], "c": 3, "e": "Es falsa: la libertad académica se manifiesta en las libertades de cátedra, investigación y estudio.", "r": "Ley 3/2004 del Sistema Universitario Vasco · batería oficial, pregunta 142"}, {"id": "ehu143", "q": "De acuerdo con los Estatutos de la EHU una de estas afirmaciones es falsa:", "o": ["La EHU es una Institución de Derecho Público, que goza de autonomía, está dotada de personalidad y capacidad jurídica, y sin patrimonio propio.", "Es un fin de la EHU la educación superior de calidad que contribuya a la formación integral de los estudiantes.", "La autonomía universitaria garantiza la capacidad autonormativa y de autoorganización.", "La EHU es una Universidad multicampus."], "c": 0, "e": "Es falsa: la UPV/EHU sí tiene patrimonio propio.", "r": "Estatutos UPV/EHU art. 1 · batería oficial, pregunta 143"}, {"id": "ehu144", "q": "En todo caso, la ejecución de la oferta pública de empleo deberá desarrollarse dentro del plazo improrrogable de:", "o": ["Tres años.", "Cuatro años.", "Diez años.", "ElEstatuto Básico del Empleado Público no detalla plazo."], "c": 0, "e": "La oferta de empleo debe ejecutarse en el plazo improrrogable de tres años.", "r": "TREBEP art. 70.1 · batería oficial, pregunta 144"}, {"id": "ehu145", "q": "La EHU:", "o": ["Es una institución de Derecho Foral.", "Es una institución de Derecho Civil.", "Es una institución de Derecho Público.", "Es una institución de Derecho Privado y Financiación Pública."], "c": 2, "e": "La UPV/EHU es una institución de Derecho público.", "r": "Estatutos UPV/EHU art. 1 · batería oficial, pregunta 145"}, {"id": "ehu146", "q": "Eldl1/2023 de 16 marzo, por el que se aprueba el texto refundido de la Ley para la igualdad de mujeres y hombres y vidas libres de violencia machista para las mujeres, ¿Que porcentaje minimo de representación de cada sexo establece para que exista representación equilibrada en organos pluripersonales de mas de cuatro miembros?", "o": ["30%.", "35%.", "40%.", "50%."], "c": 2, "e": "Hay representación equilibrada cuando cada sexo está representado al menos al 40%.", "r": "DL 1/2023 (Igualdad), art. 20/ definición de representación equilibrada · batería oficial, pregunta 146"}, {"id": "ehu147", "q": "¿Quétipo de profesores componen los cuerpos docentes universitarios?", "o": ["Catedráticos/as de universidad, profesores/as titulares de universidad, catedráticos/as de escuela universitaria y profesores/as titulares de escuela universitaria.", "Catedráticos/as de universidad, catedráticos/as de escuela universitaria, profesores/as asociados/as y profesores/as visitantes.", "Catedráticos/as de universidad, catedráticos/as de escuela universitaria, titulares de universidad y eméritos/as.", "Profesores/as titulares de universidad, profesores/as titulares de escuela, maestros/as de aller y catedráticos/as de universidad."], "c": 0, "e": "Los cuerpos docentes eran catedráticos y titulares de universidad y catedráticos y titulares de escuela universitaria.", "r": "LOU (Estatutos UPV/EHU) · batería oficial, pregunta 147"}, {"id": "ehu148", "q": "Señale la respuesta correcta:", "o": ["El IV Plan de Igualdad de Mujeres y Hombres de la EHU abarca el periodo 2024/2028.", "Elll Plan de Igualdad de Mujeres y Hombres de la EHU abarca el periodo 2019/2022.", "El IV Plan de Igualdad de Mujeres y Hombres de la EHU abarca el periodo 2019/2022.", "Ellll Plan de Igualdad de Mujeres y Hombres de la EHU abarca el periodo 2020/2023."], "c": 0, "e": "Respuesta probable. Compruébalo en la web de Igualdad de la UPV/EHU.", "r": "Planes de Igualdad UPV/EHU · batería oficial, pregunta 148"}, {"id": "ehu149", "q": "Las relaciones de puestos de trabajo deberán incluir:", "o": ["La totalidad de los existentes que se hallen dotados presupuestariamente.", "Sólo los reservados a personal funcionario que se hallen dotados presupuestariamente.", "Sólo los reservados a personal funcionario y personal laboral, excluidos los que se encuentren vacantes.", "La totalidad de los existentes, estén o no dotados presupuestariamente."], "c": 0, "e": "Las RPT incluyen la totalidad de los puestos existentes que estén dotados presupuestariamente.", "r": "Ley de Función Pública Vasca / Ley 11/2022 · batería oficial, pregunta 149"}, {"id": "ehu150", "q": "Los delegados y delegadas de prevención son:", "o": ["Los/as responsables de diseñar los Planes de Emergencia.", "Junto con los/as Técnicos/as de Prevención planificarán anualmente la actividad preventiva.", "Los/as representantes de los/as trabajadores y trabajadoras de la Universidad en materia de Prevención y tendrán las competencias y derechos recogidos en la normativa sobre Prevención de Riesgos Laborales.", "Serán los/as responsables de gestionar los planes de Emergencia."], "c": 2, "e": "Los delegados de prevención son los representantes del personal con funciones específicas en prevención de riesgos.", "r": "Ley 31/1995 art. 35 · batería oficial, pregunta 150"}, {"id": "ehu151", "q": "No es función de los centros docentes", "o": ["Adaptar y desarrollar en el Centro la planificación lingüística general.", "Promover la realización de actividades de carácter científico.", "Coordinar e impartir las enseñanzas de un área o varias de conocimiento.", "Elaborar su memoria anual."], "c": 2, "e": "Coordinar e impartir las enseñanzas de una o varias áreas de conocimiento es función de los departamentos, no de los centros.", "r": "Estatutos UPV/EHU (centros y departamentos) · batería oficial, pregunta 151"}, {"id": "ehu152", "q": "¿Qué tipos de centros universitarios configuran la EHU?", "o": ["Propios y Sección de Centros.", "Propios y adscritos.", "Propios y Unidades Delegadas.", "Integrados, Departamentos e Institutos Universitarios."], "c": 1, "e": "La UPV/EHU se configura con centros propios y centros adscritos.", "r": "Estatutos UPV/EHU · batería oficial, pregunta 152"}, {"id": "ehu153", "q": "De acuerdo con sus Estatutos y en el marco de las leves, la EHU actúa en régimen:", "o": ["Foral.", "De autonomía.", "De dependencia funcional.", "De competencias delegadas."], "c": 1, "e": "La Universidad actúa en régimen de autonomía.", "r": "CE art. 27.10; Estatutos UPV/EHU art. 1 · batería oficial, pregunta 153"}, {"id": "ehu154", "q": "¿De quién depende Orgánica y funcionalmente la gerencia?", "o": ["Del Consejo de Gobierno.", "Del/la Vicerrector/a Asuntos Económicos.", "Del/ de la Rector/a.", "Del Consejo Social."], "c": 2, "e": "Respuesta probable: la Gerencia depende orgánica y funcionalmente del Rector o Rectora.", "r": "Estatutos UPV/EHU (Gerencia) · batería oficial, pregunta 154"}, {"id": "ehu155", "q": "El Consejo social de la EHU", "o": ["Ejerce la potestad reglamentaria aprobando las normas de desarrollo y aplicación de los Estatutos de la EHU.", "Puede crear las Comisiones que considere convenientes para el mejor ejercicio de sus funciones.", "Puede crear nuevos campus universitarios.", "Aprueba la programación plurianual de inversiones e infraestructuras."], "c": 3, "e": "Respuesta probable: el Consejo Social aprueba la programación plurianual y el presupuesto.", "r": "LOSU; Ley 3/2004 · batería oficial, pregunta 155"}, {"id": "ehu156", "q": "Para la elección de representantes al Claustro universitario por el personal docente e investigador permanente doctor, la demarcación electoral sera:", "o": ["El Campus.", "El Centro.", "El Departamento.", "El Servicio."], "c": 1, "e": "Respuesta probable: para el PDI permanente doctor la circunscripción es el centro.", "r": "Estatutos UPV/EHU (Claustro) · batería oficial, pregunta 156"}, {"id": "ehu157", "q": "La Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas se aplica al sector público que comprende...", "o": ["La Administración General del Estado y las Administraciones de las Comunidades Autónomas.", "La Administración General del Estado y las Entidades que integran la Administración Local y el sector público institucional.", "Las Administraciones de las Comunidades Autónomas, las Entidades que integran la Administración Local y el sector público institucional.", "La Administración General del Estado, las Administraciones de las Comunidades Autónomas, las Entidades que integran la Administración Local y el sector público institucional."], "c": 3, "e": "La Ley 39/2015 se aplica a la AGE, las CCAA, la Administración Local y el sector público institucional.", "r": "Ley 39/2015 art. 2.1 · batería oficial, pregunta 157"}, {"id": "ehu158", "q": "Según el artículo 2 de la Ley 10/1982 básica de normalización, de normalización del uso del euskera, la lengua propia del País Vasco es:", "o": ["El euskera.", "El euskera, aunque también se puede utilizar el castellano como lengua oficial.", "El euskera, que además es lengua oficial subsidiaria al castellano.", "Todas las respuestas anteriores son incorrectas."], "c": 0, "e": "La lengua propia del País Vasco es el euskera.", "r": "Ley 10/1982 art. 2 · batería oficial, pregunta 158"}, {"id": "ehu159", "q": "Según el artículo 15 de la Ley 10/1982, básica de normalización del uso del euskera, se reconoce a todo el alumnado el derecho de recibir la enseñanza ...:", "o": ["...en euskera obligatoriamente en todos los niveles educativos.", "..en castellano obligatoriamente en todos los niveles educativos.", "...tanto en euskera como en castellano en los diversos niveles educativos.", "Ninguna de las respuestas es correcta."], "c": 2, "e": "Se reconoce a todo el alumnado el derecho a recibir la enseñanza tanto en euskera como en castellano.", "r": "Ley 10/1982 art. 15 · batería oficial, pregunta 159"}, {"id": "ehu160", "q": "Según la Ley 10/1982, básica de normalización del uso del euskera, el Gobierno Vasco regulara los modelos linguísticos a impartir en cada centro educativo teniendo en cuenta:", "o": ["La voluntad de los padres o tutores/as y la situación socio-lingüística de la zona.", "La voluntad de los padres o tutores y la situación socio-económica de las familias.", "La voluntad de los padres o tutores y la situación socio-sanitaria de las familias.", "Las respuestas b) y c) son correctas."], "c": 0, "e": "El Gobierno Vasco regula los modelos lingüísticos teniendo en cuenta la voluntad de padres o tutores y la situación sociolingüística de la zona.", "r": "Ley 10/1982 art. 16 · batería oficial, pregunta 160"}]}, {"id": "b06", "sig": "Bloque 6", "titulo": "Bloque 6. EHU: Estatutos, personal y organización (II)", "sub": "Preguntas 161–192 de la batería oficial (sin respuestas oficiales: resueltas por Claude).", "preguntas": [{"id": "ehu161", "q": "Según la Ley 10/1982, básica de normalización del uso del euskera, las lenguas oficiales en la comunidad autonoma del País Vasco, son:", "o": ["El castellano, que es la única lengua oficial.", "El euskera, que es la única lengua oficial.", "EL euskera y el castellano.", "Todas las respuestas son falsas."], "c": 2, "e": "Las lenguas oficiales en la CAPV son el euskera y el castellano.", "r": "Ley 10/1982 art. 3 · batería oficial, pregunta 161"}, {"id": "ehu162", "q": "Según la Ley 10/1982, básica de normalización del uso del euskera, el euskera es:", "o": ["La lengua propia del País Vasco, junto con el castellano.", "La única lengua propia del País Vasco", "La única lengua oficial del País Vasco.", "Todas las anteriores son correctas."], "c": 1, "e": "La ley dice que la lengua propia del País Vasco es el euskera (no el castellano), aunque ambas sean oficiales.", "r": "Ley 10/1982 art. 2 · batería oficial, pregunta 162"}, {"id": "ehu163", "q": "Según el artículo 14 de la 10/1982, básica de normalización del uso del euskera, ¿Cuál de las siguientes afirmaciones es la correcta?", "o": ["Los poderes públicos adoptarán las medidas tendentes a la progresiva euskaldunización del personal afecto a la Administración Pública de la Comunidad Autónoma del País Vasco.", "En las pruebas selectivas que se realicen para el acceso a las demás plazas se considerará, entre otros méritos, el nivel de conocimiento de las lenguas oficiales en la Comunidad Autónoma Vasca.", "Los poderes públicos determinarán las plazas para las que es preceptivo el conocimiento de ambas lenguas.", "Todas las anteriores son correctas."], "c": 3, "e": "Las tres afirmaciones recogen lo previsto para la Administración en el art. 14.", "r": "Ley 10/1982 art. 14 · batería oficial, pregunta 163"}, {"id": "ehu164", "q": "Según la Ley 10/1982, básica de normalización del uso del euskera, se reconocen a los/as ciudadanos/as del País Vasco los siguientes derechos lingüísticos fundamentales:", "o": ["Derecho a recibir la enseñanza en ambas lenguas oficiales.", "Derecho a recibir en euskera publicaciones periódicas, programaciones de radio y televisión y de otros medios de comunicación.", "Derecho a expresarse en euskera en cualquier reunión.", "Todas las anteriores son correctas."], "c": 3, "e": "La ley reconoce esos tres derechos lingüísticos fundamentales, entre otros.", "r": "Ley 10/1982 art. 6.2 · batería oficial, pregunta 164"}, {"id": "ehu165", "q": "Los actos administrativos producidos por silencio administrativo se denominan:", "o": ["Resoluciones.", "Actos de gravamen.", "Actos desfavorables.", "Actos presuntos."], "c": 3, "e": "Los actos producidos por silencio se denominan actos presuntos.", "r": "Ley 39/2015 art. 24 · batería oficial, pregunta 165"}, {"id": "ehu166", "q": "Los actos administrativos que ponen fin a un procedimiento se denominan:", "o": ["Actos de trámite.", "Resoluciones.", "Recusaciones.", "Recursos."], "c": 1, "e": "Los actos que ponen fin al procedimiento son las resoluciones.", "r": "Ley 39/2015 art. 88 · batería oficial, pregunta 166"}, {"id": "ehu167", "q": "¿En cuál de los siguientes supuestos no se podrá otorgar eficacia retroactiva a un acto administrativo?", "o": ["Cuando se trate de una resolución.", "Cuando se trate de un acto sancionador.", "Cuando produzca efectos favorables al interesado.", "Los actos administrativos siempre pueden tener efectos retroactivos."], "c": 1, "e": "Solo cabe eficacia retroactiva en actos favorables; un acto sancionador no puede ser retroactivo.", "r": "Ley 39/2015 art. 39.3; CE art. 9.3 · batería oficial, pregunta 167"}, {"id": "ehu168", "q": "¿Qué respuesta es la correcta según los Estatutos de la EHU?", "o": ["Las Escuelas, Facultades y Departamentos son los Centros encargados de la organización de a enseñanza, dirigiendo, coordinando y gestionando los procesos académicos conducentes a la obtención de títulos de grado u otras ofertas docentes.", "Las Escuelas, Facultades y Departamentos son los Centros encargados de la organización de aenseñanza, dirigiendo, coordinando y gestionando procesos académicos y administrativos conducentes a la obtención de títulos de grado", "Las Escuelas y Facultades son los Centros encargados de la organización de la enseñanza, dirigiendo, coordinando y gestionando procesos académicos y administrativos conducentes a la obtención de títulos de grado", "Las Facultades y los Departamentos organizan las enseñanzas universitarias y dirigen y gestionan los procesos académicos y administrativos conducentes a la obtención de títulos académicos u otras ofertas docentes."], "c": 2, "e": "Respuesta probable: las facultades y escuelas son los centros que organizan la enseñanza y gestionan los procesos que conducen a títulos de grado.", "r": "Estatutos UPV/EHU (centros) · batería oficial, pregunta 168"}, {"id": "ehu169", "q": "¿Qué respuesta es la correcta según los Estatutos de la EHU?", "o": ["El/la Rector/a es la máxima autoridad académica universitaria de la EHU, ostenta su representación y ejerce su dirección y gobierno.", "El/la Rector/a es la persona responsable de la organización y gestión de los servicios administrativos y económicos de la EHU, de acuerdo con las directrices marcadas por sus órganos de gobierno.", "El/la Rector/a es el/la fedatario/a de los actos y acuerdos de los órganos colegiados de gobierno y de Administración general de la EHU.", "Las respuestas a) y c) son verdaderas."], "c": 0, "e": "El Rector es la máxima autoridad académica, ostenta la representación y ejerce la dirección y gobierno. La gestión económica es del Gerente y la fe pública de la Secretaría General.", "r": "LOSU; Estatutos UPV/EHU · batería oficial, pregunta 169"}, {"id": "ehu170", "q": "Los órganos de Gobierno, representación, dirección y gestión de un centro docente son al menos los siguientes:", "o": ["La Junta de Centro, el Decanato o la Dirección, y la Secretaría Académica.", "La Junta de Centro, el Decanato o la Dirección, la Secretaría Académica y la Administración.", "La Junta de Centro, el Decanato o la Dirección, los Vicedecanatos o Subdirecciones y la Secretaría Académica.", "La Junta de Centro, el Decanato o la Dirección, los Vicedecanatos o Subdirecciones, la Secretaría Académica y la Administración."], "c": 0, "e": "Respuesta probable: Junta de Centro, Decanato o Dirección y Secretaría Académica.", "r": "Estatutos UPV/EHU (centros) · batería oficial, pregunta 170"}, {"id": "ehu171", "q": "Diga cuál de estas afirmaciones es correcta de acuerdo con el art. 2 del Reglamento marco de los departamentos de la EHU:", "o": ["Los Departamentos determinan las necesidades de plantilla de profesores y PERSONAL técnico, de gestión y administración y servicios.", "Los Departamentos eligen al Decano/a o Director/a del Centro.", "Los Departamentos impulsan y apoyan la investigación relativa al área o áreas de conocimiento de su competencia.", "Todas las respuestas son falsas."], "c": 2, "e": "Los departamentos impulsan y apoyan la investigación de sus áreas de conocimiento.", "r": "Reglamento Marco de Departamentos UPV/EHU art. 2 · batería oficial, pregunta 171"}, {"id": "ehu172", "q": "Entre los deberes del personal técnico, de gestión y administración y servicios recogidos en los Estatutos figura el de:", "o": ["Asegurar la continuidad en la buena marcha del servicio, en los supuestos de ausencia de las personas superiores jerárquicas, compañeras o subordinadas.", "Conocer al detalle el plan de estudios de su centro, sabiendo distinguir entre asignaturas troncales y optativas.", "Contar con vehículo propio para sus desplazamientos por razón del trabajo.", "Disponibilidad absoluta para la realización de trabajos extraordinarios."], "c": 0, "e": "Respuesta probable: asegurar la continuidad del servicio en ausencia de superiores, compañeros o subordinados.", "r": "Estatutos UPV/EHU (deberes del PTGAS) · batería oficial, pregunta 172"}, {"id": "ehu173", "q": "Corresponde al personal técnico, de gestión y administración y servicios de la EHU:", "o": ["El desarrollo de los procesos de gestión y de soporte necesarios para el cumplimiento por parte de la EHU de sus objetivos y funciones.", "El apoyo, asistencia y asesoramiento a los órganos de gobierno universitario.", "El desarrollo de las tareas de apoyo a la docencia e investigación.", "Todas las respuestas anteriores son correctas."], "c": 3, "e": "Al PTGAS le corresponden la gestión y el soporte, el apoyo a los órganos de gobierno y el apoyo a la docencia e investigación.", "r": "Estatutos UPV/EHU (PTGAS) · batería oficial, pregunta 173"}, {"id": "ehu174", "q": "El/la secretario/a académico/a de un centro es:", "o": ["La persona que ejerce la dirección jerárquica del personal técnico, de gestión y administración y servicios de la Secretaría del Centro.", "La persona fedataria de los actos y acuerdos de los órganos colegiados de gobierno, representación y administración del centro.", "La persona responsable de proponer los limites de plazas al Vicerrectorado de Campus.", "La persona que coordina los Departamentos que imparten docencia en el centro."], "c": 1, "e": "El Secretario Académico es fedatario de los actos y acuerdos de los órganos colegiados del centro.", "r": "Estatutos UPV/EHU (centros) · batería oficial, pregunta 174"}, {"id": "ehu175", "q": "(Señale la afirmación correcta). Es personal funcionario interino:", "o": ["Quien en virtud de nombramiento y por razones de urgencia y necesidad sustituya a personal funcionario de carrera en el desempeño de su puesto de trabajo en los casos de ausencia temporal.", "Quien en virtud de contrato laboral y por razones de urgencia sustituya a personal funcionario de carrera en el desempeño de su puesto de trabajo en los casos de ausencia temporal.", "Quien en virtud de nombramiento y por razones de confianza sustituya a personal funcionario de carrera en el desempeño de su puesto de trabajo en los casos de ausencia temporal.", "Quien en virtud de confianza y por razones de urgencia sustituya a personal funcionario de carrera en el desempeño de su puesto de trabajo en los casos de ausencia temporal."], "c": 0, "e": "Es interino quien, por nombramiento y por necesidad y urgencia, sustituye transitoriamente a un funcionario de carrera.", "r": "TREBEP art. 10.1 · batería oficial, pregunta 175"}, {"id": "ehu176", "q": "De las funciones señaladas, ¿Cuál no puede desempeñarse por el campus, según los Estatutos de la EHU?", "o": ["Adoptar, desarrollar y ejecutar Programas o Medidas Generales", "Desarrollar y potenciar las relaciones institucionales, así como la extensión cultural y universitaria.", "Aprobar la creación de un departamento del Campus.", "Gestionar los recursos e infraestructuras de uso compartido y de apoyo a la docencia e investigación existentes en su ámbito."], "c": 2, "e": "Respuesta probable: aprobar la creación de un departamento no corresponde al campus.", "r": "Estatutos UPV/EHU (campus) · batería oficial, pregunta 176"}, {"id": "ehu177", "q": "Según los Estatutos de la EHU, son enseñanzas universitarias:", "o": ["Las enseñanzas conducentes a la obtención de títulos oficiales reconocidos u homologados.", "Las enseñanzas conducentes a la obtención del Título de Bachiller.", "Las enseñanzas de Formación Profesional.", "Todas las anteriores son enseñanzas universitarias."], "c": 0, "e": "Son enseñanzas universitarias las que conducen a títulos oficiales y propios de la Universidad, no el bachillerato ni la FP.", "r": "Estatutos UPV/EHU · batería oficial, pregunta 177"}, {"id": "ehu178", "q": "De los siguientes, indique el único que es un centro adscrito a la EHU:", "o": ["Escuela de Ingeniería de Gipuzkoa", "Escuela de Ingeniería de Bilbao", "Escuela Universitaria de Enfermería de Vitoria-Gasteiz", "Escuela Técnica Superior de Arquitectura"], "c": 2, "e": "La Escuela Universitaria de Enfermería de Vitoria-Gasteiz es un centro adscrito.", "r": "Centros adscritos UPV/EHU · batería oficial, pregunta 178"}, {"id": "ehu179", "q": "Conforme al Plan actual de igualdad de mujeres y hombres la EHU debe garantizar la igualdad:", "o": ["Sólo en el PDI.", "Sólo en el PTGAS.", "Sólo en el estudiantado.", "En toda la comunidad universitaria."], "c": 3, "e": "El Plan de Igualdad abarca a toda la comunidad universitaria.", "r": "Plan de Igualdad UPV/EHU · batería oficial, pregunta 179"}, {"id": "ehu180", "q": "Según el DL1/2023 de 16 marzo, por el que se aprueba el texto refundido de la Ley para la igualdad de mujeres y hombres y vidas libres de violencia machista para las mujeres, la formación en materia de igualdad de mujeres y hombres para el personal de los poderes públicos vascos debe ser:", "o": ["Voluntaria, progresiva y periódica.", "Básica, progresiva, permanente y obligatoria.", "Específica, puntual y evaluable.", "Avanzada, obligatoria y exclusivamente presencial."], "c": 1, "e": "La formación en igualdad para el personal de los poderes públicos vascos debe ser básica, progresiva, permanente y obligatoria.", "r": "DL 1/2023 (Igualdad) art. 17 · batería oficial, pregunta 180"}, {"id": "ehu181", "q": "Relacionado con el presupues to de una entidad pública, señala la afirmación correcta:", "o": ["Los Presupuestos de una Entidad Pública están constituidos por las obligaciones que prevé reconocer durante el ejercicio correspondiente y por los derechos, que como máximo, puede liquidar dicha Entidad.", "Los Presupuestos de una Entidad Pública están constituidos por las obligaciones y derechos, que como máximo, puede reconocer dicha Entidad.", "Los Presupuestos de una Entidad Pública están constituidos por las obligaciones que, como máximo, puede reconocer dicha Entidad y por los derechos que prevé liquidar durante el ejercicio correspondiente.", "Los Presupuestos de una Entidad Pública están constituidos por las obligaciones y derechos que se prevé reconocer durante el correspondiente ejercicio."], "c": 2, "e": "El presupuesto recoge las obligaciones que, como máximo, puede reconocer la entidad y los derechos que prevé liquidar.", "r": "Normativa presupuestaria (concepto de presupuesto) · batería oficial, pregunta 181"}, {"id": "ehu182", "q": "El proyecto de Ley de presupuestos de Euskadi se presentará ante el parlamento:", "o": ["Porel Gobierno, con anterioridad al 1 de noviembre del ejercicio anterior a que se refiere el citado proyecto.", "Porel Departamento de Hacienda y Administración Pública.", "Por el Gobierno con anterioridad al 31 de diciembre del ejercicio anterior a que se refiere el citado proyecto.", "Por una Comisión específica constituida por los titulares de Hacienda de las tres Diputaciones Vascas, antes del 30 de noviembre del ejercicio anterior a que se refiere el citado proyecto."], "c": 0, "e": "El Gobierno presenta el proyecto de Ley de Presupuestos antes del 1 de noviembre del ejercicio anterior.", "r": "Régimen presupuestario de Euskadi · batería oficial, pregunta 182"}, {"id": "ehu183", "q": "Los presupuestos Generales de Euskadi están integrados por los correspondientes a cada una de las entidades que componen el sector público de la comunidad:", "o": ["Administración de la Comunidad Autónoma, sociedades públicas y fundaciones del sector público de la Comunidad Autónoma.", "Administración de la Comunidad Autónoma, organismos autónomos, sociedades públicas, fundaciones del sector público de la Comunidad Autónoma y consorcios del sector público de la Comunidad Autónoma.", "Administración de la Comunidad Autónoma, sociedades públicas, entes públicos de derecho privado, fundaciones del sector público de la Comunidad Autónoma y consorcios del sector público de la Comunidad Autónoma.", "Administración de la Comunidad Autónoma, organismos autónomos, sociedades públicas, entes públicos de derecho privado, fundaciones del sector público de la Comunidad Autónoma y consorcios del sector público de la Comunidad Autónoma."], "c": 3, "e": "Integran los Presupuestos Generales de Euskadi la Administración, organismos autónomos, entes públicos de derecho privado, sociedades públicas, fundaciones y consorcios del sector público.", "r": "Régimen presupuestario de Euskadi · batería oficial, pregunta 183"}, {"id": "ehu184", "q": "Qué respuesta no es correcta sobre los presupuestos Generales:", "o": ["Los presupuestos son una previsión de ingresos y gastos para un periodo de tiempo.", "Los presupuestos se basan en la certeza de unos ingresos y en la previsión de unos gastos.", "Uno de los objetivos de los presupuestos es la redistribución de la renta.", "Los presupuestos son instrumentos de las administraciones con dimensión política, económica y jurídica."], "c": 1, "e": "Es incorrecta: el presupuesto se basa en la previsión de ingresos y en el límite de gastos, no en la certeza de los ingresos.", "r": "Concepto de presupuesto · batería oficial, pregunta 184"}, {"id": "ehu185", "q": "Según los Estatutos de la EHU, no se consideran remanentes específicos y, por LO tanto, no generan crédito en el ejercicio siguiente:", "o": ["Los créditos pendientes de ejecución correspondientes a proyectos e infraestructuras de investigación.", "Los créditos pendientes de ejecución y que han sido dotados con la subvención ordinaria de la Comunidad Autónoma del País Vasco.", "Los créditos pendientes de ejecución dotados con recursos externos finalistas", "Los créditos pendientes de ejecución correspondientes a gastos que amparen compromisos contraídos y que por causas justificadas no hayan podido realizarse."], "c": 1, "e": "Respuesta probable: los créditos dotados con la subvención ordinaria no son remanentes específicos.", "r": "Estatutos UPV/EHU (régimen económico) · batería oficial, pregunta 185"}, {"id": "ehu186", "q": "Según los Estatutos de la Universidad, las actividades ordinarias de la EHU son cubiertas por:", "o": ["Los rendimientos procedentes de su patrimonio.", "Los ingresos procedentes de los contratos previstos en el art.83 de la Ley Orgánica 6/2000, de Universidades, de acuerdo con el régimen económico que para dichos contratos establezca el Consejo de Gobierno.", "Las transferencias para gastos corrientes y de capital fijadas, anualmente, por la Comunidad Autónoma del País Vasco.", "El producto de las operaciones de crédito que concierte, previa autorización de la Comunidad autónoma del País Vasco."], "c": 2, "e": "Respuesta probable: las actividades ordinarias se cubren con las transferencias anuales de la Comunidad Autónoma.", "r": "Estatutos UPV/EHU (financiación) · batería oficial, pregunta 186"}, {"id": "ehu187", "q": "El acto por el cual se formaliza la realización concreta de obras y la prestación o suministro de bienes y servicios con la consiguiente reserva de crédito de pago por importe y condiciones exactamente determinadas, es:", "o": ["La autorización del gasto.", "La disposición del gasto.", "El reconocimiento de la obligación.", "La orden del pago."], "c": 1, "e": "La disposición (compromiso) del gasto formaliza la realización concreta de obras o servicios con reserva de crédito por importe exacto.", "r": "Fases del gasto: A-D-O-P · batería oficial, pregunta 187"}, {"id": "ehu188", "q": "Conforme al artículo 133 de los Estatutos de la EHU para la Constitución de un departamento el número mínimo de PDI será:", "o": ["12 personas del personal docente e investigador con vinculación permanente a tiempo completo o equivalente que deberán ser, además, doctores/as y, al menos, una dotación de personal técnico, de gestión y administración y servicios.", "18 personas del personal docente e investigador con vinculación permanente a tiempo completo o equivalente, de las cuales, al menos 12 serán doctores/as.", "18 personas del personal docente e investigador con vinculación permanente a tiempo completo o equivalente, de las cuales, al menos 12 serán doctores/as y, al menos, una dotación de personal técnico, de gestión y administración y servicios.", "18 personas del personal docente e investigador con vinculación permanente, de las cuales, al menos 12 serán doctores/as a tiempo completo o equivalente."], "c": 2, "e": "Respuesta probable: 18 PDI permanentes a tiempo completo, al menos 12 doctores, y al menos una dotación de PTGAS.", "r": "Estatutos UPV/EHU art. 133 · batería oficial, pregunta 188"}, {"id": "ehu189", "q": "Los departamentos universitarios son los encargados de coordinar e impartir las enseñanzas en uno o varios centros ¿Cual es el criterio de Constitución de los departamentos?", "o": ["Por ámbitos de conocimiento.", "Por Centros en los que imparten docencia.", "Por Campus.", "Poráreas de investigación."], "c": 0, "e": "Los departamentos se constituyen por ámbitos de conocimiento.", "r": "LOSU; Estatutos UPV/EHU · batería oficial, pregunta 189"}, {"id": "ehu190", "q": "De acuerdo con los Estatutos de la EHU, la dirección funcional del personal técnico, de gestión y administración y servicios de los departamentos le corresponde:", "o": ["Al Decano o Director del Centro.", "Al Administrador del Centro.", "Al Director del Departamento.", "A la Junta de Centro."], "c": 2, "e": "Respuesta probable: la dirección funcional del PTGAS del departamento corresponde al director del departamento.", "r": "Estatutos UPV/EHU · batería oficial, pregunta 190"}, {"id": "ehu191", "q": "¿Cúal de los siguientes elementos no es software?:", "o": ["Hoja de cálculo.", "Procesador de texto.", "AutoCAD.", "Todos lo son."], "c": 3, "e": "Hoja de cálculo, procesador de texto y AutoCAD son todos software.", "r": "Informática básica · batería oficial, pregunta 191"}, {"id": "ehu192", "q": "De los siguientes dispositivos cual no pertenece a la periferia de un ordenador:", "o": ["El escáner.", "El teclado.", "La impresora.", "El Sistema operativo."], "c": 3, "e": "El sistema operativo es software, no un periférico.", "r": "Informática básica · batería oficial, pregunta 192"}]}, {"id": "b07", "sig": "Bloque 7", "titulo": "Bloque 7. Ofimática, permisos y comunicación", "sub": "Preguntas 193–227 de la batería oficial (sin respuestas oficiales: resueltas por Claude).", "preguntas": [{"id": "ehu193", "q": "¿Que es una intranet?", "o": ["Es una red privada ubicada en Internet a la que sólo pueden acceder un grupo de usuarios/as cumpliendo unas condiciones determinadas.", "Es una red privada y clandestina ubicada en Internet.", "Es una red privada dentro de una compañía u organización que proporciona herramientas de Internet.", "Ninguna de las anteriores."], "c": 2, "e": "Una intranet es una red privada dentro de una organización que usa herramientas de Internet.", "r": "Informática básica · batería oficial, pregunta 193"}, {"id": "ehu194", "q": "El término “multimedia” está asociado:", "o": ["Al manejo exclusivo de texto.", "Al manejo exclusivo de texto y gráficos.", "Al manejo exclusivo de texto, gráficos e imagen.", "Al manejo de texto, gráficos, imagen y sonido."], "c": 3, "e": "Multimedia combina texto, gráficos, imagen y sonido.", "r": "Informática básica · batería oficial, pregunta 194"}, {"id": "ehu195", "q": "¿Qué significado tiene el que una herramienta sea multiplataforma?:", "o": ["Que puede correr en máquinas con múltiples procesadores.", "Que es independiente del hardware y del Sistema Operativo de la máquina en la que se ejecuta.", "Que puede realizar funciones de procesador de texto y hoja de cálculo simultáneamente.", "Que ha evolucionado a lo largo de los años y por ello se dispone de varias versiones del producto."], "c": 1, "e": "Multiplataforma significa que funciona con independencia del hardware y del sistema operativo.", "r": "Informática básica · batería oficial, pregunta 195"}, {"id": "ehu196", "q": "En el paquete ofimático microsoft office la herramienta de base de datos es:", "o": ["Access.", "Word.", "Excel.", "Outlook."], "c": 0, "e": "La base de datos de Microsoft Office es Access.", "r": "Ofimática · batería oficial, pregunta 196"}, {"id": "ehu197", "q": "La herramienta “Power Point\" la relacionaría principalmente con:", "o": ["Exposiciones y presentaciones.", "Control de agendas.", "Elaboración de gráficos.", "Correo electrónico."], "c": 0, "e": "PowerPoint sirve para exposiciones y presentaciones.", "r": "Ofimática · batería oficial, pregunta 197"}, {"id": "ehu198", "q": "Una de las funcionalidades comunes a la mayor parte de productos ofimáticos es la disponibilidad de barras de botones. El objetivo de las mismas es:", "o": ["Evitarla utilización del ratón.", "Proporcionar acceso rápido a funcionalidades que pueden hacerse a través del teclado o a través de comandos del menú.", "Mostrar las características del sistema operativo de la máquina sobre la que se trabaja.", "Permitir el acceso directo al resto de aplicativos abiertos en el equipo de trabajo."], "c": 1, "e": "Las barras de botones dan acceso rápido a funciones que también están en menús o atajos.", "r": "Ofimática · batería oficial, pregunta 198"}, {"id": "ehu199", "q": "Si deseo intercambiar información entre aplicaciones, éstas deberán ser:", "o": ["Complementarias.", "Amigables.", "Automatizables.", "Compatibles."], "c": 3, "e": "Para intercambiar información, las aplicaciones deben ser compatibles.", "r": "Informática básica · batería oficial, pregunta 199"}, {"id": "ehu200", "q": "Las condiciones de especial dificultad técnica, dedicación, responsabilidad, incompatibilidad y peligrosidad o penosidad de un puesto de trabajo son retribuidas por:", "o": ["El sueldo.", "El sueldo y el complemento de destino.", "El sueldo y el complemento específico.", "El complemento específico."], "c": 3, "e": "El complemento específico retribuye la especial dificultad técnica, dedicación, responsabilidad, incompatibilidad, peligrosidad o penosidad.", "r": "TREBEP art. 24; Ley 11/2022 art. 122 · batería oficial, pregunta 200"}, {"id": "ehu201", "q": "El término “ofimática” se asocia a:", "o": ["Automatización de las oficinas y de los procesos allí realizados.", "A la informática de forma general.", "A las redes informáticas desplegadas en las oficinas.", "A los procesadores de texto que permiten eliminar las máquinas de escribir."], "c": 0, "e": "Ofimática es la automatización de las oficinas y de sus procesos.", "r": "Informática básica · batería oficial, pregunta 201"}, {"id": "ehu202", "q": "En términos informáticos cuando hablamos de un “tutorial” estamos haciendo referencia a:", "o": ["Punto de consulta telefónica sobre un producto.", "Tipo de ayuda a modo libro en formato electrónico donde se describen las principales características y funcionalidades de un producto.", "Una automatización en un único comando de una operación que requiera varios comandos consecutivos.", "Un aplicativo ofimático desarrollado en un lenguaje orientado a objetos"], "c": 1, "e": "Un tutorial es una ayuda tipo manual electrónico que explica las funciones de un producto.", "r": "Informática básica · batería oficial, pregunta 202"}, {"id": "ehu203", "q": "La corrección ortográfica en un procesador de texto hace uso del:", "o": ["Ratón.", "Teclado.", "Diccionario.", "Lista de sinónimos."], "c": 2, "e": "El corrector ortográfico compara el texto con un diccionario.", "r": "Ofimática · batería oficial, pregunta 203"}, {"id": "ehu204", "q": "Las licencias por paternidad:", "o": ["Su concesión se condiciona a la autorización del superior jerárquico.", "Serán retribuidas.", "Se concederán por una sola vez.", "Se interrumpirán si las necesidades de servicio lo requieren."], "c": 1, "e": "Los permisos por nacimiento son retribuidos.", "r": "TREBEP art. 49 · batería oficial, pregunta 204"}, {"id": "ehu205", "q": "(Señale la respuesta correcta). Los permisos por asuntos propios:", "o": ["No darán lugar a retribución alguna.", "Su duración acumulada no podrá exceder de tres meses cada dos años.", "Estará siempre subordinada a las necesidades del servicio.", "Todas las respuestas anteriores son correctas."], "c": 3, "e": "Las licencias por asuntos propios no son retribuidas, no superan tres meses cada dos años y están subordinadas a las necesidades del servicio.", "r": "Normativa de permisos y licencias del personal funcionario · batería oficial, pregunta 205"}, {"id": "ehu206", "q": "En la EHU la elaboración de los planes de formación del personal corresponde a:", "o": ["La Comisión de Planificación.", "El Comité de Planes Formativos.", "La Comisión de Formación, Perfeccionamiento y Reciclaje.", "La Comisión de Euskaldunización."], "c": 2, "e": "Respuesta probable: la Comisión de Formación, Perfeccionamiento y Reciclaje.", "r": "Normativa de formación UPV/EHU · batería oficial, pregunta 206"}, {"id": "ehu207", "q": "La reducción de la jornada laboral podrá concederse, entre otras situaciones, por una de las siguientes:", "o": ["Guarda legal de menor de doce años.", "Cuidado de parientes de hasta 2* grado de consanguinidad o afinidad.", "Adopción de menor extracomunitario.", "Trabajo voluntario en organización sin ánimo de lucro."], "c": 0, "e": "Cabe reducción de jornada por guarda legal de menor de doce años.", "r": "TREBEP art. 48.h · batería oficial, pregunta 207"}, {"id": "ehu208", "q": "A efectos de la concesión de licencias no se consideran deberes inexcusables de caracter público o personal:", "o": ["Examen del carnet de conducir.", "Citaciones en Juzgados.", "Consultas en gabinetes jurídicos.", "Renovación del DNI."], "c": 2, "e": "Respuesta probable: una consulta en un gabinete jurídico no es un deber inexcusable de carácter público o personal.", "r": "Normativa de permisos UPV/EHU · batería oficial, pregunta 208"}, {"id": "ehu209", "q": "De entre los siguientes sólo un puesto de trabajo corresponde al personal funcionario de la EHU.", "o": ["Técnico/a Auxiliar de Biblioteca.", "Técnico/a Especialista de Laboratorio.", "Oficial de Mantenimiento", "Técnico/a de Sistemas."], "c": 0, "e": "Respuesta probable: Técnico/a Auxiliar de Biblioteca es puesto de personal funcionario; los demás son de plantilla laboral.", "r": "RPT del PTGAS UPV/EHU · batería oficial, pregunta 209"}, {"id": "ehu210", "q": "Al acercarse una persona a un puesto de información al público, LO más apropiado es que el personal que esté atendiendo:", "o": ["Le mire seriamente sin hacer ningún gesto de aproximación.", "Siga realizando cualquier tarea indiferentemente.", "Le reciba con algún gesto de disponibilidad que facilite la comunicación.", "Intente dar muestras de una intensa actividad."], "c": 2, "e": "Se recibe a la persona con un gesto de disponibilidad que facilite la comunicación.", "r": "Atención al público · batería oficial, pregunta 210"}, {"id": "ehu211", "q": "Los elementos básicos en la comunicación son:", "o": ["Persona emisora, mensaje, canal, persona receptora, código, ruido y retroalimentación.", "Persona emisora, persona receptora y mensaje.", "Persona emisora, canal, persona receptora y código.", "Persona receptora, mensaje, canal y código."], "c": 0, "e": "Los elementos son emisor, mensaje, canal, receptor, código, ruido y retroalimentación.", "r": "Teoría de la comunicación · batería oficial, pregunta 211"}, {"id": "ehu212", "q": "La comunicación supone un proceso de transmisión y comprensión de un mensaje que seda:", "o": ["Unidireccionalmente, de la persona receptora a la emisora.", "Unidireccionalmente, de la persona emisora a la receptora.", "Bidireccionalmente, exige respuesta de verificación por parte de la persona receptora.", "Lo importante es el lugar donde se coloca la persona receptora."], "c": 2, "e": "La comunicación es bidireccional y exige respuesta de verificación del receptor.", "r": "Teoría de la comunicación · batería oficial, pregunta 212"}, {"id": "ehu213", "q": "Para conseguir que una comunicación sea correcta:", "o": ["Es conveniente utilizar expresiones vacilantes o inseguras.", "Es positivo el uso de palabras malsonantes para afianzar nuestra situación.", "El uso de lenguaje técnico facilita la comprensión.", "Se tratará de utilizar palabras y gestos adecuados a lo que se quiera transmitir."], "c": 3, "e": "Hay que usar palabras y gestos adecuados a lo que se quiere transmitir.", "r": "Teoría de la comunicación · batería oficial, pregunta 213"}, {"id": "ehu214", "q": "En un proceso de comunicación, se denomina \"feedback\":", "o": ["Al método por el que se capta la atención de la persona receptora.", "A la información que recoge la persona emisora sobre los efectos que su comunicación produce en la persona receptora.", "A la escucha pasiva por parte de la persona receptora.", "A la necesidad de interrumpir la comunicación."], "c": 1, "e": "El feedback es la información que recibe el emisor sobre los efectos de su mensaje en el receptor.", "r": "Teoría de la comunicación · batería oficial, pregunta 214"}, {"id": "ehu215", "q": "Se considera que una comunicación se ha realizado con éxito:", "o": ["Si la persona emisora se ha expresado de forma nítida.", "Al comprobar la persona emisora que su mensaje ha sido entendido.", "Si la persona receptora ha adaptado su mensaje a la emisora.", "Se deberá hacer una comprobación posterior."], "c": 1, "e": "La comunicación tiene éxito cuando el emisor comprueba que su mensaje ha sido entendido.", "r": "Teoría de la comunicación · batería oficial, pregunta 215"}, {"id": "ehu216", "q": "Para poder trasmitir correctamente una información:", "o": ["Es importante captar la atención de la persona interlocutora.", "Es necesario conocer bien a la persona interlocutora.", "No adquiere importancia alguna la actitud de la persona interlocutora.", "Lo que menos importa es conocer el contenido del mensaje que se quiere trasmitir."], "c": 0, "e": "Para transmitir bien una información hay que captar la atención del interlocutor.", "r": "Teoría de la comunicación · batería oficial, pregunta 216"}, {"id": "ehu217", "q": "La información que recibe el/la ciudadano/a en sus trámites con la administración debe ser:", "o": ["Clara.", "Incoherente.", "Difusa.", "La respuesta a) y la respuesta b)."], "c": 0, "e": "La información debe ser clara.", "r": "Atención a la ciudadanía · batería oficial, pregunta 217"}, {"id": "ehu218", "q": "El/la ciudadano/a necesita en sus trámites con la administración que el/la funcionario/a:", "o": ["Dé respuesta a sus necesidades de información.", "Preste ayuda para esos trámites.", "Dispense un trato humano aceptable y adecuado a su calidad de ciudadano.", "Todas las respuestas son correctas."], "c": 3, "e": "Necesita información, ayuda en los trámites y un trato humano adecuado.", "r": "Atención a la ciudadanía · batería oficial, pregunta 218"}, {"id": "ehu219", "q": "Cuando nos viene un/a ciudadano/a con un comportamiento agresivo debemos:", "o": ["Tender a realizar juicios, a buscarle defectos, a exigirle.", "Hacerle ver que la culpa es suya.", "Negociar haciéndole ver que su problema nos preocupa.", "Laa) yla c) son correctas."], "c": 2, "e": "Ante un comportamiento agresivo hay que negociar mostrando que su problema nos preocupa, sin juzgar ni culpar.", "r": "Atención a la ciudadanía · batería oficial, pregunta 219"}, {"id": "ehu220", "q": "¿Cúal de estas afirmaciones es correcta en la atención al ciudadano/a?:", "o": ["La comunicación ha de organizarse sin eliminar los prejuicios personales.", "La comunicación ha de organizarse sin prever el comportamiento del receptor/a.", "La comunicación ha de organizarse y planificarse elaborando un mensaje complicado.", "La comunicación ha de organizarse definiendo los objetivos del mensaje claro y sencillo."], "c": 3, "e": "La comunicación se organiza definiendo los objetivos con un mensaje claro y sencillo.", "r": "Atención a la ciudadanía · batería oficial, pregunta 220"}, {"id": "ehu221", "q": "Para conseguir la participación de nuestro interlocutor/a en la comunicación, debemos:", "o": ["Adoptar una escucha pasiva, confundiendo escuchar con oír.", "Comprender al emisor/a y su mensaje asegurándonos de que hemos entendido.", "No tomar notas de lo que dice, aunque fuese necesario.", "Ser comprensivo/a con el interlocutor/a y escucharle distraídamente."], "c": 1, "e": "Hay que comprender al emisor y su mensaje, asegurándonos de haberlo entendido.", "r": "Escucha activa · batería oficial, pregunta 221"}, {"id": "ehu222", "q": "Entre las causas de los fallos en la comunicación están:", "o": ["Enviamos mensajes bien elaborados y vocalizamos adecuadamente.", "Sabemos escuchar.", "Utilizamos un lenguaje excesivamente técnico.", "Todas las respuestas son correctas"], "c": 2, "e": "Un lenguaje excesivamente técnico es causa de fallos en la comunicación.", "r": "Teoría de la comunicación · batería oficial, pregunta 222"}, {"id": "ehu223", "q": "¿Como debemos atender las reclamaciones del ciudadano/a?", "o": ["Recoger con calma y consideración la reclamación", "Dejar hablar, escuchar y no entrar en la discusión.", "Permanecer calmado/a.", "Todas las respuestas son correctas."], "c": 3, "e": "Las tres actitudes son correctas ante una reclamación.", "r": "Atención a la ciudadanía · batería oficial, pregunta 223"}, {"id": "ehu224", "q": "La escucha activa:", "o": ["Esun conjunto de acciones no verbales destinadas a la consecución de una escucha positiva.", "Es una comunicación bidireccional.", "Es el objeto de acciones verbales destinadas a la consecución de una escucha óptima.", "Es el conjunto de acciones verbales y no verbales destinadas a la consecución de una escucha óptima."], "c": 3, "e": "La escucha activa es el conjunto de acciones verbales y no verbales para lograr una escucha óptima.", "r": "Escucha activa · batería oficial, pregunta 224"}, {"id": "ehu225", "q": "(Señale la respuesta incorrecta). Según el artículo 11.2 de la Ley 39/2015, de 1 de octubre, de procedimiento administrativo común, es obligatoria la firma por parte de los/as interesados/as para...", "o": ["Formular solicitudes.", "Presentar declaraciones responsables o comunicaciones.", "Firmar acuse de recibo en las notificaciones electrónicas.", "Renunciar a derechos."], "c": 2, "e": "La firma es obligatoria para solicitar, presentar declaraciones o comunicaciones, recurrir, desistir y renunciar; no figura el acuse de recibo.", "r": "Ley 39/2015 art. 11.2 · batería oficial, pregunta 225"}, {"id": "ehu226", "q": "Si el/la funcionario/a atiende una llamada directamente, deberá en primer lugar:", "o": ["Darlos buenos días/tardes y preguntar qué desea.", "Preguntar el nombre de la persona usuaria.", "Preguntar el motivo de la llamada.", "Identificar la unidad a la que se está llamando."], "c": 3, "e": "Lo primero es identificar la unidad a la que se llama.", "r": "Atención telefónica · batería oficial, pregunta 226"}, {"id": "ehu227", "q": "El/la funcionario/a que recibe una reclamación de una persona usuaria:", "o": ["Ha de negarse a recibirla.", "Debe convencer a la persona usuaria que no la presente.", "Debe recibir cualquier tipo de reclamación que la persona usuaria quiera presentar.", "La persona usuaria no puede realizar reclamaciones."], "c": 2, "e": "Debe recibir cualquier reclamación que la persona quiera presentar.", "r": "Atención a la ciudadanía · batería oficial, pregunta 227"}]}, {"id": "b08", "sig": "Bloque 8", "titulo": "Bloque 8. Igualdad, plazos, transparencia y protección de datos", "sub": "Preguntas 228–300 de la batería oficial (sin respuestas oficiales: resueltas por Claude).", "preguntas": [{"id": "ehu228", "q": "La sociedad, en la que se produce un desequilibrio en el reparto del poder, beneficiando a los hombres en perjuicio de los derechos o del libre ejercicio de los derechos de las mujeres, recibe la denominación de:", "o": ["Sociedad masculinizada.", "Patriarcado.", "Sociedad machista.", "Androgenia."], "c": 1, "e": "Esa organización social se denomina patriarcado.", "r": "Conceptos de igualdad · batería oficial, pregunta 228"}, {"id": "ehu229", "q": "La perspectiva o análisis de género es:", "o": ["Un constructor político.", "Un concepto sociológico.", "Una herramienta de análisis.", "Una forma de interpretar las diferencias de sexo."], "c": 2, "e": "La perspectiva de género es una herramienta de análisis.", "r": "Conceptos de igualdad · batería oficial, pregunta 229"}, {"id": "ehu230", "q": "¿Qué organo preside la Comisión interinstitucional para la igualdad de mujeres y hombres?", "o": ["La Consejera de Igualdad, Justicia y Políticas Sociales.", "La Directora de Emakunde.", "El Lehendakari del Gobierno Vasco.", "La persona presidenta del Parlamento Vasco."], "c": 2, "e": "La preside la persona que ostenta la presidencia de Emakunde, que es el Lehendakari.", "r": "DL 1/2023 (Igualdad) · batería oficial, pregunta 230"}, {"id": "ehu231", "q": "En el ámbito de la igualdad, las acciones positivas:", "o": ["Tienen un carácter permanente.", "Tienen un carácter temporal.", "Tienen un carácter discriminatorio.", "Tienen un carácter no transversal."], "c": 1, "e": "Las acciones positivas son medidas temporales.", "r": "DL 1/2023; LO 3/2007 art. 11 · batería oficial, pregunta 231"}, {"id": "ehu232", "q": "¿Qué elemento refuerza la LOSU en materia de igualdad?", "o": ["Eliminación de unidades de igualdad.", "Planes de igualdad y protocolos contra la violencia de género.", "Sustitución de comisiones por órganos externos.", "Reducción de la representación femenina."], "c": 1, "e": "La LOSU refuerza los planes de igualdad y los protocolos contra la violencia de género.", "r": "LOSU (LO 2/2023) · batería oficial, pregunta 232"}, {"id": "ehu233", "q": "El indicativo “rómpase en caso de incendio” se asocia a:", "o": ["Extintores fijos.", "Hidrantes.", "Rociadores.", "Una BIE (boca de incendios equipada)."], "c": 3, "e": "El letrero «Rómpase en caso de incendio» está en la boca de incendios equipada (BIE).", "r": "Protección contra incendios · batería oficial, pregunta 233"}, {"id": "ehu234", "q": "Cuando necesitamos una intervención rápida contra el fuego, de una manera automática, colocaremos:", "o": ["BIE.", "Extintores de espuma.", "Sprinklers.", "Hidrantes."], "c": 2, "e": "Los rociadores automáticos (sprinklers) actúan solos y con rapidez.", "r": "Protección contra incendios · batería oficial, pregunta 234"}, {"id": "ehu235", "q": "(Señale la respuesta correcta). En la institución, contará con una instalación de alumbrado de emergencia:", "o": ["Todos los recintos cuya ocupación sea mayor de 50 personas.", "Los aseos de planta en edificios de acceso público.", "Las escaleras y pasillos protegidos.", "Los almacenes de productos farmacológicos y depósitos de residuos y basuras."], "c": 2, "e": "Respuesta probable: escaleras y pasillos protegidos deben tener alumbrado de emergencia.", "r": "CTE DB-SUA 4 · batería oficial, pregunta 235"}, {"id": "ehu236", "q": "En los sistemas de alarma, las siglas “AT” corresponden a:", "o": ["Aparatos de tensión.", "Apertura tipo.", "Alta tensión.", "Acometida de transporte."], "c": 2, "e": "Respuesta probable: AT significa alta tensión.", "r": "Instalaciones · batería oficial, pregunta 236"}, {"id": "ehu237", "q": "Cuando los plazos se señalen por días, según la Ley 39/2015, de 1 de octubre, en su computo habra que excluir:", "o": ["Los domingos.", "Los declarados festivos.", "Los sábados.", "Los sábados, los domingos y los declarados festivos."], "c": 3, "e": "En los plazos por días se excluyen sábados, domingos y festivos.", "r": "Ley 39/2015 art. 30.2 · batería oficial, pregunta 237"}, {"id": "ehu238", "q": "En las normas y actos administrativos, si el plazo de fija en meses, se computara:", "o": ["De fecha a fecha, a partir del mismo día de la notificación o publicación.", "30 días naturales.", "30 días hábiles.", "A partir del día siguiente al de la notificación o publicación del acto de que se trate."], "c": 0, "e": "Los plazos en meses se computan de fecha a fecha.", "r": "Ley 39/2015 art. 30.4 · batería oficial, pregunta 238"}, {"id": "ehu239", "q": "Si el último día de un plazo administrativo es inhábil:", "o": ["El plazo expira el día anterior.", "El día en cuestión se entiende hábil a los solos efectos de ese trámite.", "El plazo se entiende prorrogado al primer día hábil siguiente.", "No puede darse este supuesto."], "c": 2, "e": "Si el último día es inhábil, el plazo se prorroga al primer día hábil siguiente.", "r": "Ley 39/2015 art. 30.5 · batería oficial, pregunta 239"}, {"id": "ehu240", "q": "Los plazos administrativos expresados en días se cuenta, por regla general, a partir de:", "o": ["El mismo día de la notificación o publicación.", "El día siguiente al de la notificación o publicación del acto de que se trate.", "El mismo día de la notificación siempre que éste sea hábil.", "El primer día hábil del mes siguiente."], "c": 1, "e": "Los plazos en días se cuentan desde el día siguiente a la notificación o publicación.", "r": "Ley 39/2015 art. 30.3 · batería oficial, pregunta 240"}, {"id": "ehu241", "q": "Los actos administrativos producen efectos desde la fecha en que se dicten, sin embargo, su eficacia quedará demorada:", "o": ["Cuando sea necesaria la notificación o publicación del acto, supuesto en el cual el acto no será eficaz hasta que se realice correctamente la notificación o publicación.", "Cuando el destinatario del acto no esté de acuerdo con su contenido.", "Cuando produzcan efectos desfavorables para la persona interesada.", "Los actos administrativos siempre son eficaces desde que se dictan, sin que tal eficacia pueda quedar demorada en ningún caso."], "c": 0, "e": "La eficacia se demora cuando el acto debe notificarse o publicarse.", "r": "Ley 39/2015 art. 39.2 · batería oficial, pregunta 241"}, {"id": "ehu242", "q": "Si el plazo se fija en meses y en el mes de vencimiento no hubiera día equivalente a aquél en el que comienza el computo, se entendera que el plazo expira:", "o": ["A los 30 días de haberse notificado o publicado el acto.", "A los 31 días de haberse notificado o publicado el acto.", "El último día del mes de vencimiento.", "El primer día hábil siguiente al del mes de vencimiento."], "c": 2, "e": "Si no hay día equivalente, el plazo expira el último día del mes.", "r": "Ley 39/2015 art. 30.4 · batería oficial, pregunta 242"}, {"id": "ehu243", "q": "Si la solicitud de iniciación del procemiento administrativo no reúne los requisitos exigibles, la administración debe:", "o": ["Archivar la solicitud.", "Requerir a la persona interesada para que la subsane.", "Requerir a la persona interesada para que formule una nueva que reúna todos los requisitos.", "Sancionar a la persona interesada."], "c": 1, "e": "Se requiere al interesado para que subsane en diez días.", "r": "Ley 39/2015 art. 68.1 · batería oficial, pregunta 243"}, {"id": "ehu244", "q": "De conformidad con LO establecido en el artículo 35 de la Ley 39/2015, de 1 de octubre, de procedimiento administrativo comun, han de ser motivados:", "o": ["Los actos que resuelvan recursos administrativos.", "Los actos que limiten derechos o intereses legítimos.", "Los actos que se separen del criterio seguido en actuaciones precedentes.", "Todas las respuestas anteriores son correctas."], "c": 3, "e": "Los tres tipos de actos deben motivarse.", "r": "Ley 39/2015 art. 35.1 · batería oficial, pregunta 244"}, {"id": "ehu245", "q": "Las notificaciones de los actos administrativos deberán contener:", "o": ["El texto íntegro del acto o resolución.", "Un resumen detallado del acto o resolución.", "La parte del acto o resolución que pueda afectar a quien se notifica.", "Únicamente es necesario que contenga el recurso que se puede interponer contra el acto notificado."], "c": 0, "e": "La notificación contiene el texto íntegro de la resolución.", "r": "Ley 39/2015 art. 40.2 · batería oficial, pregunta 245"}, {"id": "ehu246", "q": "Si un/a interesado/a rechaza la notificación de un acto administrativo:", "o": ["Sele intentará notificar nuevamente, dentro de los 3 días siguientes, a una hora distinta.", "Se dará por efectuado el trámite y se continuará el procedimiento.", "Sele publicará en el Boletín Oficial del Estado, de la Comunidad Autónoma o de la Provincia, según cuál sea la Administración de la que procede el acto a notificar.", "Se le hará por medio de edicto en el tablón de anuncios del Ayuntamiento de su último domicilio."], "c": 1, "e": "Si se rechaza la notificación, se da por efectuado el trámite y sigue el procedimiento.", "r": "Ley 39/2015 art. 41.5 · batería oficial, pregunta 246"}, {"id": "ehu247", "q": "Se deberán notificar las resoluciones y actos administrativos a:", "o": ["Todos/as los/as administrados/as.", "Las personas interesadas cuyos derechos e intereses se vean afectados por dichos actos y resoluciones.", "Quién previamente lo haya solicitado.", "Los/as funcionarios/as de la Administración que han dictado el acto."], "c": 1, "e": "Se notifica a los interesados cuyos derechos e intereses se vean afectados.", "r": "Ley 39/2015 art. 40.1 · batería oficial, pregunta 247"}, {"id": "ehu248", "q": "Las notificaciones de un acto administrativo se hará en un boletín oficial cuando:", "o": ["Los/asinteresados/as sean desconocidos/as.", "Se ignore el lugar donde ha de practicarse la notificación", "Se ha intentado la notificación, pero no se ha podido practicar.", "Todas las respuestas anteriores son correctas."], "c": 3, "e": "Se notifica por anuncio en el BOE si los interesados son desconocidos, se ignora el lugar o no se ha podido practicar.", "r": "Ley 39/2015 art. 44 · batería oficial, pregunta 248"}, {"id": "ehu249", "q": "Reúne la condición de persona interesada:", "o": ["Toda aquella que presenta un escrito dirigido a la Administración.", "Toda aquella que interpone un recurso administrativo.", "Cualquier ciudadano/a.", "Toda aquella que, sin haber iniciado el procedimiento, tenga derechos que puedan resultar afectados por la decisión que se adopte en el mismo."], "c": 3, "e": "Es interesado quien, sin haber iniciado el procedimiento, tenga derechos que puedan resultar afectados por la decisión.", "r": "Ley 39/2015 art. 4.1.b · batería oficial, pregunta 249"}, {"id": "ehu250", "q": "Si varias personas interesadas firman una solicitud, las actuaciones se entenderán:", "o": ["Con la que ostente mayor interés", "Con toda el las.", "Siempre con la que figure en primer lugar.", "Con la persona representante o interesada que expresamente designen."], "c": 3, "e": "Las actuaciones se entienden con el representante o interesado designado expresamente o, en su defecto, con el primero que figure.", "r": "Ley 39/2015 art. 7 · batería oficial, pregunta 250"}, {"id": "ehu251", "q": "Para tener los particulares derecho a ser indemnizados por las administraciones públicas ¿Cual de estas características no se corresponde al daño sufrido?", "o": ["Deberá ser evaluable económicamente.", "Deberá ser efectivo.", "Deberá ser individualizado con relación a una persona o grupo de personas", "Deberá ser perceptible."], "c": 3, "e": "El daño debe ser efectivo, evaluable económicamente e individualizado; «perceptible» no es un requisito legal.", "r": "Ley 40/2015 art. 32.2 · batería oficial, pregunta 251"}, {"id": "ehu252", "q": "Los particulares en ningún caso tendrían derecho a ser indemnizados por las administraciones publicas:", "o": ["Sise ha sufrido una lesión en cualquier bien y derecho.", "Si la lesión producida en bienes y derechos se ha debido a un caso de fuerza mayor.", "Si la lesión ha sido consecuencia del funcionamiento normal de los servicios públicos.", "Si la lesión ha sido consecuencia del funcionamiento anormal de los servicios públicos."], "c": 1, "e": "No se indemnizan las lesiones producidas por fuerza mayor.", "r": "Ley 40/2015 art. 32.1 · batería oficial, pregunta 252"}, {"id": "ehu253", "q": "La administración, para poder exigir a sus autoridades y demás personal a su servicio, responsabilidad patrimonial en la que hubieran incurrido por su actuación deberá:", "o": ["Instruir el procedimiento que reglamentariamente se establezca.", "Ponderar el resultado dañoso producido.", "Ponderar la existencia o no de intencionalidad, la responsabilidad profesional del personal a su servicio y su relación con la producción del resultado.", "Las tres opciones son correctas."], "c": 3, "e": "Se instruye el procedimiento y se ponderan el resultado dañoso, la intencionalidad, la responsabilidad profesional y su relación con el daño.", "r": "Ley 40/2015 art. 36.2 · batería oficial, pregunta 253"}, {"id": "ehu254", "q": "Según el art. 33 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando se trate de procedimientos en materia de responsabilidad patrimonial, la administración pública competente deberá consultar a las restantes administraciones implicadas para que estas puedan exponer cuanto consideren procedente, en el plazo de:", "o": ["10 días.", "15 días.", "1mes.", "3 meses."], "c": 1, "e": "Las demás Administraciones implicadas disponen de quince días para exponer lo que consideren.", "r": "Ley 40/2015 art. 33.2 · batería oficial, pregunta 254"}, {"id": "ehu255", "q": "La Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, señala que para hacer efectiva la responsabilidad patrimonial, los particulares exigirán:", "o": ["Directamente a la Administración Pública correspondiente las indemnizaciones por los daños y perjuicios causados por las autoridades y personal a su servicio.", "Indirectamente a la Administración Pública correspondiente las indemnizaciones por los daños y perjuicios causados por las autoridades y personal a su servicio.", "A la Administración Pública o a las autoridades y personal a su servicio, las indemnizaciones por los daños y perjuicios causados.", "Ninguna de las opciones anteriores es correcta."], "c": 0, "e": "Los particulares exigen directamente a la Administración las indemnizaciones por daños causados por su personal.", "r": "Ley 40/2015 art. 36.1 · batería oficial, pregunta 255"}, {"id": "ehu256", "q": "Las personas físicas podrán utilizar, para relacionarse con la administración:", "o": ["Sólo los certificados electrónicos incorporados al Documento Nacional de Identidad.", "Sólo los certificados electrónicos reconocidos y los sistemas de firma electrónica avanzada que se admitan por la Administración.", "Los certificados electrónicos incorporados al Documento Nacional de Identidad, los certificados electrónicos reconocidos y los sistemas de firma electrónica avanzada que se admitan por la Administración.", "Ninguna de las opciones anteriores es correcta."], "c": 2, "e": "Pueden usar los certificados del DNI, los certificados reconocidos y otros sistemas de firma admitidos.", "r": "Ley 39/2015 arts. 9-10 · batería oficial, pregunta 256"}, {"id": "ehu257", "q": "Los canales de asistencia para el acceso a servicios electrónicos tienen como finalidad:", "o": ["Sustituir todos los trámites.", "Ayudar a las personas en el uso de medios electrónicos.", "Realizar funciones judiciales.", "Gestionar únicamente sanciones."], "c": 1, "e": "Los canales de asistencia ayudan a las personas a usar los medios electrónicos.", "r": "Ley 39/2015 art. 12 · batería oficial, pregunta 257"}, {"id": "ehu258", "q": "¿Tienen derecho los/as ciudadanos/as a conocer el estado de la tramitación de un procedimiento administrativo concreto?", "o": ["Sí, en todo momento, aunque no tengan la condición de personas interesadas en el mismo.", "Sí, en cualquier fase del procedimiento anterior al trámite de audiencia, aunque no tengan la condición de personas interesadas en el procedimiento.", "Sí, en todo momento, si tienen la condición de personas interesadas en el procedimiento.", "Sí, sólo en las fases anteriores al trámite de audiencia, si tienen la condición de personas interesadas en dicho procedimiento."], "c": 2, "e": "Los interesados tienen derecho a conocer en cualquier momento el estado de tramitación.", "r": "Ley 39/2015 art. 53.1.a · batería oficial, pregunta 258"}, {"id": "ehu259", "q": "De conformidad con la Ley 39/2015, de 1 de octubre, la constancia de documentos y actuaciones en un archivo electrónico facilita el cumplimiento de las obligaciones", "o": ["De congruencia.", "De transparencia.", "De participación.", "Decercanía."], "c": 1, "e": "El archivo electrónico facilita el cumplimiento de las obligaciones de transparencia.", "r": "Ley 39/2015, preámbulo y art. 17 · batería oficial, pregunta 259"}, {"id": "ehu260", "q": "¿Puede la administración convalidar los actos anulables?", "o": ["No, en ningún caso.", "Sí, subsanando los vicios de que adolezcan.", "SÍ, pero únicamente se pueden convalidar cuando el motivo de anulabilidad sea un defecto de forma.", "No, únicamente cabe la convalidación de actos nulos."], "c": 1, "e": "La Administración puede convalidar los actos anulables subsanando sus vicios.", "r": "Ley 39/2015 art. 52.1 · batería oficial, pregunta 260"}, {"id": "ehu261", "q": "En un procedimiento iniciado a solicitud de la persona interesada, el vencimiento del plazo máximo sin haberse notificado resolución expresa legitima a la persona interesada para:", "o": ["Entender siempre estimada su solicitud.", "Entender siempre desestimada su solicitud.", "Entender caducado el procedimiento.", "Entender su solicitud estimada o desestimada, según proceda."], "c": 3, "e": "El vencimiento sin resolución legitima para entenderla estimada o desestimada por silencio, según proceda.", "r": "Ley 39/2015 art. 24.1 · batería oficial, pregunta 261"}, {"id": "ehu262", "q": "¿Cuáles son los efectos de la desestimación de una solicitud por silencio administrativo?", "o": ["Tiene el efecto de exonerar a la Administración de la obligación de resolver.", "Tiene los mismos efectos que una resolución expresa desestimatoria.", "Tiene los mismos efectos que un acto de trámite cualificado.", "Tiene los solos efectos de permitir a las personas interesadas la interposición del recurso administrativo o contencioso-administrativo que resulte procedente."], "c": 3, "e": "La desestimación por silencio solo permite interponer el recurso que proceda.", "r": "Ley 39/2015 art. 24.2 · batería oficial, pregunta 262"}, {"id": "ehu263", "q": "Según la Ley de empleo público Vasco la responsabilidad disciplinaria no se extingue:", "o": ["Porel arrepentimiento de la persona infractora.", "Porla prescripción de la falta o sanción.", "Por fallecimiento.", "Por el cumplimiento de la sanción."], "c": 0, "e": "La responsabilidad disciplinaria se extingue por cumplimiento, fallecimiento o prescripción, no por arrepentimiento.", "r": "Ley 11/2022 de Empleo Público Vasco; TREBEP art. 94 · batería oficial, pregunta 263"}, {"id": "ehu264", "q": "¿Puede el personal técnico, de gestión y administración y servicios participar en los organos de Gobierno y representación de la EHU?", "o": ["No, sólo puede hacerlo el personal docente.", "SÍ, siempre que tenga más de 5 años de servicios.", "Sí, conforme a los procedimientos de elección establecidos.", "Síen los de representación, pero no en los de gobierno."], "c": 2, "e": "El PTGAS participa en los órganos de gobierno y representación conforme a los procedimientos de elección.", "r": "LOSU; Estatutos UPV/EHU · batería oficial, pregunta 264"}, {"id": "ehu265", "q": "¿Qué implica la transparencia de la administración?", "o": ["Identificación del personal de atención al público.", "Acceso a la información precisa", "Publicidad de los resultados.", "Todas las respuestas son correctas."], "c": 3, "e": "La transparencia implica identificar al personal, dar acceso a la información y publicar los resultados.", "r": "Ley 19/2013; atención a la ciudadanía · batería oficial, pregunta 265"}, {"id": "ehu266", "q": "Según la Ley 39/2015, los/as ciudadanos/as tienen derecho a:", "o": ["Obtener copia de los documentos que presenten, quedando, en todo caso, los originales en el procedimiento de que se trate", "Obtener copia cotejada de los documentos que presenten, quedando, en todo caso, los originales en el procedimiento de que se trate", "A obtener copia de los documentos contenidos en los procedimientos en los que tengan la condición de interesados", "Ninguna de las anteriores respuestas es correcta."], "c": 2, "e": "Los interesados tienen derecho a obtener copia de los documentos contenidos en sus procedimientos.", "r": "Ley 39/2015 art. 53.1.a · batería oficial, pregunta 266"}, {"id": "ehu267", "q": "Según la Ley 39/2015, los/as ciudadanos/as tienen derecho a:", "o": ["Identificar a las autoridades y al personal al servicio de las Administraciones Públicas bajo cuya responsabilidad se tramiten los procedimientos", "No presentar documentos no exigidos por las normas aplicables al procedimiento de que se rate", "Ser tratados con respeto y deferencia por autoridades y funcionariado, que habrán de facilitarles el ejercicio de sus derechos y el cumplimiento de sus obligaciones", "Todas las respuestas anteriores son correctas"], "c": 3, "e": "Las tres son derechos reconocidos.", "r": "Ley 39/2015 arts. 13 y 53 · batería oficial, pregunta 267"}, {"id": "ehu268", "q": "Según el texto refundido de la Ley del Estatuto básico del empleado público, los/as empleados/as públicos deben actuar con arreglo, entre otros, al siguiente principio, que inspira su codigo de conducta:", "o": ["Integridad.", "Austeridad.", "Honradez", "Las tres respuestas son correctas."], "c": 3, "e": "El código de conducta se inspira, entre otros, en integridad, austeridad y honradez.", "r": "TREBEP art. 52 · batería oficial, pregunta 268"}, {"id": "ehu269", "q": "En relación con el derecho de acceso a la información pública que obre en poder de las administraciones públicas, se entiende por “información pública”, de acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen Gobierno:", "o": ["Los contenidos o documentos, cualquiera que sea su formato o soporte, que hayan sido elaborados o adquiridos en el ejercicio de sus funciones.", "Los contenidos o documentos, siempre en formato papel o digital, elaborados o adquiridos en el ejercicio de sus funciones.", "Los contenidos o documentos, siempre en formato papel, elaborados o adquiridos en el ejercicio de sus funciones.", "Sólo se refiere a la información contenida en formato papel, cualquiera que sea el origen de a misma."], "c": 0, "e": "Es información pública cualquier contenido o documento, en cualquier formato o soporte, elaborado o adquirido en el ejercicio de sus funciones.", "r": "Ley 19/2013 art. 13 · batería oficial, pregunta 269"}, {"id": "ehu270", "q": "El artículo 13 de la Ley 39/2015, de 1 de octubre, de procedimiento administrativo común, recoge entre los derechos de las personas en sus relaciones con las administraciones publicas:", "o": ["Aser asistidos en el uso de medios electrónicos", "A utilizar las lenguas oficiales de la comunidad autónoma.", "A acceder a los registros y documentos.", "Todas las respuestas son correctas."], "c": 3, "e": "El art. 13 recoge los tres derechos.", "r": "Ley 39/2015 art. 13 · batería oficial, pregunta 270"}, {"id": "ehu271", "q": "Indique la opción correcta en relación con la actuación y funcionamiento del sector público por medios electrónicos.", "o": ["Las empresas privadas han de tener una sede electrónica si son adjudicatarias de algún servicio público de competencia de cualquiera de las administraciones públicas.", "Las sedes electrónicas siempre han de estar bajo la titularidad de una Administración Pública, aunque la gestión y administración puede ser subcontratada con empresas expertas en la materia.", "La sede electrónica de cada Administración ha de preservar la protección de datos personales de las personas usuarias; con ese objetivo, se constituirán sistemas informáticos cerrados sin ninguna conexión e interoperabilidad con las sedes de otras Administraciones Públicas.", "La titularidad de una sede electrónica ha de corresponder necesariamente a una Administración Pública o bien a uno o varios organismos públicos o entidades de derecho público en el ámbito de sus competencias."], "c": 3, "e": "La titularidad de una sede electrónica corresponde a una Administración Pública o a organismos o entidades de derecho público.", "r": "Ley 40/2015 art. 38.1 · batería oficial, pregunta 271"}, {"id": "ehu272", "q": "¿Cual de los siguientes documentos utiliza la ciudadanía para hacer peticiones a la administracion?", "o": ["Circular.", "Notificación.", "Instancia.", "Oficio."], "c": 2, "e": "La ciudadanía usa la instancia (solicitud) para dirigirse a la Administración.", "r": "Documentos administrativos · batería oficial, pregunta 272"}, {"id": "ehu273", "q": "¿En cúal de los siguientes documentos tiene que constar la fecha?", "o": ["Instancia.", "Notificación.", "Certificación.", "Todas las respuestas son correctas"], "c": 3, "e": "Instancia, notificación y certificación deben llevar fecha.", "r": "Documentos administrativos · batería oficial, pregunta 273"}, {"id": "ehu274", "q": "En las actas se consigna la siguiente información en relación a las reuniones:", "o": ["Día de la reunión.", "Lugar de la reunión.", "Hora de finalización de la reunión.", "Todas las respuestas son correctas."], "c": 3, "e": "El acta recoge día, lugar y hora de la reunión, entre otros datos.", "r": "Ley 40/2015 art. 18 · batería oficial, pregunta 274"}, {"id": "ehu275", "q": "La administración pública en su relación con la ciudadanía tiene que ser:", "o": ["Receptiva, accesible y transparente.", "Receptiva y accesible pero no transparente.", "Receptiva y transparente pero no accesible.", "Ni receptiva ni accesible pero sí transparente."], "c": 0, "e": "La Administración debe ser receptiva, accesible y transparente.", "r": "Atención a la ciudadanía · batería oficial, pregunta 275"}, {"id": "ehu276", "q": "¿Qué implica la idea de que los servicios que presta la administración pública son de naturaleza universal?", "o": ["Que sirven para ciudadanos/as de todos los países.", "Igualdad en el trato a todas las personas usuarias.", "Segmentación del mercado público.", "Que no tiene barreras físicas ni psíquicas."], "c": 1, "e": "Universalidad significa igualdad de trato a todas las personas usuarias.", "r": "Atención a la ciudadanía · batería oficial, pregunta 276"}, {"id": "ehu277", "q": "¿Cúal de los siguientes es un requisito imprescindible para una atención de calidad a la ciudadanía?", "o": ["Intervenir aleatoriamente sin responder a demandas.", "Que el personal de atención telefónica tenga voz grave.", "Escuchar permanentemente a la ciudadanía.", "Que el personal de atención al público modere sus respuestas negativas."], "c": 2, "e": "Escuchar permanentemente a la ciudadanía es requisito de una atención de calidad.", "r": "Atención a la ciudadanía · batería oficial, pregunta 277"}, {"id": "ehu278", "q": "¿Cúal de las siguientes opciones es una ventaja de la implantación de la ventanilla única?", "o": ["Ahorro en desplazamientos de la ciudadanía.", "Desaparición de colas.", "Simplificación de trámites", "Todas las respuestas son correctas."], "c": 3, "e": "La ventanilla única ahorra desplazamientos, reduce colas y simplifica trámites.", "r": "Atención a la ciudadanía · batería oficial, pregunta 278"}, {"id": "ehu279", "q": "La información administrativa es el cauce por el que el/la ciudadano/a puede acceder:", "o": ["Al conocimiento de sus derechos y obligaciones.", "A la utilización de los bienes y servicios públicos.", "Al Boletín Oficial.", "Entre otros, a los contenidos de las respuestas a) y b)."], "c": 3, "e": "La información administrativa da acceso al conocimiento de derechos y obligaciones y al uso de bienes y servicios.", "r": "RD 208/1996 art. 1 · batería oficial, pregunta 279"}, {"id": "ehu280", "q": "La atención al ciudadano/a por medios telemáticos:", "o": ["Es el único canal disponible para las personas menores de 65 años, salvo que se acredite alguna discapacidad física que dificulte esa atención por medios telemáticos.", "Tiene como principal finalidad el ahorro de personal.", "Permite acercar los servicios de la Administración al ciudadano/a, diversificando los canales de acceso.", "Esla única posible a partir de la entrada en vigor del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos."], "c": 2, "e": "La atención telemática acerca la Administración diversificando los canales de acceso.", "r": "Atención a la ciudadanía · batería oficial, pregunta 280"}, {"id": "ehu281", "q": "Indique la opción correcta:", "o": ["Los registros electrónicos se regirán a efectos de cómputo de los plazos imputables tanto a los interesados como a las Administraciones Públicas por la fecha y hora del sistema Operativo utilizado por la persona usuaria, siempre que dicho sistema cuente con la licencia de uso correspondiente.", "Los registros electrónicos permitirán la presentación de solicitudes, escritos y comunicaciones todos los días del año durante las veinticuatro horas, salvo que la Administración titular del correspondiente registro, en uso de sus competencias, pueda establecer restricciones de acceso en días festivos nacionales.", "A los efectos del cómputo de plazo fijado en días hábiles o naturales, y en lo que se refiere a cumplimiento de plazos por los interesados, la presentación en un día inhábil se entenderá siempre realizada en la primera hora del primer día hábil siguiente.", "La opción inicial que tiene los ciudadanos de comunicarse por unos u otros medios con la Administración Pública, no le vincula en el desarrollo del procedimiento y, por ende, podrá, en cualquier momento, optar por un medio distinto del inicialmente elegido."], "c": 3, "e": "La opción de canal no vincula: la persona física puede cambiar de medio en cualquier momento.", "r": "Ley 39/2015 art. 14.1 · batería oficial, pregunta 281"}, {"id": "ehu282", "q": "La información administrativa sobre los requisitos jurídicos o técnicos que las disposiciones impongan a los proyectos, actuaciones o solicitudes que un/a ciudadano/a se proponga realizar, se considera una información:", "o": ["De carácter particular.", "De carácter general.", "Sin importancia.", "Confidencial."], "c": 1, "e": "La información sobre requisitos jurídicos o técnicos de proyectos y solicitudes es de carácter general.", "r": "RD 208/1996 art. 3 · batería oficial, pregunta 282"}, {"id": "ehu283", "q": "Se considera información administrativa de carácter particular:", "o": ["La concerniente al estado o contenido de los procedimientos en tramitación.", "La que concierne a la identificación de las autoridades y personal al servicio de la Administración bajo cuya responsabilidad se tramiten aquellos procedimientos.", "La referida a los datos de carácter personal que afecten de alguna forma a la intimidad o privacidad de las personas físicas.", "Las tres opciones anteriores son correctas."], "c": 3, "e": "Es información particular la relativa al estado de los procedimientos, a la identificación de los responsables y a los datos personales.", "r": "RD 208/1996 art. 4 · batería oficial, pregunta 283"}, {"id": "ehu284", "q": "La atención personalizada a la ciudadanía contempla entre sus objetivos:", "o": ["La recepción de las iniciativas o sugerencias formuladas por los/as ciudadanos/as para mejorar la calidad de los servicios.", "La recepción de las iniciativas o sugerencias formuladas por los/as propios/as empleados/as públicos/as para mejorar la calidad de los servicios.", "Las respuestas a) y b) son posibles.", "El desplazamiento del personal funcionario al domicilio particular de la persona que requiera la realización de un trámite."], "c": 2, "e": "Se recogen iniciativas y sugerencias tanto de la ciudadanía como del propio personal.", "r": "RD 208/1996 art. 2 · batería oficial, pregunta 284"}, {"id": "ehu285", "q": "¿La Constitución Española reconoce a los/as ciudadanos/as el ejercicio del derecho de peticion?", "o": ["Sí, pero la petición ha de ser presentada directamente a título individual.", "Sí, siempre que la petición sea presentada por escrito por un colectivo social.", "Sí, individual o colectivamente, por escrito y en la forma y con los efectos que determine la ley.", "El derecho de petición sólo está contemplado en la Ley 39/2015, del Procedimiento Administrativo Común."], "c": 2, "e": "Todos los españoles tienen derecho de petición individual y colectiva, por escrito, en la forma y con los efectos que determine la ley.", "r": "CE art. 29 · batería oficial, pregunta 285"}, {"id": "ehu286", "q": "Cuando un ciudadano precisa de una aclaración sobre algún procedimiento, trámite o requisito para acceder a un servicio público:", "o": ["Deberá consultar la legislación adecuada.", "Tendrá derecho a recibir orientación e información personalizada.", "Deberá solicitar asesoramiento jurídico-administrativo en una Gestoría privada.", "Acudirá al servicio de información, previo pago de la cuota correspondiente."], "c": 1, "e": "La ciudadanía tiene derecho a recibir orientación e información personalizada.", "r": "Atención a la ciudadanía · batería oficial, pregunta 286"}, {"id": "ehu287", "q": "En sus relaciones con las administraciones públicas, ¿Los/as ciudadanos/as tienen el derecho a utilizar las lenguas oficiales en el territorio de su comunidad autónoma?:", "o": ["Esun derecho que las Administraciones Públicas de las diversas Comunidades Autónomas han de garantizar a la ciudadanía.", "Sólo si las Administraciones de esa Comunidad Autónoma ofrecen expresamente esa posibilidad.", "Sólo en las administraciones autonómicas.", "Sólo si el/la funcionario/a las conoce."], "c": 0, "e": "Es un derecho que las Administraciones deben garantizar.", "r": "Ley 39/2015 art. 13.c · batería oficial, pregunta 287"}, {"id": "ehu288", "q": "El acceso a archivos y a documentos que obren en los archivos administrativos es un derecho que le asiste al ciudadano/a:", "o": ["Sólo a los que se sustentan en soporte gráfico.", "Sólo a los quese sustentan en soporte gráfico y correspondan a procedimientos terminados.", "En cualquier forma de expresión siempre que estén inacabados.", "Siempre que correspondan a procedimientos terminados en la fecha de la solicitud."], "c": 3, "e": "El acceso a archivos se refería a documentos de procedimientos terminados en la fecha de la solicitud.", "r": "Ley 30/1992 art. 37.1 (hoy Ley 19/2013) · batería oficial, pregunta 288"}, {"id": "ehu289", "q": "El acceso a documentos que obren en los archivos administrativos y que contengan datos referentes a la intimidad de las personas:", "o": ["Estará reservado a éstas.", "Será igualmente de acceso público.", "Estará totalmente prohibido.", "Será posible en caso de que contar con el consentimiento expreso y por escrito de la persona afectada."], "c": 0, "e": "El acceso a documentos con datos de la intimidad estaba reservado a las personas afectadas.", "r": "Ley 30/1992 art. 37.2 · batería oficial, pregunta 289"}, {"id": "ehu290", "q": "Los datos personales no deben conservarse:", "o": ["Durante más tiempo del necesario para la consecución de la finalidad pretendida.", "Por tiempo indefinido.", "Por tiempo limitado.", "Ninguna de las respuestas anteriores es correcta."], "c": 0, "e": "Los datos no deben conservarse más tiempo del necesario para su finalidad.", "r": "RGPD art. 5.1.e · batería oficial, pregunta 290"}, {"id": "ehu291", "q": "La seguridad adecuada de los datos atendiendo al principio de integridad y confidencialidad debe incluir:", "o": ["La protección contra el tratamiento no autorizado o ilícito.", "La protección contra su pérdida.", "La protección contra su destrucción o daño accidental.", "Las tres respuestas anteriores son correctas."], "c": 3, "e": "La integridad y confidencialidad incluyen protección contra tratamiento no autorizado, pérdida, destrucción o daño accidental.", "r": "RGPD art. 5.1.f · batería oficial, pregunta 291"}, {"id": "ehu292", "q": "¿Con qué fines se pueden conservar los datos por períodos más largos?:", "o": ["Fines de archivo en interés público.", "Fines estadísticos.", "Las respuestas a) y b) son correctas.", "Cuando los datos no contengan informaciones relevantes."], "c": 2, "e": "Pueden conservarse más tiempo con fines de archivo en interés público, investigación o estadísticos.", "r": "RGPD art. 5.1.e · batería oficial, pregunta 292"}, {"id": "ehu293", "q": "El proceso de seudonimización de datos personales implica que ciertos atributos se sustituyan por:", "o": ["Seudónimos.", "Códigos.", "Las respuestas a) y b) son correctas.", "Sobrenombres."], "c": 2, "e": "Respuesta probable: la seudonimización sustituye atributos por seudónimos o códigos.", "r": "RGPD art. 4.5 · batería oficial, pregunta 293"}, {"id": "ehu294", "q": "¿Cuáles de los siguientes datos se subsumen en las categorías especiales de datos?:", "o": ["Origen étnico y racial.", "Datos biométricos.", "Los datos relativos a la vida sexual.", "Las tres respuestas anteriores son correctas."], "c": 3, "e": "Origen étnico, datos biométricos y vida sexual son categorías especiales.", "r": "RGPD art. 9.1 · batería oficial, pregunta 294"}, {"id": "ehu295", "q": "La información básica al afectado ha de contener:", "o": ["Identidad del responsable.", "Identidad del encargado.", "La finalidad del tratamiento.", "Las respuestas a) y c) son correctas."], "c": 3, "e": "La información básica incluye la identidad del responsable y la finalidad del tratamiento, además de cómo ejercer los derechos.", "r": "LOPDGDD art. 11.2 · batería oficial, pregunta 295"}, {"id": "ehu296", "q": "¿Cuál de los siguientes derechos no queda regulado expresamente en el RGPD?:", "o": ["Derecho de acceso.", "Derecho de rectificación.", "Derecho a la cancelación.", "Derecho de supresión."], "c": 2, "e": "El RGPD no habla de «cancelación» sino de «supresión».", "r": "RGPD art. 17 · batería oficial, pregunta 296"}, {"id": "ehu297", "q": "El derecho a la portabilidad de los datos es solo de aplicación cuando el tratamiento es:", "o": ["Automatizado y el fundamento jurídico del tratamiento es el consentimiento o un contrato.", "No automatizado y el fundamento jurídico del tratamiento es el consentimiento o un contrato.", "Consentido e informado.", "Ninguna de las respuestas anteriores es correcta."], "c": 0, "e": "La portabilidad se aplica a tratamientos automatizados basados en el consentimiento o en un contrato.", "r": "RGPD art. 20.1 · batería oficial, pregunta 297"}, {"id": "ehu298", "q": "¿Cuáles de los siguientes derechos pueden ser calificados como derechos digitales?:", "o": ["Derecho al honor en las redes sociales.", "Derecho a la desconexión digital en el ámbito laboral.", "Derecho a la intimidad.", "Las tres respuestas anteriores son correctas."], "c": 1, "e": "Respuesta probable: la desconexión digital en el ámbito laboral es un derecho digital expreso.", "r": "LOPDGDD art. 88 · batería oficial, pregunta 298"}, {"id": "ehu299", "q": "Las administraciones públicas, en su actuación para con los/as ciudadanos/as, se rigen por criterios:", "o": ["De cooperación.", "De eficacia y concentración.", "De eficiencia y servicio a los/as ciudadanos/as.", "Que dictan las leyes de Régimen Local."], "c": 2, "e": "Las Administraciones se rigen por criterios de eficiencia y servicio a la ciudadanía.", "r": "Ley 40/2015 art. 3.1 · batería oficial, pregunta 299"}, {"id": "ehu300", "q": "Las formas o canales de información y atención al público utilizadas por la administración son:", "o": ["Fundamentalmente, la vía telefónica y el correo escrito.", "La presencial, la telefónica, el correo, la telemática.", "La presencial es la que indica la ley.", "La telemática y la telefónica preferencialmente."], "c": 1, "e": "Los canales son el presencial, el telefónico, el correo y el telemático.", "r": "Atención a la ciudadanía · batería oficial, pregunta 300"}]}, {"id": "b09", "sig": "Bloque 9", "titulo": "Bloque 9. Atención a la ciudadanía, documentación y prevención", "sub": "Preguntas 301–350 de la batería oficial (sin respuestas oficiales: resueltas por Claude).", "preguntas": [{"id": "ehu301", "q": "En el ámbito de atención al ciudadano/a, la forma en que la administración transmite al ciudadano/a la documentación precisa:", "o": ["Sólo pueden realizarse en soporte papel.", "Puede ser transmitida en soporte papel o bien por medios electrónicos o telemáticos.", "Siempre necesita ser ratificada telefónicamente.", "Sólo se trasmite por medios electrónicos o telemáticos."], "c": 1, "e": "La documentación puede transmitirse en papel o por medios electrónicos o telemáticos.", "r": "Ley 39/2015 art. 14 · batería oficial, pregunta 301"}, {"id": "ehu302", "q": "¿A quién identifica el RGPD como responsable del tratamiento o responsable de la protección de datos?:", "o": ["Personas físicas y jurídicas.", "Autoridades públicas.", "Servicios u otros organismos.", "Las tres respuestas anteriores son correctas."], "c": 3, "e": "Responsable puede ser una persona física o jurídica, autoridad pública, servicio u otro organismo.", "r": "RGPD art. 4.7 · batería oficial, pregunta 302"}, {"id": "ehu303", "q": "Señale la respuesta incorrecta según LO dispuesto en Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos. Las administraciones públicas podrán utilizar los siguientes sistemas para su identificación electrónica y para la autenticación de los documentos electrónicos que produzcan:", "o": ["Sistemas de firma electrónica basados en la utilización de certificados de dispositivo seguro o medio equivalente que permita identificar la sede electrónica y el establecimiento con ella de comunicaciones seguras.", "Sistemas de firma electrónica para la actuación administrativa automatizada.", "Un código OR impreso en los documentos que necesariamente ha de integrar la información relativa a la Administración generadora del documento, así como de la persona que ostenta la competencia sobre la materia expresada en el documento.", "Intercambio electrónico de datos en entornos cerrados de comunicación, conforme a lo especificamente acordado entre las partes."], "c": 2, "e": "El reglamento prevé el código seguro de verificación (CSV), no un código QR con esos contenidos.", "r": "RD 203/2021 arts. 18-20 · batería oficial, pregunta 303"}, {"id": "ehu304", "q": "En la comunicación telefónica la persona receptora debe tener en cuenta:", "o": ["Procurar terminar las frases iniciadas por la persona interlocutora.", "Saber utilizar los silencios, tanto para subrayar determinadas palabras como para escuchar a la persona interlocutora.", "Escuchar la exposición del mensaje de la persona emisora de una forma activa, interviniendo para añadir detalles.", "Proporcionar más datos aún de los solicitados, aunque estos no sean procedentes."], "c": 1, "e": "Al teléfono hay que saber usar los silencios para subrayar y para escuchar.", "r": "Atención telefónica · batería oficial, pregunta 304"}, {"id": "ehu305", "q": "¿Cómo se define «calidad» en la atención a las personas usuarias?", "o": ["Es proporcionar la mejor respuesta a las necesidades de la persona usuaria con los medios existentes.", "Es conseguir que la persona usuaria se encuentre satisfecha a pesar de no haber obtenido ninguna respuesta.", "Es conseguir atender el mayor número de consultas posibles durante la jornada laboral.", "Es proporcionar a la persona usuaria aquellos contactos que le resolverán sus necesidades."], "c": 0, "e": "Calidad es dar la mejor respuesta a las necesidades de la persona usuaria con los medios existentes.", "r": "Atención a la ciudadanía · batería oficial, pregunta 305"}, {"id": "ehu306", "q": "En un estilo positivo de comunicación se ha de evitar:", "o": ["Palabras amables.", "Frases hechas y refranes.", "Sonrisas.", "Lenguaje conciso."], "c": 1, "e": "En un estilo positivo se evitan frases hechas y refranes.", "r": "Comunicación · batería oficial, pregunta 306"}, {"id": "ehu307", "q": "Aquel comportamiento que conduce a ver las cosas con un enfoque nuevo, encontrando soluciones inéditas, se denomina:", "o": ["Comportamiento creativo.", "Comportamiento positivo.", "Comportamiento crítico.", "Comportamiento tranquilizador."], "c": 0, "e": "Ver las cosas con un enfoque nuevo y buscar soluciones inéditas es un comportamiento creativo.", "r": "Comunicación · batería oficial, pregunta 307"}, {"id": "ehu308", "q": "Aquellos comportamientos irritantes o generadores de conflictos son:", "o": ["Comportamientos positivo, creativo y crítico.", "Comportamientos defensivo, crítico, agresivo y creativo.", "Comportamientos tranquilizador y defensivo.", "Comportamientos defensivo, crítico y agresivo."], "c": 3, "e": "Los comportamientos defensivo, crítico y agresivo generan conflictos.", "r": "Comunicación · batería oficial, pregunta 308"}, {"id": "ehu309", "q": "De entre los siguientes tipos de comportamiento, señale el que se ha de evitar ante la persona usuaria:", "o": ["La jerga de la Institución: abreviaturas, signos, términos de uso propios...", "Palabras tranquilizadoras.", "Actitud positiva.", "Actitud previsora."], "c": 0, "e": "Ante la persona usuaria hay que evitar la jerga interna de la institución.", "r": "Atención a la ciudadanía · batería oficial, pregunta 309"}, {"id": "ehu310", "q": "En la comunicación ¿Qué se entiende por canal?", "o": ["Es el vehículo del que nos servimos para transmitir un mensaje. Constituye el elemento puramente técnico de la comunicación.", "Esel conjunto de signos o símbolos utilizados en la comunicación.", "Es el retorno de la información desde la persona receptora a la emisora, posibilitando la autocorrección y el autocontrol.", "Esel conjunto se señales utilizados en la comunicación."], "c": 0, "e": "El canal es el vehículo que transmite el mensaje, el elemento técnico de la comunicación.", "r": "Teoría de la comunicación · batería oficial, pregunta 310"}, {"id": "ehu311", "q": "La política de atención e información al ciudadano/a por parte de la administración está orientada a:", "o": ["Hacer prevalecer la atención presencial sobre otras modalidades.", "Promocionar exclusivamente los canales telemáticos.", "Interferir en la atención ciudadana desde la perspectiva unicanal", "Mejorar la atención a la ciudadanía desde una perspectiva unificada y multicanal."], "c": 3, "e": "La política busca mejorar la atención desde una perspectiva unificada y multicanal.", "r": "Atención a la ciudadanía · batería oficial, pregunta 311"}, {"id": "ehu312", "q": "La implantación de un sistema único de información administrativa supone:", "o": ["La implantación de un sistema de información unificado y multicanal.", "Que el ciudadano podrá acudir a una única administración.", "La implantación de un sistema único, con un solo canal de transmisión.", "Que la Administración se dirige al ciudadano unilateralmente."], "c": 0, "e": "Un sistema único de información supone un sistema unificado y multicanal.", "r": "Atención a la ciudadanía · batería oficial, pregunta 312"}, {"id": "ehu313", "q": "¿Qué debe consignar un registro general de un organismo público cuando recibe una notificación?", "o": ["Firma de la persona funcionaria que la recibe y sello oficial.", "Nombre de la persona funcionaria que recibe la notificación, firma de la misma, DNI y fecha.", "Únicamente es necesario el sello del Organismo.", "Firma de la persona funcionaria que recibe la notificación."], "c": 0, "e": "Respuesta probable: firma de quien la recibe y sello oficial.", "r": "Registro y notificaciones · batería oficial, pregunta 313"}, {"id": "ehu314", "q": "¿En que plazo se debe realizar el 2% intento de entrega de una notificación?", "o": ["En los tres días siguientes al primer intento y en hora distinta.", "Al día siguiente del primer intento y hora distinta.", "A los dos días del primer intento y en hora distinta.", "Al tercer día del primer intento y en hora distinta."], "c": 0, "e": "El segundo intento se hace en los tres días siguientes y a hora distinta.", "r": "Ley 39/2015 art. 42.2 · batería oficial, pregunta 314"}, {"id": "ehu315", "q": "El impuesto sobre el valor añadido:", "o": ["Es un tributo de naturaleza directa que recae sobre el consumo.", "Esun tributo de naturaleza indirecta que recae sobre el consumo.", "Es un tributo de naturaleza directa que grava, entre otros, los premios de la Lotería Nacional.", "Esun tributo de naturaleza indirecta que grava los intereses de cuentas bancarias."], "c": 1, "e": "El IVA es un tributo indirecto que recae sobre el consumo.", "r": "Ley 37/1992 del IVA art. 1 · batería oficial, pregunta 315"}, {"id": "ehu316", "q": "¿Qué es el albarán?", "o": ["Esun documento que acredita la recepción de un pedido.", "El documento elaborado por el receptor de la mercancía.", "El documento de pago que sustituye al cheque confirmado.", "Ninguna respuesta es correcta."], "c": 0, "e": "El albarán acredita la entrega y recepción de un pedido.", "r": "Documentación comercial · batería oficial, pregunta 316"}, {"id": "ehu317", "q": "Entre otras, ¿Qué información ha de incluir el albarán?", "o": ["Número de orden, Fecha de emisión y número de factura.", "Fecha de emisión, Nombre de parte emisora y receptora, NIF y domicilio.", "Número de la factura, producto, Número y fecha del pedido", "Número de orden, Fecha de emisión, Datos de parte emisora y receptora, Número y fecha del pedido, producto, cantidad."], "c": 3, "e": "El albarán incluye número, fecha, datos de emisor y receptor, número y fecha del pedido, producto y cantidad.", "r": "Documentación comercial · batería oficial, pregunta 317"}, {"id": "ehu318", "q": "Señale la diferencia, entre otras, que existe entre la factura y el albarán:", "o": ["La factura la emite la parte compradora y el albarán la vendedora.", "La emisión del albarán es obligatoria, mientras que la de la factura no.", "La emisión del albarán no es obligatoria, mientras que la de la factura sí.", "Todas las respuestas son correctas."], "c": 2, "e": "La factura es obligatoria; el albarán no.", "r": "Documentación comercial · batería oficial, pregunta 318"}, {"id": "ehu319", "q": "El pedido, es parte del flujo administrativo del stock, y se define...", "o": ["Como la solicitud que realiza un/a empresario/a o profesional a un/a proveedor/a para que le suministre unas determinadas mercancías o le preste un servicio.", "Como el parte de trabajo que realiza el cliente al proveedor.", "Es el documento mercantil que acompaña a la factura de abono.", "Ninguna respuesta es correcta."], "c": 0, "e": "El pedido es la solicitud a un proveedor para que suministre mercancías o preste un servicio.", "r": "Documentación comercial · batería oficial, pregunta 319"}, {"id": "ehu320", "q": "La recepción de mercancías debe ser:", "o": ["Cualitativa, comprobando que la cantidad recibida es la pedida.", "Cuantitativa, comprobando que lo pedido es lo recibido.", "Cuantitativa y cualitativa.", "Estas no son características de la recepción de las mercancías."], "c": 2, "e": "La recepción debe ser cuantitativa y cualitativa.", "r": "Gestión de almacén · batería oficial, pregunta 320"}, {"id": "ehu321", "q": "En caso de emergencia dentro de un edificio:", "o": ["Se debe salir corriendo por la primera salida que encontremos.", "Se debe esperar al ascensor.", "Se debe dejar todo ordenado en el despacho.", "Se debe tranquilamente pero sin detenerse buscar la salida de emergencia más próxima."], "c": 3, "e": "Hay que dirigirse tranquilamente, sin detenerse, a la salida de emergencia más próxima.", "r": "Plan de emergencia · batería oficial, pregunta 321"}, {"id": "ehu322", "q": "En todo lugar de trabajo, las puertas transparentes se deberán señalizar:", "o": ["Siempre.", "Solo si son de emergencia.", "Solo las que no están construidas con material de seguridad.", "Solo sino son de emergencia."], "c": 0, "e": "Las puertas transparentes deben señalizarse a la altura de la vista.", "r": "RD 486/1997 anexo I.A.6 · batería oficial, pregunta 322"}, {"id": "ehu323", "q": "La temperatura donde se realicen trabajos sedentarios ha de estar comprendida entre:", "o": ["17y27\"C ysise realizan trabajos ligeros entre 14 y 25%C.", "18y27\"C ysise realizan trabajos ligeros entre 14 y 26%C.", "17y28\"C y si se realizan trabajos ligeros entre 18 y 25%C.", "18 y28\"C y si se realizan trabajos ligeros entre 15 y 26%C."], "c": 0, "e": "Trabajos sedentarios: 17-27 °C; trabajos ligeros: 14-25 °C.", "r": "RD 486/1997 anexo III · batería oficial, pregunta 323"}, {"id": "ehu324", "q": "Las dimensiones de los locales de trabajo deben permitir que los/as trabajadores/as realicen sus trabajos sin riesgos para su seguridad y salud y en condiciones ergonómicas aceptables. Sus dimensiones mínimas en oficina han de ser:", "o": ["Altura 3m desde el piso hasta el techo, superficie libre por trabajador/a 2m3, espacio no ocupado por trabajador/a 10 m?.", "Altura 3m desde el piso hasta el techo, superficie libre por trabajador/a 2m?2, espacio no ocupado por trabajador/a 10 m?,", "Altura 2,5m desde el piso hasta el techo, superficie libre por trabajador/a 2m?, espacio no ocupado por trabajador/a 10 m?.", "Altura 2,5m, superficie libre por trabajador/a 2m?, espacio no ocupado por trabajador/a 10 m?."], "c": 2, "e": "Altura de 2,5 m en oficinas, 2 m² de superficie libre y 10 m³ no ocupados por trabajador.", "r": "RD 486/1997 anexo I.A.2 · batería oficial, pregunta 324"}, {"id": "ehu325", "q": "Las vías y salidas de evacuación deben satisfacer las condiciones que se establecen en los siguientes puntos:", "o": ["Las puertas de emergencia deben abrirse hacia el exterior y no estar cerradas. Están prohibidas las puertas específicamente de emergencia que sean correderas o giratorias y no deben cerrarse con llave.", "Las puertas de emergencia deben permanecer expeditas y desembocar lo más directamente posible al exterior o zona de seguridad.", "El número, dimensiones y distribución de las puertas de emergencia dependen del uso, de los equipos y de las dimensiones de los lugares de trabajo y del número de personas máximo que puedan estar presentes.", "Todas son ciertas."], "c": 3, "e": "Las tres condiciones son ciertas.", "r": "RD 486/1997 anexo I.A.10 · batería oficial, pregunta 325"}, {"id": "ehu326", "q": "Definición de riesgo de trabajo", "o": ["Posibilidad de que surja un peligro derivado del trabajo.", "Posibilidad de que la persona trabajadora sufra un determinado daño derivado de su trabajo.", "Posibilidad de que deba prevenirse un riego derivado del trabajo.", "Trabajar estando enfermo/a."], "c": 1, "e": "Riesgo laboral es la posibilidad de que un trabajador sufra un daño derivado del trabajo.", "r": "Ley 31/1995 art. 4.2 · batería oficial, pregunta 326"}, {"id": "ehu327", "q": "La gestión en la prevención de riesgos laborales consiste fundamentalmente en:", "o": ["Informatizar toda la información para tomar decisiones con agilidad.", "Aplicar la Ley de Prevención de riesgos Laborales a las circunstancias, tamaño y actividad de la empresa.", "Formarse y establecer una comunicación eficaz entre todas las áreas de la empresa.", "La respuesta b) y optimizar los recursos humanos y materiales destinados a la prevención de riesgos laborales."], "c": 3, "e": "Se trata de aplicar la ley a la empresa y optimizar los recursos destinados a prevención.", "r": "Gestión de la prevención · batería oficial, pregunta 327"}, {"id": "ehu328", "q": "¿Que es un accidente de trabajo?", "o": ["Las caídas sufridas", "Toda lesión corporal que la persona trabajadora sufra con ocasión o como consecuencia del trabajo que ejecuta por cuenta ajena.", "Las lesiones por causa ajena.", "Cansarse como consecuencia de la actividad laboral."], "c": 1, "e": "Accidente de trabajo es toda lesión corporal sufrida con ocasión o por consecuencia del trabajo por cuenta ajena.", "r": "LGSS art. 156.1 · batería oficial, pregunta 328"}, {"id": "ehu329", "q": "¿En cuántas áreas está dividido el servicio de prevención de la EHU?", "o": ["Está dividido en 2 áreas: el área sanitaria y el área técnica.", "Está dividido en 2 áreas: el área informática y el área técnica.", "Está dividido en 3 áreas: informática, técnica y sanitaria.", "Está dividido en 2 áreas: el área sanitaria y el área informática."], "c": 0, "e": "Respuesta probable: área sanitaria y área técnica.", "r": "Servicio de Prevención UPV/EHU · batería oficial, pregunta 329"}, {"id": "ehu330", "q": "El servicio de prevención de la EHU tiene como obligación asesorar:", "o": ["Sólo a la Administración.", "Sólo asu personal trabajador y a sus representantes.", "A la Administración y a su personal trabajador y sus representantes.", "A la administración, a su personal trabajador, a sus representantes y a los Comités de Campus e Intercampus de Seguridad y Salud Laboral."], "c": 3, "e": "Respuesta probable: asesora a la Administración, al personal, a sus representantes y a los comités de seguridad y salud.", "r": "Servicio de Prevención UPV/EHU; Ley 31/1995 art. 31 · batería oficial, pregunta 330"}, {"id": "ehu331", "q": "La implantación del Plan de autoprotección comprenderá:", "o": ["Que todo el personal de la EHU esté atento ante una emergencia.", "Que el Servicio de Prevención dé la señal en caso de emergencia.", "Comprenderá, al menos, la formación y capacitación del personal, el establecimiento de mecanismos de información al público y la provisión de los medios y recursos precisa para la aplicabilidad del plan.", "Que todos los recursos funcionen adecuadamente de cara a una inspección de trabajo."], "c": 2, "e": "La implantación incluye formación del personal, información al público y provisión de medios y recursos.", "r": "RD 393/2007 Norma Básica de Autoprotección · batería oficial, pregunta 331"}, {"id": "ehu332", "q": "Una señal de forma redonda con pictograma blanco, fondo azul y borde blanco o azul es una señal de:", "o": ["Advertencia.", "Prohibición.", "Salvamento.", "Obligación."], "c": 3, "e": "Redonda con fondo azul y pictograma blanco: señal de obligación.", "r": "RD 485/1997 anexo III · batería oficial, pregunta 332"}, {"id": "ehu333", "q": "La evacuación del centro de trabajo se realiza cuando:", "o": ["Se ve humo en el centro de trabajo.", "Todas las etapas de protección, detección y extinción del fuego han fallado y existe riesgo para la vida de las personas.", "Cuando los sprinklers comienzan a funcionar.", "Cuando se ha llamado a los bomberos."], "c": 1, "e": "Respuesta probable: se evacua cuando fallan la protección, detección y extinción y hay riesgo para las personas.", "r": "Plan de emergencia · batería oficial, pregunta 333"}, {"id": "ehu334", "q": "Con la señalización de seguridad se pretende:", "o": ["Hacer recomendaciones de seguridad en forma de cartel.", "Lograr que la persona trabajadora se quede inmóvil cuando vea la señal.", "Estimular al trabajador/a a través de los sentidos, para informarle del riesgo.", "Ordenar el tráfico de los vehículos dentro de la empresa."], "c": 2, "e": "Respuesta probable: la señalización estimula los sentidos para informar del riesgo.", "r": "RD 485/1997 · batería oficial, pregunta 334"}, {"id": "ehu335", "q": "Indique el orden que deben llevar las acciones en seguridad:", "o": ["Actuar sobre el receptor, actuar sobre el medio, actuar sobre el riesgo.", "Actuar sobre la máquina, actuar sobre el trabajador, actuar sobre el método de trabajo.", "Actuar sobre el riesgo, actuar sobre el medio, actuar sobre el receptor.", "Actuar sobre el medio, actuar sobre el riesgo, actuar sobre el receptor."], "c": 2, "e": "Primero se actúa sobre el riesgo en origen, luego sobre el medio y por último sobre la persona.", "r": "Ley 31/1995 art. 15 · batería oficial, pregunta 335"}, {"id": "ehu336", "q": "¿Cuál de las siguientes actuaciones con un extintor es correcta? Marque la respuesta correcta", "o": ["Quitar el pasador de seguridad, tirando de la anilla.", "Sujetar la manguera de salida del extintor.", "Dirigirse hacia el incendio y situarse a un metro de distancia al menos.", "Todas las actuaciones anteriores son correctas."], "c": 3, "e": "Respuesta probable: quitar el pasador, sujetar la manguera y acercarse al fuego son pasos del uso del extintor.", "r": "Uso de extintores · batería oficial, pregunta 336"}, {"id": "ehu337", "q": "Según el art. 14 de la Ley de prevención de riesgos laborales ...", "o": ["Los/as trabajadores/as tienen derecho a una protección eficaz.", "Los/as trabajadores/as tienen derecho a una protección integral.", "Los/as trabajadores/as tienen derecho a una evaluación eficaz.", "Los/as trabajadores/as tienen derecho a una protección permanente."], "c": 0, "e": "Los trabajadores tienen derecho a una protección eficaz en seguridad y salud.", "r": "Ley 31/1995 art. 14.1 · batería oficial, pregunta 337"}, {"id": "ehu338", "q": "La realización de simulacros tendrá como objetivos la verificación y comprobación de:", "o": ["Que todo el personal de la plantilla se ha leído el plan de emergencia y de esa manera cumplir con la Ley 31/1995, sobre Prevención de Riesgos Laborales.", "Que al menos el Portero Mayor del centro se ha leído el plan de emergencia, con lo que se garantiza que la puertas y salidas de evacuación estará abiertas en caso de emergencia.", "Que se ha presentado a Protección Civil el Plan de Emergencia y de esa manera en caso de emergencia serán ellos/as los/as que llamen a los/as bomberos/as.", "La eficacia de la organización de respuesta ante una emergencia, la capacitación del personal, el entrenamiento de todo el personal de la actividad en la respuesta frente a una emergencia, la suficiencia e idoneidad de los medios y recursos asignados, la adecuación de los procedimientos de actuación."], "c": 3, "e": "Los simulacros verifican la organización, la capacitación, los medios y los procedimientos de respuesta.", "r": "RD 393/2007 · batería oficial, pregunta 338"}, {"id": "ehu339", "q": "Cuáles son las cuatro disciplinas o especialidades de la prevención de riesgos laborales:", "o": ["Seguridad en el Trabajo, Higiene Industrial, Ergonomía y Psicosociología aplicada.", "Seguridad en el Trabajo, Higiene Industrial, Ergonomía y Psicosociología aplicada y Medicina en el Trabajo.", "Seguridad Laboral, Higiene Industrial, Seguridad Estructural y Vigilancia de la Salud.", "Seguridad en el Trabajo, Higiene Industrial, Ergonomía Estructural y Medicina en el Trabajo."], "c": 1, "e": "Las especialidades son Seguridad en el Trabajo, Higiene Industrial, Ergonomía y Psicosociología Aplicada, y Medicina del Trabajo.", "r": "RD 39/1997 art. 34 · batería oficial, pregunta 339"}, {"id": "ehu340", "q": "Señala el número de delegados/as de prevención que le corresponde tener a las empresas que tienen una plantilla con 503 trabajadores/as:", "o": ["2.", "3.", "4.", "5."], "c": 2, "e": "De 501 a 1.000 trabajadores corresponden 4 delegados de prevención.", "r": "Ley 31/1995 art. 35.2 · batería oficial, pregunta 340"}, {"id": "ehu341", "q": "Según el r.d. 486/1997, sobre disposiciones mínimas en lugares de trabajo, el nivel de iluminación exigido en vías de circulación es:", "o": ["Si la vía es de uso ocasional, 50 lux, y si es de uso habitual, 100 lux .", "Si la vía es de uso ocasional, 25 lux, y si es de uso habitual, 50 lux.", "Si la vía es de uso ocasional, 100 lux, y si es de uso habitual, 200 lux .", "Si la vía es de uso ocasional, 20 lux, y si es de uso habitual, 60 lux ."], "c": 1, "e": "Vías de circulación: 25 lux de uso ocasional y 50 lux de uso habitual.", "r": "RD 486/1997 anexo IV · batería oficial, pregunta 341"}, {"id": "ehu342", "q": "En relacion con la prevención de riesgos laborales, podemos encontrar los colores:", "o": ["Rojo, verde, azul, amarillo o amarillo-anaranjado.", "Rojo, amarillo o amarillo-anaranjado.", "Rojo, blanco, negro, azul o verde.", "Rojo, azul, negro o blanco."], "c": 0, "e": "Los colores de seguridad son rojo, amarillo o amarillo anaranjado, azul y verde.", "r": "RD 485/1997 anexo II · batería oficial, pregunta 342"}, {"id": "ehu343", "q": "En relación con la prevención de riesgos laborales, el color amarillo en una señal significa:", "o": ["Comportamiento o acción específica.", "Obligación de utilizar un equipo de protección individual.", "Comportamientos peligrosos.", "Atención, precaución."], "c": 3, "e": "El amarillo indica atención, precaución.", "r": "RD 485/1997 anexo II · batería oficial, pregunta 343"}, {"id": "ehu344", "q": "En relación con la prevención de riesgos laborales, las señales de prohibición:", "o": ["Tienen forma redonda.", "Tienen forma cuadrada.", "Tienen forma rectangular.", "Tienen forma triangular."], "c": 0, "e": "Las señales de prohibición son redondas.", "r": "RD 485/1997 anexo III · batería oficial, pregunta 344"}, {"id": "ehu345", "q": "En relación con la prevención de riesgos laborales, las señales de obligación:", "o": ["Tienen forma redonda.", "Tienen forma cuadrada.", "Tienen forma rectangular.", "Tienen forma triangular."], "c": 0, "e": "Las señales de obligación son redondas.", "r": "RD 485/1997 anexo III · batería oficial, pregunta 345"}, {"id": "ehu346", "q": "Los accidentes graves o muy graves o que afecten a más de cuatro trabajadores/as deben comunicarse a la autoridad laboral de la provincia:", "o": ["Inmediatamente.", "Enun plazo máximo de 12 horas.", "Enun plazo máximo de 24 horas.", "Enun plazo máximo de 18 horas."], "c": 2, "e": "Respuesta probable: deben comunicarse a la autoridad laboral en un plazo máximo de 24 horas.", "r": "Orden TAS/2926/2002 · batería oficial, pregunta 346"}, {"id": "ehu347", "q": "En relación con la prevención de riesgos laborales, entendemos como carga física:", "o": ["Cualquier esfuerzo realizado con la espalda.", "Todo peso que se levante o no con las manos siempre que se trate de un objeto animado.", "Cualquier objeto animado o inanimado que se caracterice por un peso, una forma, un tamaño, un agarre y una distribución del peso.", "El conjunto de requerimientos físicos a los que se ve sometida la persona a lo largo de su jornada laboral."], "c": 3, "e": "La carga física es el conjunto de requerimientos físicos a los que se somete la persona durante la jornada.", "r": "INSST (ergonomía) · batería oficial, pregunta 347"}, {"id": "ehu348", "q": "Si la máquina fotocopiadora nos indica que hay un atasco en la unidad fusora ¿Donde esta localizado el atasco?", "o": ["En los rodillos.", "En el tambor.", "En la bandeja de recepción.", "Ninguna de las anteriores."], "c": 0, "e": "La unidad fusora está formada por rodillos.", "r": "Ofimática: fotocopiadoras · batería oficial, pregunta 348"}, {"id": "ehu349", "q": "Cuando el vidrio de contacto en una máquina fotocopiadora está sucio ¿Cómo se procedera a su limpieza?", "o": ["Con disolvente.", "Con un paño empapado en amoniaco.", "Con un paño humedecido con alcohol o detergente suave.", "Con cera líquida."], "c": 2, "e": "El cristal se limpia con un paño humedecido con alcohol o detergente suave.", "r": "Ofimática: fotocopiadoras · batería oficial, pregunta 349"}, {"id": "ehu350", "q": "Si un papel lleva el símbolo TCF ¿Qué significa?", "o": ["Que está fabricado con pasta libre de cloro.", "Que está fabricado con pasta de papel blanqueado con dióxido de carbono.", "Que está fabricado con materiales recuperados selectivamente del postconsumo.", "Ninguna de las anteriores."], "c": 0, "e": "TCF (Totally Chlorine Free) significa pasta libre de cloro.", "r": "Papel y medio ambiente · batería oficial, pregunta 350"}]}, {"id": "b10", "sig": "Bloque 10", "titulo": "Bloque 10. Atención al público, reuniones y ergonomía", "sub": "Preguntas 351–400 de la batería oficial (sin respuestas oficiales: resueltas por Claude).", "preguntas": [{"id": "ehu351", "q": "¿La memoria zoom en una fotocopiadora está relacionada con?", "o": ["Intensidad de color.", "Ampliación o reducción de la copia.", "El número de copias que se quiere realizar.", "Ninguna de las anteriores."], "c": 1, "e": "El zoom sirve para ampliar o reducir la copia.", "r": "Ofimática: fotocopiadoras · batería oficial, pregunta 351"}, {"id": "ehu352", "q": "La destrucción de documentos se debe realizar con el:", "o": ["Documento grapado.", "Documento sin grapar.", "Documento archivado por el sistema de púa.", "Todas las respuestas son correctas."], "c": 1, "e": "Los documentos deben destruirse sin grapas.", "r": "Destrucción de documentos · batería oficial, pregunta 352"}, {"id": "ehu353", "q": "La destrucción física de documentos no válidos se denomina:", "o": ["Expurgo.", "Expolio.", "Documentos de archivo.", "Dossier."], "c": 0, "e": "La eliminación física de documentos que ya no tienen valor se llama expurgo.", "r": "Archivística · batería oficial, pregunta 353"}, {"id": "ehu354", "q": "La destrucción física de documentos se debe realizar:", "o": ["Tirándolos a la basura.", "Por cualquier método que garantice la imposibilidad de reconstrucción.", "Tratándolos químicamente.", "Taladrando el ángulo superior derecho de cada documento."], "c": 1, "e": "Hay que usar un método que garantice que no puedan reconstruirse.", "r": "Destrucción de documentos; RGPD · batería oficial, pregunta 354"}, {"id": "ehu355", "q": "A la hora de atender al ciudadano/a se habla de la prestación de un servicio, ¿Qué se quiere decir con ello?", "o": ["Que se realiza la cesión de un bien tangible.", "Que se presta un bien que almacenable y fácilmente medible.", "Que se presta un servicio que no está vinculado a la materialización de un producto.", "Que es un bien que se cede de manera temporal."], "c": 2, "e": "Prestar un servicio es una actividad intangible, no vinculada a un producto material.", "r": "Atención a la ciudadanía · batería oficial, pregunta 355"}, {"id": "ehu356", "q": "¿Cuál es el primer acto de comunicación entre la administración y el/la usuario/a-cliente que acude a ella?", "o": ["El saludo.", "La recepción.", "La comunicación escrita.", "La comunicación oral."], "c": 1, "e": "Respuesta probable: la recepción es el primer acto de comunicación con quien acude.", "r": "Atención a la ciudadanía · batería oficial, pregunta 356"}, {"id": "ehu357", "q": "¿Cuáles son las capacidades básicas que debe tener el profesional de recepción de una administración pública?", "o": ["Claridad de comunicación y capacidad de mando.", "Capacidad de relación y capacidad de solución de conflictos.", "Debe saber aplicarlas técnicas de expresión oral y debe tener capacidad para dar una buena información.", "Capacidad de síntesis y don de gentes."], "c": 2, "e": "Respuesta probable: dominar la expresión oral y saber dar una buena información.", "r": "Atención a la ciudadanía · batería oficial, pregunta 357"}, {"id": "ehu358", "q": "¿Qué diferencia existe en información y comunicación?", "o": ["El significado es el mismo.", "La información la da una sola persona y la comunicación la puedan dar varias.", "La información se produce en un solo sentido y la comunicación requiere de feedback.", "La comunicación siempre es ascendente y la información descendente."], "c": 2, "e": "La información va en un sentido; la comunicación exige retroalimentación.", "r": "Teoría de la comunicación · batería oficial, pregunta 358"}, {"id": "ehu359", "q": "¿En cuál de los siguientes dispositivos predomina la comunicación?", "o": ["En las publicaciones internas.", "En los indicadores de control.", "En las encuestas.", "En las reuniones."], "c": 3, "e": "En las reuniones predomina la comunicación, porque hay intercambio.", "r": "Comunicación interna · batería oficial, pregunta 359"}, {"id": "ehu360", "q": "¿Cuál de las siguientes afirmaciones es la correcta?", "o": ["El/la funcionario/a administrativo es el primer punto de contacto de la Administración con la ciudadanía.", "Los/as Directivos/as son el primer punto de contacto de la Administración con la ciudadanía.", "El/la funcionario/a de atención al público es el primer punto de contacto de la Administración con la ciudadanía.", "Los puestos intermedios son el primer punto de contacto de la Administración con la ciudadanía."], "c": 2, "e": "El personal de atención al público es el primer contacto de la Administración con la ciudadanía.", "r": "Atención a la ciudadanía · batería oficial, pregunta 360"}, {"id": "ehu361", "q": "¿Cuál de las siguientes afirmaciones es la correcta?", "o": ["El desconocimiento o mala elección del lenguaje (vocabulario complejo, estilo inadecuado) es algo que sucede y no tiene ninguna repercusión en la comunicación.", "El desconocimiento o mala elección del lenguaje (vocabulario complejo, estilo inadecuado) es una ventaja en la comunicación.", "El desconocimiento o mala elección del lenguaje (vocabulario complejo, estilo inadecuado) es una barrera en la comunicación.", "La ausencia de motivación es una ventaja en la comunicación."], "c": 2, "e": "Un lenguaje mal elegido es una barrera en la comunicación.", "r": "Comunicación · batería oficial, pregunta 361"}, {"id": "ehu362", "q": "Cuando se atiende al público, las interferencias y ruidos son:", "o": ["Algo que sucede y no tiene ninguna repercusión.", "Una barrera en la comunicación.", "Una ventaja en la comunicación.", "Una característica que facilita la comprensibilidad."], "c": 1, "e": "Interferencias y ruidos son barreras.", "r": "Comunicación · batería oficial, pregunta 362"}, {"id": "ehu363", "q": "Cuando se atiende al público el buen conocimiento de la materia:", "o": ["Ayuda a entender mejor el mensaje.", "Supone una barrera en la comunicación.", "Es una característica que no facilita la comprensibilidad.", "No tiene ninguna repercusión en la comunicación."], "c": 0, "e": "Conocer bien la materia ayuda a entender mejor el mensaje.", "r": "Comunicación · batería oficial, pregunta 363"}, {"id": "ehu364", "q": "La incoherencia del mensaje es:", "o": ["Una ventaja en la comunicación.", "Una barrera en la comunicación.", "Algo que sucede y no tiene ninguna repercusión.", "En la mayoría de las ocasiones conveniente."], "c": 1, "e": "La incoherencia del mensaje es una barrera.", "r": "Comunicación · batería oficial, pregunta 364"}, {"id": "ehu365", "q": "Cuando alguien trabaja atendiendo al público, la intención positiva es:", "o": ["Una barrera en la comunicación.", "Una ventaja en la comunicación.", "Algo que sucede y no tiene ninguna repercusión.", "Algo inevitable."], "c": 1, "e": "La intención positiva favorece la comunicación.", "r": "Comunicación · batería oficial, pregunta 365"}, {"id": "ehu366", "q": "En la comunicación, ¿Cuál de las siguientes frases es la correcta?", "o": ["La brevedad es una característica que no afecta a la comprensión del mensaje.", "La brevedad es una característica que no facilita a la comprensión del mensaje.", "La brevedad es una característica que facilita a la comprensión del mensaje.", "La brevedad es una barrera en la comunicación."], "c": 2, "e": "La brevedad facilita la comprensión.", "r": "Comunicación · batería oficial, pregunta 366"}, {"id": "ehu367", "q": "¿Cuál de las siguientes frases es la correcta?", "o": ["El orden del mensaje es una característica que facilita la comprensión del mismo.", "El orden del mensaje es una característica que no facilita la comprensión del mismo.", "El orden del mensaje es una característica que no afecta a la comprensión del mismo.", "La brevedad es una característica que no facilita a la comprensión del mensaje."], "c": 0, "e": "El orden del mensaje facilita su comprensión.", "r": "Comunicación · batería oficial, pregunta 367"}, {"id": "ehu368", "q": "La actitud de una buena persona informadora debe ser la de:", "o": ["Ser inflexible.", "Estar a la defensiva.", "Ser natural.", "La falta de empatía."], "c": 2, "e": "La persona informadora debe ser natural.", "r": "Atención a la ciudadanía · batería oficial, pregunta 368"}, {"id": "ehu369", "q": "En la comunicación ser cortés indica:", "o": ["Una actitud de buen informador.", "Una actitud de mal informador.", "Una actitud que no afecta.", "Una actitud que no afecta y de mal informador."], "c": 0, "e": "Ser cortés es actitud de buen informador.", "r": "Atención a la ciudadanía · batería oficial, pregunta 369"}, {"id": "ehu370", "q": "Una característica que define a una persona que está informando incorrectamente es:", "o": ["La disponibilidad.", "La profesionalidad.", "La falta de disposición.", "La integridad."], "c": 2, "e": "La falta de disposición caracteriza a quien informa mal.", "r": "Atención a la ciudadanía · batería oficial, pregunta 370"}, {"id": "ehu371", "q": "Los componentes de la comunicación telefónica son:", "o": ["La voz.", "La voz y elocución.", "La voz, elocución, lenguaje y silencio.", "La voz, elocución, lenguaje, silencio y sonrisa."], "c": 3, "e": "Componentes: voz, elocución, lenguaje, silencio y sonrisa.", "r": "Atención telefónica · batería oficial, pregunta 371"}, {"id": "ehu372", "q": "En la conversación telefónica:", "o": ["La persona interlocutora es la que se adapta a nuestra velocidad.", "Hay que saber hablar a mayor velocidad que la de la persona interlocutora.", "No hay que adaptar nuestra velocidad a la de la persona interlocutora.", "Hay que saber adaptar nuestra velocidad a la de la persona interlocutora."], "c": 3, "e": "Hay que adaptar la velocidad a la del interlocutor.", "r": "Atención telefónica · batería oficial, pregunta 372"}, {"id": "ehu373", "q": "En el transcurso de una conversación telefónica hay que:", "o": ["Utilizar un tono normal.", "Susurrar.", "Gritar", "Hablar más rápido que en una conversación oral presencial."], "c": 0, "e": "Se habla con un tono normal.", "r": "Atención telefónica · batería oficial, pregunta 373"}, {"id": "ehu374", "q": "La entonación en la comunicación telefónica:", "o": ["Esun componente que aprecia la persona que está a la escucha.", "No es un componente que se pueda llegar a apreciar.", "Sólo se aprecia en la conversación oral presencial...", "No se debe tener en cuenta"], "c": 0, "e": "La entonación la percibe quien escucha.", "r": "Atención telefónica · batería oficial, pregunta 374"}, {"id": "ehu375", "q": "Cuando se ha llamado a un teléfono equivocado LO más apropiado es:", "o": ["Preguntar a dónde se ha llamado", "Preguntar quién habla.", "Aclarar el número de teléfono que se ha marcado.", "Colgar."], "c": 2, "e": "Lo correcto es aclarar el número marcado.", "r": "Atención telefónica · batería oficial, pregunta 375"}, {"id": "ehu376", "q": "Uno de los errores más frecuentes en la atención al público directa es:", "o": ["Evitar enviara la gente al sitio incorrecto.", "Tener conversaciones privadas en presencia de público.", "Tener conversaciones privadas en privado.", "Mostrarse paciente."], "c": 1, "e": "Un error frecuente es mantener conversaciones privadas delante del público.", "r": "Atención al público · batería oficial, pregunta 376"}, {"id": "ehu377", "q": "En la comunicación presencial comunicador/a-ciudadano/a:", "o": ["Hay que prestar mucha atención a los gestos y al contenido de la conversación.", "Sólo hay que escuchar el contenido de la conversación.", "Hay que responder brevemente.", "Hay que implicarse personalmente."], "c": 0, "e": "Hay que atender tanto a los gestos como al contenido.", "r": "Comunicación presencial · batería oficial, pregunta 377"}, {"id": "ehu378", "q": "En la relación comunicador/a-ciudadano/a, si estamos atendiendo por teléfono y llega una visita, LO más apropiado consiste en:", "o": ["Colgar el teléfono y atender a la visita.", "No atender a la visita y atender el teléfono sin más.", "Hacer un gesto de saludo a la visita y colgar lo antes posible.", "No mostrarse impacientes con la persona que está al teléfono."], "c": 3, "e": "Respuesta probable: se saluda con un gesto a la visita sin mostrarse impaciente con quien está al teléfono.", "r": "Atención al público · batería oficial, pregunta 378"}, {"id": "ehu379", "q": "En la comunicación presencial:", "o": ["Se fomentará el impacto negativo en la percepción ciudadana.", "Se formularán cuantas preguntas sean necesarias para entender perfectamente el problema.", "Se mantendrá una inexpresividad en el rostro.", "Se practicará la escucha pasiva."], "c": 1, "e": "Se hacen las preguntas necesarias para entender bien el problema.", "r": "Comunicación presencial · batería oficial, pregunta 379"}, {"id": "ehu380", "q": "Si se quire tener una comunicación activa con el ciudadanoj/a, se debe:", "o": ["No reformular las preguntas que sean necesarias.", "Cooperar con la persona interlocutora.", "No mostrar una expresión amable en la cara.", "No indagar ni requerir información complementaria."], "c": 1, "e": "La comunicación activa exige cooperar con el interlocutor.", "r": "Comunicación presencial · batería oficial, pregunta 380"}, {"id": "ehu381", "q": "En la comunicación oral presencial, para que exista una comunicación activa entre informador/a-ciudadano/a, debemos:", "o": ["Indagar y requerir información complementaria.", "No mirar a la persona que habla.", "Tener una actitud distante.", "No reformular las preguntas que sean necesarias."], "c": 0, "e": "Hay que indagar y pedir información complementaria.", "r": "Comunicación presencial · batería oficial, pregunta 381"}, {"id": "ehu382", "q": "En las consultas telefónicas demostramos a la persona interlocutora que hemos eentendido:", "o": ["Reformulando la pregunta.", "Contestando lo antes posible.", "Implicándonos personalmente.", "Mostrando impaciencia."], "c": 0, "e": "Reformular la pregunta demuestra que se ha entendido.", "r": "Atención telefónica · batería oficial, pregunta 382"}, {"id": "ehu383", "q": "Las respuestas en las consultas telefónicas deben ser:", "o": ["Formuladas con un lenguaje sencillo y adaptado a la persona interlocutora.", "Formuladas con un lenguaje técnico.", "Formuladas con rapidez.", "Formuladas con expresiones vacilantes."], "c": 0, "e": "Lenguaje sencillo y adaptado al interlocutor.", "r": "Atención telefónica · batería oficial, pregunta 383"}, {"id": "ehu384", "q": "En la atención telefónica, la sonrisa telefónica corresponde a la fase de:", "o": ["Identificación de la necesidad.", "Cierre.", "Presentación.", "Escucha activa."], "c": 2, "e": "La sonrisa telefónica corresponde a la presentación.", "r": "Atención telefónica · batería oficial, pregunta 384"}, {"id": "ehu385", "q": "En la entrevista telefónica, si hay que realizar algún trámite o consulta interna:", "o": ["Si la espera va a ser larga, debemos advertirlo a la persona interlocutora.", "Tomaremos nota y devolveremos la llamada a la persona interlocutora.", "Debemos dejar el teléfono y realizar el trámite o consulta.", "Ninguna de las anteriores es correcta."], "c": 0, "e": "Si la espera va a ser larga, hay que advertirlo.", "r": "Atención telefónica · batería oficial, pregunta 385"}, {"id": "ehu386", "q": "Cuando se atiende al público, si llega una persona con una protesta:", "o": ["Nos implicaremos personalmente.", "Nole dejaremos hablar.", "No tomaremos en serio las objeciones.", "Le dejaremos hablar y tomaremos en serio las objeciones."], "c": 3, "e": "Se le deja hablar y se toman en serio sus objeciones.", "r": "Atención de quejas · batería oficial, pregunta 386"}, {"id": "ehu387", "q": "Si llega un/a ciudadano/a con una reclamación:", "o": ["No aceptaremos la responsabilidad.", "Nole dejaremos hablar.", "No tomaremos en serio las objeciones.", "No nos implicaremos personalmente."], "c": 3, "e": "No hay que tomarse la reclamación como algo personal.", "r": "Atención de reclamaciones · batería oficial, pregunta 387"}, {"id": "ehu388", "q": "La actitud que tiene que tener una persona que está atendiendo al público y le llega una queja es:", "o": ["No aceptar la responsabilidad.", "Mantener una actitud positiva.", "No mostrar empatía.", "No mostrar preocupación."], "c": 1, "e": "Ante una queja, actitud positiva.", "r": "Atención de quejas · batería oficial, pregunta 388"}, {"id": "ehu389", "q": "Un/a administrativo/a abandona el servicio durante 3 horas y no tiene justificación:", "o": ["Podrá estar sujeto a sanción administrativa.", "Está sujeto a responsabilidad civil.", "Está sujeto a responsabilidad penal.", "Está sujeto a responsabilidad civil, responsabilidad penal y a sanción administrativa."], "c": 0, "e": "El abandono injustificado puede dar lugar a sanción disciplinaria.", "r": "Régimen disciplinario · batería oficial, pregunta 389"}, {"id": "ehu390", "q": "Para hacer reuniones se pueden utilizar medios que necesitan de una pantalla para ser proyectados, ¿Cuales son esos medios?", "o": ["Blogs gigantes, pizarras, pizarras iluminadas.", "Transparencias, diapositivas, películas y videos.", "Grabadora audio.", "Muestras."], "c": 1, "e": "Transparencias, diapositivas, películas y vídeos necesitan pantalla.", "r": "Organización de reuniones · batería oficial, pregunta 390"}, {"id": "ehu391", "q": "Cuando en una reunión se quieren poner transparencias, ¿Qué aparato se necesita?", "o": ["Pizarra.", "Video.", "Aparato proyector.", "Cartelógrafo."], "c": 2, "e": "Las transparencias requieren un proyector.", "r": "Organización de reuniones · batería oficial, pregunta 391"}, {"id": "ehu392", "q": "Cuando se utiliza la traducción simultánea:", "o": ["La sala escogida debe tener cabinas de traducción y equipos personales o transmisores personales portátiles.", "La sala debe tener la megafonía alta.", "La sala escogida debe tener sólo cabinas de traducción.", "La sala escogida debe tener sólo transmisores portátiles."], "c": 0, "e": "La traducción simultánea exige cabinas y receptores personales.", "r": "Organización de reuniones · batería oficial, pregunta 392"}, {"id": "ehu393", "q": "En las reuniones se aconseja que la colocación de sillas en la sala:", "o": ["Sea versátil, dependiendo del número de personas y del uso que se le vaya a dar.", "Tenga forma de U.", "Tenga forma de elipse.", "Tenga forma rectangular."], "c": 0, "e": "La disposición de las sillas debe ser versátil según asistentes y uso.", "r": "Organización de reuniones · batería oficial, pregunta 393"}, {"id": "ehu394", "q": "Cuando se realiza una reunión, la disposición convencional tipo teatro:", "o": ["Es recomendable para las presentaciones de productos.", "Es recomendable para hacer presentaciones, debates y lluvia de ideas.", "Es recomendable para hacer dinámicas de grupo.", "Es recomendable para dar conferencias, dar discursos y/o charlas y para presentaciones ejecutivas."], "c": 3, "e": "El formato teatro es para conferencias, discursos y presentaciones ejecutivas.", "r": "Organización de reuniones · batería oficial, pregunta 394"}, {"id": "ehu395", "q": "Cuando se realiza una reunión, la disposición convencional en forma de “yr.", "o": ["Es recomendable para las presentaciones de productos.", "Es recomendable para hacer presentaciones, debates y lluvia de ideas.", "Es recomendable para hacer dinámicas de grupo.", "Es recomendable para dar conferencias, dar discursos y/o charlas y para presentaciones ejecutivas."], "c": 1, "e": "La disposición en U favorece presentaciones, debates y lluvia de ideas.", "r": "Organización de reuniones · batería oficial, pregunta 395"}, {"id": "ehu396", "q": "Los datos de una credencial completa para un congreso son:", "o": ["Logotipo, nombre del organizador.", "Nombre de la persona participante.", "Identificación del acto.", "Logotipo, nombre del organizador, nombre de la persona participante e identificación del acto."], "c": 3, "e": "La credencial lleva logotipo y organizador, nombre del participante e identificación del acto.", "r": "Organización de eventos · batería oficial, pregunta 396"}, {"id": "ehu397", "q": "Estando sentado y para evitar lesiones de espalda, ¿Cuál es la posición adecuada?", "o": ["Inclinada hacia la mesa.", "Con el tronco curvado.", "Apoyado en el respaldo y con el tronco en posición vertical.", "Sin apoyar los antebrazos en la mesa."], "c": 2, "e": "Apoyado en el respaldo y con el tronco vertical.", "r": "RD 488/1997; ergonomía · batería oficial, pregunta 397"}, {"id": "ehu398", "q": "¿Cuál es la distancia adecuada entre la pantalla de visualización de datos y los ojos de quien la utiliza?", "o": ["Menos de 40 cm.", "Entre 60 y 80 cm.", "Más de 90 cm.", "La que la persona usuaria elija."], "c": 1, "e": "Respuesta probable: entre 60 y 80 cm; la norma exige al menos 40 cm.", "r": "RD 488/1997; guía técnica INSST · batería oficial, pregunta 398"}, {"id": "ehu399", "q": "¿Qué es un inventario?", "o": ["Es una nota de entrega.", "Esun tipo de pedido.", "Es un resumen de las mercancías almacenadas.", "Esun tipo de envase."], "c": 2, "e": "El inventario es la relación de las mercancías almacenadas.", "r": "Gestión de almacén · batería oficial, pregunta 399"}, {"id": "ehu400", "q": "Para que se produzca un fuego es condición necesaria y suficiente la concurrencia de:", "o": ["El combustible y una fuente de calor.", "El combustible y el comburente, que generalmente es el oxígeno.", "El combustible, el comburente y una fuente de calor.", "El comburente y una fuente de calor."], "c": 2, "e": "Se necesitan combustible, comburente y calor (triángulo del fuego).", "r": "Protección contra incendios · batería oficial, pregunta 400"}]}, {"id": "b11", "sig": "Bloque 11", "titulo": "Bloque 11. Igualdad, informática y Seguridad Social", "sub": "Preguntas 401–450 de la batería oficial (sin respuestas oficiales: resueltas por Claude).", "preguntas": [{"id": "ehu401", "q": "La Comisión de igualdad de la EHU se constituyó en el año:", "o": ["2008.", "2010.", "2009.", "2011."], "c": 0, "e": "Respuesta probable. Compruébalo en la web de Igualdad de la UPV/EHU.", "r": "Igualdad UPV/EHU · batería oficial, pregunta 401"}, {"id": "ehu402", "q": "Según el IV Plan de igualdad de la EHU ¿Cuál es la respuesta incorrecta respecto a la representación?", "o": ["Se tiende a la paridad en el equipo de gobierno.", "A mayor rango, mayor presencia femenina.", "Hay menos directoras que directores.", "Hay más secretarias que secretarios."], "c": 1, "e": "Es incorrecta: cuanto mayor es el rango, menor es la presencia femenina (segregación vertical).", "r": "IV Plan de Igualdad UPV/EHU · batería oficial, pregunta 402"}, {"id": "ehu403", "q": "Señale la respuesta correcta:", "o": ["Ellll Plan de Igualdad de Mujeres y Hombres de la EHU encomienda a la EHU a poner en vigor antes del 2022 un Protocolo contra las violencias de género.", "La EHU aplica a la comunidad universitaria el Protocolo contra las violencias de género aprobado en mayo de 2016 por la Consejería de Universidades del Gobierno Vasco.", "El Consejo de Gobierno aprobó en junio de 2018 el Protocolo de la EHU contra las violencias de género.", "Por Resolución de la Rectora de 7 de junio de 2018 se aprobó el Protocolo de la EHU contra as violencias de género."], "c": 2, "e": "Respuesta probable. Compruébalo en el Protocolo contra las violencias de género de la UPV/EHU.", "r": "Protocolo UPV/EHU contra las violencias de género · batería oficial, pregunta 403"}, {"id": "ehu404", "q": "El IV Plan de igualdad de mujeres y hombres de la EHU busca eliminar:", "o": ["Diferencias académicas.", "Roles y estereotipos de género.", "Idiomas cooficiales.", "Autonomía universitaria."], "c": 1, "e": "El Plan busca eliminar roles y estereotipos de género.", "r": "IV Plan de Igualdad UPV/EHU · batería oficial, pregunta 404"}, {"id": "ehu405", "q": "El día internacional de la mujer y la niña en la ciencia se conmemora cada:", "o": ["8de marzo.", "25 de noviembre.", "11 de febrero.", "El viernes incluido en la Semana de la Ciencia (evento anual)."], "c": 2, "e": "El Día Internacional de la Mujer y la Niña en la Ciencia es el 11 de febrero.", "r": "ONU, resolución 70/212 · batería oficial, pregunta 405"}, {"id": "ehu406", "q": "¿Cuándo existe discriminación indirecta por razón de sexo?:", "o": ["Cuando una persona es tratada de manera menos favorable que otra por razón de su sexo.", "Cuando un acto jurídico, criterio o práctica aparentemente neutra perjudica a una proporción sustancialmente mayor de personas de un mismo sexo, sin justificación objetiva..", "Cuando se producen actos de acoso sexual en el ámbito laboral.", "Cuando una norma establece tratamientos diferentes para mujeres y hombres sin ningún motivos."], "c": 1, "e": "Hay discriminación indirecta cuando una práctica aparentemente neutra perjudica a un sexo sin justificación objetiva.", "r": "LO 3/2007 art. 6.2 · batería oficial, pregunta 406"}, {"id": "ehu407", "q": "Según el vigente Plan de igualdad de la EHU, la “segregación vertical\" implica;", "o": ["Diferencias entre ramas académicas.", "Distribución desigual por sexos en posiciones jerárquicas.", "Diferencias en el estudiantado.", "Diferencias en elección de estudios."], "c": 1, "e": "La segregación vertical es la distribución desigual por sexos en los niveles jerárquicos.", "r": "Plan de Igualdad UPV/EHU · batería oficial, pregunta 407"}, {"id": "ehu408", "q": "La compra pública ecológica se define en la comunicación de la Comisión Europea “contratación pública para un medio ambiente mejor” como:", "o": ["El procedimiento de contratación pública que obliga a que un porcentaje de las compras tenga una etiqueta ecológica.", "Un proceso por el cual las autoridades públicas tratan de adquirir mercancías, servicios y obras con un impacto medioambiental reducido durante su ciclo de vida, en comparación con el de otras mercancías, servicios y obras con la misma función primaria que se adquirirían en su lugar.", "Un proceso por el que las administraciones públicas priman la compra de productos ecológicos", "El procedimiento por el que las autoridades públicas cumplen con las directivas de compra ecológica."], "c": 1, "e": "Es el proceso de adquirir bienes, servicios y obras con menor impacto ambiental durante su ciclo de vida.", "r": "Comunicación COM(2008) 400 · batería oficial, pregunta 408"}, {"id": "ehu409", "q": "Las funcionarias de carrera víctimas de violencia de género tendrán derecho a solicittr la situación de excedencia:", "o": ["Necesita haber prestado un tiempo mínimo de 3 años de servicios previos.", "No se le exige plazo de permanencia en la misma.", "Durante los dos primeros meses de la excedencia tendrán derecho a la reserva del puesto que desempeñen.", "Dicho período será computable a efectos de antigüedad, carrera profesional y derechos del régimen de la S.S. que sea de aplicación."], "c": 1, "e": "No se exige tiempo mínimo de servicios ni plazo de permanencia; la reserva de puesto es de seis meses. Ojo: la d también reproduce lo que dice la ley.", "r": "TREBEP art. 89.5 · batería oficial, pregunta 409"}, {"id": "ehu410", "q": "Según el programa de “compra y contratación pública verde del País Vasco 2020\", todas las administraciones participantes deberán alcanzar una ambientalización en la compra y contratación para el ejercicio 2020, de:", "o": ["Al menos un 30%.", "Al menos un 50%.", "Al menos un 40%.", "Al menos un 20%."], "c": 1, "e": "Respuesta probable: el objetivo era ambientalizar al menos el 50% de la compra.", "r": "Programa de Compra y Contratación Pública Verde del País Vasco 2020 · batería oficial, pregunta 410"}, {"id": "ehu411", "q": "Indique cuál de las siguientes no es una línea estratégica del programa de compra y contratación publica verde del País Vasco 2020:", "o": ["Contenido y herramientas para la implementación.", "Integración en los procedimientos de contratación.", "Formación, capacitación y sensibilización.", "Observancia estricta del articulado de Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público para obtener el mejor precio por los bienes/servicios contratados."], "c": 3, "e": "Buscar el mejor precio cumpliendo la LCSP no es una línea estratégica del programa verde.", "r": "Programa de Compra Verde PV 2020 · batería oficial, pregunta 411"}, {"id": "ehu412", "q": "En Internet, las páginas web creadas para atraer de la forma más rápida al mayor número de leads, se denomina:", "o": ["Microsites.", "Portal web.", "Favorite site.", "Landing page."], "c": 3, "e": "Una landing page es una página creada para captar contactos (leads).", "r": "Marketing digital · batería oficial, pregunta 412"}, {"id": "ehu413", "q": "Estarán exentos del cumplimiento del régimen general de preceptividad de los perfiles linguísticos en relación con el puesto de trabajo del que son titulares:", "o": ["Las personas que superen la edad de 55 años al inicio de cada período de planificación en el que se asigne la fecha de preceptividad al puesto de trabajo del que son titulares, previa conformidad de la persona interesada. Asimismo, también estarán exentas las personas que, en caso de que se apruebe la modificación del perfil linguístico previamente asignado al puesto de trabajo del que son titulares, superen la edad de 45 años, previa conformidad de a persona interesada.", "Las personas cuyo nivel de estudios realizados alcanzar a los de Bachiller Elemental, Educación General Básica o Educación Secundaria Obligatoria, ni otros que, en el futuro, pudieran sustituir a estos, prescindiendo de las equivalencias y convalidaciones que contemple el ordenamiento jurídico a otros fines respecto al Certificado de Escolaridad.", "Las personas en las que no concurra carencia manifiesta y contrastada de las destrezas aptitudinales necesarias en el proceso de aprendizaje del idioma mediante los programas de formación y capacitación lingüística de personas adultas.", "Todas las respuestas anteriores son incorrectas."], "c": 0, "e": "Respuesta probable. Las opciones b y c dicen lo contrario de la norma (les falta un «no»).", "r": "Decreto 86/1997, de normalización del euskera en las Administraciones Públicas de la CAPV · batería oficial, pregunta 413"}, {"id": "ehu414", "q": "Indique cuál de estos componentes pertenece al software del ordenador:", "o": ["Sistema operativo.", "Disco duro.", "Unidad de DVD y CD.", "Impresora."], "c": 0, "e": "El sistema operativo es software.", "r": "Informática básica · batería oficial, pregunta 414"}, {"id": "ehu415", "q": "Indique cuál de estos elementos no pertenece al hardware del ordenador:", "o": ["Memoria RAM.", "Ratón.", "Drivers.", "Disco duro."], "c": 2, "e": "Los drivers son software.", "r": "Informática básica · batería oficial, pregunta 415"}, {"id": "ehu416", "q": "En los criterios básicos de la compra pública ecológica (CPE) de la Unión Europea, aplicables al papel reciclado para usos profesionales, este papel debera estar fabricado:", "o": ["Al menos con un 50% de fibra de papel recuperado.", "Al menos con un 75 % de fibra de papel recuperado.", "Al menos con un 40% de fibra de papel recuperado.", "Al menos con un 90% de fibra de papel recuperado."], "c": 1, "e": "Respuesta probable: al menos un 75% de fibra recuperada.", "r": "Criterios CPE de la UE para papel · batería oficial, pregunta 416"}, {"id": "ehu417", "q": "¿Qué es un sistema operativo?:", "o": ["Esun hardware que gestiona los recursos del ordenador.", "Esun lenguaje de programación.", "Es un software que proporciona un entorno de trabajo donde se pueden ejecutar programas.", "Esun software multitarea."], "c": 2, "e": "El sistema operativo es el software que proporciona el entorno donde se ejecutan los programas.", "r": "Informática básica · batería oficial, pregunta 417"}, {"id": "ehu418", "q": "¿Qué es un OCR?", "o": ["Un dispositivo para calibrar impresoras.", "Un dispositivo para calibrar monitores.", "Una aplicación de calibración de monitores.", "Una aplicación de reconocimiento de caracteres."], "c": 3, "e": "OCR es el reconocimiento óptico de caracteres.", "r": "Informática básica · batería oficial, pregunta 418"}, {"id": "ehu419", "q": "¿Cuáles de los siguientes son dominios de Internet denominados gtld o de nivel superior genérico?", "o": [".eu,.eus y .es", ".uky.es", ".com,.net, .org y.info..", ".inter, mov y .tld"], "c": 2, "e": ".com, .net, .org e .info son dominios genéricos.", "r": "Internet · batería oficial, pregunta 419"}, {"id": "ehu420", "q": "Según la Ley 23/2011, de 29 de julio, de depósito legal, ¿Qué es un documento electronico?", "o": ["Espacio en Internet de una empresa, organización, o de una persona física, asociado a un nombre o una dirección, que permite que su información o contenido, productos o servicios, sean accesibles.", "Información o contenido de cualquier naturaleza, en un soporte electrónico, archivado con un formato determinado y susceptible de identificación y tratamiento diferenciado, que sea objeto de difusión.", "Información o contenido de cualquier naturaleza en soporte electrónico, archivado con un formato determinado y susceptible de identificación y tratamiento diferenciado.", "Punto de acceso electrónico formado por una o varias páginas electrónicas agrupadas en un dominio de Internet."], "c": 2, "e": "Documento electrónico es el contenido en soporte electrónico con formato determinado y susceptible de identificación y tratamiento diferenciado.", "r": "Ley 23/2011 art. 3 · batería oficial, pregunta 420"}, {"id": "ehu421", "q": "Según la Ley 23/2011, de 29 de julio, de depósito legal, ¿Qué es un dominio de Internet?", "o": ["Espacio en Internet de una empresa, organización, o de una persona física, asociado a un nombre o una dirección, que permite que su información o contenido, productos o servicios, sean accesibles.", "Información o contenido de cualquier naturaleza, en un soporte electrónico, archivado con un formato determinado y susceptible de identificación y tratamiento diferenciado, que sea objeto de difusión.", "Información o contenido de cualquier naturaleza en soporte electrónico, archivado con un formato determinado y susceptible de identificación y tratamiento diferenciado.", "Punto de acceso electrónico formado por una o varias páginas electrónicas agrupadas en un dominio de Internet."], "c": 0, "e": "Dominio de Internet es el espacio asociado a un nombre o dirección que hace accesible su contenido.", "r": "Ley 23/2011 art. 3 · batería oficial, pregunta 421"}, {"id": "ehu422", "q": "Según la Ley 23/2011, de 29 de julio, de depósito legal, ¿Qué es un sitio web?", "o": ["Espacio en Internet de una empresa, organización, o de una persona física, asociado a un nombre o una dirección, que permite que su información o contenido, productos o servicios, sean accesibles.", "Información o contenido de cualquier naturaleza, en un soporte electrónico, archivado con un formato determinado y susceptible de identificación y tratamiento diferenciado, que sea objeto de difusión.", "Información o contenido de cualquier naturaleza en soporte electrónico, archivado con un formato determinado y susceptible de identificación y tratamiento diferenciado.", "Punto de acceso electrónico formado por una o varias páginas electrónicas agrupadas en un dominio de Internet."], "c": 3, "e": "Sitio web es el punto de acceso formado por una o varias páginas agrupadas en un dominio.", "r": "Ley 23/2011 art. 3 · batería oficial, pregunta 422"}, {"id": "ehu423", "q": "Según la Ley 23/201 1, de 29 de julio, de depósito legal, ¿Qué es \"un punto de acceso electrónico formado por una o varias páginas electrónicas agrupadas en un dominio de Internet”?", "o": ["Un documento electronico.", "Un dominio de internet.", "Un sitio web.", "Una publicacion electronica."], "c": 2, "e": "Esa es la definición de sitio web.", "r": "Ley 23/2011 art. 3 · batería oficial, pregunta 423"}, {"id": "ehu424", "q": "Según la Ley 23/2011, de 29 de julio, de depósito legal, ¿Qué es “la información o contenido de cualquier naturaleza en soporte electrónico, archivado con un formato determinado y susceptible de identificación y tratamiento diferenciado”?", "o": ["Un documento electronico.", "Un dominio de internet.", "Un sitio web.", "Una publicacion electronica."], "c": 0, "e": "Esa es la definición de documento electrónico.", "r": "Ley 23/2011 art. 3 · batería oficial, pregunta 424"}, {"id": "ehu425", "q": "Indique la afirmación incorrecta en referencia al sistema de Seguridad Social:", "o": ["El Sistema Especial para Empleados de Hogar está dentro del Régimen General de la Seguridad Social.", "El Régimen Especial de Minería del Carbón es uno de los Regímenes Especiales de la Seguridad Social.", "El Régimen Especial Agrario es uno de los Regímenes Especiales de la Seguridad Social.", "El Sistema Especial de la Industria Resinera está dentro del Régimen General de la Seguridad Social."], "c": 2, "e": "El Régimen Especial Agrario ya no existe; se integró en el Régimen General y en el de autónomos.", "r": "LGSS (RDLeg 8/2015) · batería oficial, pregunta 425"}, {"id": "ehu426", "q": "Señale la afirmación incorrecta:", "o": ["El Sistema de la Seguridad Social da cobertura sólo a las personas que ejercen una actividad profesional, así como a los familiares o asimilados que tuvieran a su cargo.", "El Sistema de la Seguridad Social es un conjunto de regímenes a través de los cuales el Estado garantiza a las personas comprendidas en su campo de aplicación la protección adecuada en las contingencias y situaciones que la ley define.", "La protección que ofrece el Sistema de la Seguridad Social también es de aplicación a personas que cumplan los requisitos exigidos en la modalidad no contributiva.", "La protección que ofrece el Sistema de la Seguridad Social también es de aplicación a los familiares o asimilados que las personas beneficiarias tuvieran a su cargo."], "c": 0, "e": "Es incorrecta: la Seguridad Social no cubre solo a quienes trabajan, también la modalidad no contributiva.", "r": "LGSS art. 2 · batería oficial, pregunta 426"}, {"id": "ehu427", "q": "El derecho a la protección de la salud se reconoce en la Constitución Española como:", "o": ["Un derecho de los ciudadanos.", "Un derecho fundamental.", "Un principio rector de la política social y económica.", "Un deber de los ciudadanos"], "c": 2, "e": "La protección de la salud es un principio rector de la política social y económica.", "r": "CE art. 43 · batería oficial, pregunta 427"}, {"id": "ehu428", "q": "A efectos de las prestaciones de modalidad contributiva, están incluidos dentro del campo de aplicación del sistema de la Seguridad Social, cualquiera que sea su sexo, estado civil o profesión,", "o": ["Sólo los españoles que tengan su residencia en España, aunque estén trabajando permanentemente en el extranjero.", "Las personas extranjeras que residan o se encuentren legalmente en España, siempre que el empleador tenga su domicilio fiscal en España.", "Todos los españoles que residan en España, y los extranjeros que residan o se encuentren legalmente en España, siempre que, en el caso de estos últimos, ejerzan su actividad en territorio nacional.", "Todos los españoles que residan en España, y los extranjeros que residan o se encuentren legalmente en España, siempre que, en ambos supuestos, ejerzan su actividad en territorio nacional."], "c": 2, "e": "Españoles residentes y extranjeros que residan o se encuentren legalmente en España, si ejercen su actividad en territorio nacional.", "r": "LGSS art. 7.1 · batería oficial, pregunta 428"}, {"id": "ehu429", "q": "Los convenios especiales que se pueden suscribir con la Seguridad Social:", "o": ["Con carácter general son un acuerdo suscrito voluntariamente por los trabajadores con la Tesorería General de la Seguridad Social para poder percibir una cuantía mayor en la jubilación.", "Con carácter general es un acuerdo suscrito obligatoriamente por los trabajadores con la Tesorería General de la Seguridad Social con el fin de generar, mantener o ampliar, en determinadas situaciones, el derecho a las prestaciones de la Seguridad Social", "En el convenio especial de empresas y trabajadores sujetos a expedientes de regulación de empleo que incluya a trabajadores de 55 o más años, la suscripción se ofrece voluntariamente por la Dirección Provincial de trabajo.", "En el convenio especial de empresas y trabajadores sujetos a expedientes de regulación de empleo que incluya a trabajadores de 55 o más años, el acuerdo se suscribe por la empresa y el trabajador de una parte y la Tesorería General de la Seguridad Social de otra."], "c": 3, "e": "Respuesta probable: en los ERE con mayores de 55 años, el convenio lo suscriben empresa y trabajador con la TGSS.", "r": "LGSS DA 31ª; Orden TAS/2865/2003 · batería oficial, pregunta 429"}, {"id": "ehu430", "q": "Indique cual de los siguientes grupos no se incluye dentro de la modalidad contributiva a efecto de prestaciones de la Seguridad Social:", "o": ["Trabajadores por cuenta propia o autónomos.", "Socios trabajadores de cooperativas de trabajo asociado.", "Personas que sólo trabajan en las labores de su hogar particular.", "Estudiantes."], "c": 2, "e": "Las personas que solo realizan labores de su hogar no están incluidas.", "r": "LGSS art. 7 · batería oficial, pregunta 430"}, {"id": "ehu431", "q": "El convenio especial con la Seguridad Social tendrá como objeto la cobertura de las prestaciones correspondientes a:", "o": ["Entre otras, Invalidez permanente, muerte y supervivencia, derivadas de enfermedad común y accidente laboral.", "Entre otras, jubilación y servicios sociales.", "Entre otras, Invalidez transitoria, muerte y supervivencia, derivadas de enfermedad común y accidente no laboral.", "Entre otras, Invalidez permanente, muerte y supervivencia, derivadas de enfermedad profesional y accidente no laboral."], "c": 0, "e": "Respuesta probable: cubre, entre otras, incapacidad permanente, muerte y supervivencia.", "r": "Orden TAS/2865/2003 · batería oficial, pregunta 431"}, {"id": "ehu432", "q": "Señale la afirmación correcta:", "o": ["El plazo para la presentación de las solicitudes de alta en el Régimen General es de, como máximo, 3 días antes del inicio de la prestación.", "El plazo para la presentación de las solicitudes de baja en el Régimen General es de, como máximo, 3 días antes del fin de la prestación.", "El plazo para la presentación de las solicitudes de baja en el Régimen General es de, como máximo, 3 días posteriores al fin de la prestación.", "El plazo para la presentación de las solicitudes de alta en el Régimen General es de, como máximo, hasta 3 días después del inicio de la prestación."], "c": 2, "e": "La baja se comunica en los tres días naturales siguientes al cese; el alta debe ser previa al inicio.", "r": "RD 84/1996 art. 32 · batería oficial, pregunta 432"}, {"id": "ehu433", "q": "A efectos de afiliación al sistema de la Seguridad Social, indique la situación que no está considerada como asimilada al alta:", "o": ["Situación legal de desempleo, total y subsidiado, y la de paro involuntario una vez agotada la prestación contributiva o asistencial, siempre que se mantenga la inscripción como desempleado en la Oficina de Empleo.", "La excedencia forzosa.", "La situación de excedencia para el cuidado de hijos con reserva de puesto de trabajo, de acuerdo con la legislación aplicable.", "El desplazamiento del trabajador fuera del territorio nacional tras un cambio voluntario de trabajo."], "c": 3, "e": "El traslado voluntario al extranjero no es situación asimilada al alta; sí lo es el traslado por la empresa.", "r": "RD 84/1996 art. 36 · batería oficial, pregunta 433"}, {"id": "ehu434", "q": "¿Quiénes son los sujetos obligados a la comunicación de las altas, bajas y variaciones a la Seguridad Social en el régimen general?", "o": ["La persona trabajadora, con el visto bueno de la parte empleadora", "La parte empleadora firmará en todo caso esas comunicaciones, quedando a voluntad del trabajador la firma de conformidad con dichas comunicaciones", "La parte empleadora firmará y tramitará esas comunicaciones; las solicitudes de alta y variación de datos del trabajador por cuenta ajena deberán ir firmadas en todo caso por el trabajador.", "El alta y la baja ha de tramitarse necesariamente por el empresario; las variaciones pueden ser tramitadas por los representantes de los trabajadores, si así está previsto en el correspondiente Convenio Colectivo de Empresa."], "c": 2, "e": "Respuesta probable. Compruébalo en el reglamento de afiliación.", "r": "RD 84/1996 art. 30 · batería oficial, pregunta 434"}, {"id": "ehu435", "q": "Señale la afirmación correcta:", "o": ["Cuando el trabajador se traslade a un centro de trabajo del mismo empresario situado en diferente provincia, deberá promoverse la baja en la provincia de procedencia y el alta en la de destino.", "A efectos de afiliación, no es necesario realizar ningún trámite ante la Seguridad Social cuando el trabajador se traslade a un centro de trabajo del mismo empresario situado en diferente provincia.", "A efectos de afiliación a la Seguridad Social, cuando el trabajador se traslade a un centro de trabajo del mismo empresario situado en diferente provincia, el empresario ha de tramitar una solicitud de variación en los datos.", "Corresponderá presentar una variación de datos cuando, por cualquier causa, proceda la adscripción del trabajador a una cuenta de cotización distinta."], "c": 3, "e": "Respuesta probable: procede variación de datos cuando el trabajador pasa a otra cuenta de cotización.", "r": "RD 84/1996 · batería oficial, pregunta 435"}, {"id": "ehu436", "q": "Con carácter general, los efectos de las altas serán:", "o": ["Las altas presentadas con carácter previo a la prestación de los servicios únicamente surtirán efectos, en orden a los derechos y obligaciones inherentes a dicha situación, a partir del primer día del mes en el que se inicie la actividad.", "Las altas presentadas fuera de plazo sólo tendrán efectos desde el día en que se formule la solicitud, salvo que se haya producido ingreso de cuotas en plazo reglamentario, en cuyo caso el alta retrotraerá sus efectos a la fecha en que se hayan ingresado las primeras cuotas correspondientes al trabajador de que se trate.", "Las altas practicadas de oficio por las Direcciones Provinciales de la Tesorería General de la Seguridad Social o las Administraciones tendrán sus efectos en la fecha en que las Resoluciones que las dicten adquieran firmeza.", "Las altas presentadas con carácter previo a la prestación de los servicios únicamente surtirán efectos anticipados si la persona empleada asume la cotización correspondiente al plazo entre la fecha de la comunicación y la fecha en la que se inicie la actividad."], "c": 1, "e": "Respuesta probable: las altas fuera de plazo solo surten efecto desde la solicitud, salvo ingreso de cuotas en plazo.", "r": "RD 84/1996 art. 35 · batería oficial, pregunta 436"}, {"id": "ehu437", "q": "Señale la opción incorrecta. Con carácter general, los efectos de las bajas de afiliación:", "o": ["La baja del trabajador producirá efectos desde el cese en la prestación de los servicios por cuenta ajena, en la actividad por cuenta propia o, en su caso, en la situación determinante de su inclusión en el Régimen de que se trate.", "La solicitud de baja del trabajador extinguirá la obligación de cotizar desde el cese en el trabajo.", "Silla baja se solicita fuera de plazo, pero en los 5 días hábiles siguientes al cese en el trabajo, la obligación de cotizar se extingue en todo caso ese día de cese; pasado el quinto día, la obligación de cotizar se extingue en el día en que la Tesorería General de la Seguridad Social conozca el cese en el trabajo por cuenta ajena, o en la actividad por cuenta propia.", "Cuando la Tesorería General de la Seguridad Social curse la baja de oficio, la obligación de cotizar se extinguirá desde el mismo día en que se haya llevado a cabo la actuación inspectora, o se hayan recibido los datos o documentos que acrediten el cese en el trabajo."], "c": 2, "e": "Respuesta probable. Compruébalo en el reglamento de afiliación.", "r": "RD 84/1996 art. 35 · batería oficial, pregunta 437"}, {"id": "ehu438", "q": "De las siguientes opciones, indique la que no es una prestación de la acción protectora de la Seguridad Social:", "o": ["Riesgo durante el embarazo.", "Riesgo durante la lactancia artificial.", "Nacimiento y cuidado de menor.", "Cuidado de menores afectados por cáncer u otra enfermedad grave."], "c": 1, "e": "La prestación es por riesgo durante la lactancia natural, no artificial.", "r": "LGSS art. 42 · batería oficial, pregunta 438"}, {"id": "ehu439", "q": "Indique la opción correcta:", "o": ["La Seguridad Social incluye, entre sus prestaciones, la compensación de los gastos de sepelio", "La Prestación temporal de viudedad de la Seguridad Social tiene una duración máxima de 1 año.", "Las personas beneficiarias de la pensión de orfandad son los descendientes menores de edad, salvo que concurra una discapacidad, en cuyo caso pensión se mantiene hasta los 25 años.", "La Seguridad Social prevé, en caso de muerte causada por accidente no laboral o enfermedad común, una indemnización a tanto alzado a determinados beneficiarios, además de la correspondiente pensión."], "c": 0, "e": "La Seguridad Social incluye el auxilio por defunción para gastos de sepelio.", "r": "LGSS art. 218 · batería oficial, pregunta 439"}, {"id": "ehu440", "q": "Señale la opción incorrecta. Según la normativa de la Seguridad Social, el período en que se permanezca en la situación de excedencia laboral para el cuidado del menor a cargo produce los siguientes efectos:", "o": ["Será computable a efectos de antiguedad.", "Se tendrá derecho a la asistencia a cursos de formación profesional.", "A efecto de las prestaciones por desempleo, todo el período de excedencia tendrá la consideración de situación asimilada a la de alta.", "Durante los seis primeros meses, el trabajador tendrá derecho a la reserva de su puesto de trabajo; si se trata de familias numerosas, de cualquier categoría, el plazo se amplía a los primeros 15 meses."], "c": 3, "e": "Es incorrecta: la reserva de puesto es del primer año (15 o 18 meses en familias numerosas).", "r": "ET art. 46.3; LGSS art. 237 · batería oficial, pregunta 440"}, {"id": "ehu441", "q": "De conformidad con LO establecido en la Ley general de la Seguridad Social, se entiende suspendida la obligación de cotizar:", "o": ["Mientras el trabajador disfrute de un permiso sin sueldo.", "En el supuesto de ejercicio del derecho de huelga por el trabajador.", "Durante la situación de incapacidad temporal del trabajador.", "Todas las opciones anteriores son correctas."], "c": 1, "e": "La obligación de cotizar se suspende durante la huelga.", "r": "LGSS art. 144.4 · batería oficial, pregunta 441"}, {"id": "ehu442", "q": "Según el artículo 42 del texto refundido de la Ley general de la Seguridad Social (Real Decreto legislativo 8/2015, de 30 de octubre), la acción protectora del sistema de la Seguridad Social comprende:", "o": ["La asistencia sanitaria en los casos de maternidad.", "La asistencia sanitaria de enfermedad común o profesional.", "La asistencia sanitaria de accidente sea o no de trabajo.", "Todas las opciones anteriores son correctas."], "c": 3, "e": "Incluye la asistencia sanitaria en maternidad, enfermedad común o profesional y accidente.", "r": "LGSS art. 42.1.a · batería oficial, pregunta 442"}, {"id": "ehu443", "q": "Son principios éticos de la conducta de los/as empleados/as públicos/as:", "o": ["Principios de eficacia y cooperación.", "Principios de lealtad y buena fe con la Administración en la que presten sus servicios, y con sus superiores, compañeros, subordinados y con los ciudadanos.", "Principios de eficiencia y concentración.", "Todas las anteriores son correctas."], "c": 1, "e": "Es principio ético la lealtad y buena fe con la Administración, superiores, compañeros, subordinados y ciudadanos.", "r": "TREBEP art. 53.3 · batería oficial, pregunta 443"}, {"id": "ehu444", "q": "Indique cual no es un principio general recogido en Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos.", "o": ["Principios de tecnología privativa y de vigilancia al progreso de las tecnologías y sistemas de comunicaciones electrónicas.", "Principio de accesibilidad.", "Principio de facilidad de uso.", "Principio de personalización y proactividad,"], "c": 0, "e": "El reglamento recoge la neutralidad tecnológica, no la tecnología privativa.", "r": "RD 203/2021 art. 2 · batería oficial, pregunta 444"}, {"id": "ehu445", "q": "Al respecto de MUFACE, indique la afirmación incorrecta:", "o": ["Su ámbito de actuación de extiende al colectivo de Funcionarios Civiles y Militares del Estado y de otras Administraciones Públicas.", "El reconocimiento de los derechos pasivos y la concesión de las pensiones de clases pasivas al personal funcionario, no es competencia de MUFACE.", "El Ministerio de Inclusión, Seguridad Social y Migraciones gestiona el Régimen de Clases Pasivas.", "Los derechos pasivos de aquellos mutualistas que ingresaron en la Administración a partir del 1 de enero de 2011 los gestiona el Instituto Nacional de la Seguridad Social, INSS."], "c": 0, "e": "Es incorrecta: MUFACE es para funcionarios civiles; los militares tienen ISFAS.", "r": "RDLeg 4/2000 (MUFACE) · batería oficial, pregunta 445"}, {"id": "ehu446", "q": "Indique la prestación que no es gestionada por MUFACE:", "o": ["Indemnizaciones por lesiones permanentes no invalidantes.", "Prestación económica por gran invalidez.", "Viudedad.", "La asistencia sanitaria y la farmacéutica, complementaria de la anterior."], "c": 2, "e": "La viudedad es una pensión de Clases Pasivas, no de MUFACE.", "r": "RDLeg 4/2000 (MUFACE) · batería oficial, pregunta 446"}, {"id": "ehu447", "q": "Indique la opción correcta:", "o": ["Las personas adscritas al Régimen de MUFACE tienen derecho a la asistencia sanitaria prestada por los servicios autonómicos de salud.", "MUFACE tiene una red propia de hospitales y profesionales de la sanidad repartidos por toda la geografía del Estado Español.", "Si existe concierto previo, las aseguradoras privadas pueden facilitan la asistencia sanitaria a mutualistas y beneficiarios de MUFACE.", "MUFACE es la que indica a cada mutualista la entidad o aseguradora que ha de prestarle la asistencia sanitaria, en función de su rango de edad, así como de la Administración en la que presta servicios."], "c": 2, "e": "MUFACE presta la asistencia a través de entidades concertadas o del sistema público, mediante concierto.", "r": "RDLeg 4/2000 (MUFACE) · batería oficial, pregunta 447"}, {"id": "ehu448", "q": "Indique la afirmación incorrecta según LO dispuesto en el Manual de archivo de gestión o archivo de oficina de la EHU:", "o": ["Los documentos generados por los Departamentos, Facultades, Escuelas e Institutos Universitarios en el desempeño de sus funciones forman parte del Patrimonio Documental de la Universidad.", "Los documentos adquiridos por compraventa no forman parte del Patrimonio Documental de la Universidad, al no haber sido generados por ningún órgano de ésta.", "Se considera también documento de Archivo de la EHU toda expresión en lenguaje natural o convencional y cualquier otra expresión gráfica, sonora o en imagen, recogida en soportes informáticos.", "Los documentos que formen parte del Patrimonio Bibliográfico no son susceptibles de ser considerados documentos de Archivo."], "c": 1, "e": "Es incorrecta: los documentos adquiridos por compraventa también pueden formar parte del patrimonio documental.", "r": "Manual de Archivo de Gestión UPV/EHU · batería oficial, pregunta 448"}, {"id": "ehu449", "q": "Según el Manual de archivo de gestión o archivo de oficina de la EHU, cuando prescribe el valor administrativo del documento administrativo, ¿Es objeto de expurgo en todo caso?", "o": ["Sí, siempre ya que ocupa lugar físico o electrónico.", "No, si son documentos generados por los Órganos Superiores de la EHU (Consejo de Gobierno, Claustro y Gabinete del Rector/a.", "No siempre, ya que en los documentos pueden aflorar otros valores que planteen la necesidad de su conservación permanente.", "Ningún documento administrativo, sea cual sea el Órgano que lo ha generado y tenga el contenido que sea, es objeto de destrucción; a lo sumo se escanea para su conservación en un soporte electrónico."], "c": 2, "e": "No siempre: pueden aflorar otros valores que exijan conservarlos.", "r": "Manual de Archivo de Gestión UPV/EHU · batería oficial, pregunta 449"}, {"id": "ehu450", "q": "De los siguientes, indique cual no se debería conservar en un archivo de gestión o de oficina:", "o": ["Una solicitud no resuelta de una exención de matrícula.", "Un expediente disciplinario a un funcionario fallecido hace tres años.", "Una solicitud de licencia por asuntos propios pendiente del visto bueno del cargo superior.", "El acta de una reunión que no ha sido firmada aún por la persona que actúo en la secretaría del Órgano colegiado."], "c": 1, "e": "Un expediente cerrado hace años no debe estar en el archivo de oficina, sino transferido.", "r": "Manual de Archivo de Gestión UPV/EHU · batería oficial, pregunta 450"}]}, {"id": "b12", "sig": "Bloque 12", "titulo": "Bloque 12. Archivo, contratación pública y biblioteca", "sub": "Preguntas 451–500 de la batería oficial (sin respuestas oficiales: resueltas por Claude).", "preguntas": [{"id": "ehu451", "q": "Según el Manual de archivo de gestión o archivo de oficina de la EHU, se considera que un grupo de documentos originan series documentales claras cuando:", "o": ["Los procedimientos en los que se han generado están muy normalizados, bien por la legislación o por la normativa propia.", "Utilizan el mismo tipo y tamaño de papel, así como el mismo membrete institucional.", "Llustran el mismo tipo de acto administrativo (por ejemplo, la serie de resoluciones de los recursos, la serie de solicitudes varias, etc.)", "No se aplica en la EHU el concepto de series documentales."], "c": 0, "e": "Respuesta probable: las series son claras cuando los procedimientos están muy normalizados.", "r": "Manual de Archivo de Gestión UPV/EHU · batería oficial, pregunta 451"}, {"id": "ehu452", "q": "Indique la característica que no es propia de un documento de archivo:", "o": ["Son conjuntos orgánicos de documentos, que responden a la actividad de la oficina productora. El documento de archivo está relacionado con los que le preceden y los que le siguen, tiene carácter seriado.", "Son ejemplares únicos que reflejan la actuación o actuaciones para la resolución de un asunto. Son originales, o tratados como tales.", "Testimonian las actividades de la Universidad en el cumplimiento de sus fines.", "Apoyan la gestión, pueden ayudar en el proceso de la toma de decisiones como material de apoyo, pueden ser boletines oficiales, libros, revistas, publicaciones o informes elaborados por otras instituciones, etc."], "c": 3, "e": "El material de apoyo (boletines, libros, informes ajenos) no es documento de archivo.", "r": "Manual de Archivo de Gestión UPV/EHU · batería oficial, pregunta 452"}, {"id": "ehu453", "q": "Las entidades del sector público Vasco inspirarán el proceso de normalización del uso del euskera en los siguientes principios rectores:", "o": ["Principio de no discriminación.", "Principio de eficacia y eficiencia.", "Principio de concentración.", "Las respuestas a) y b) son correctas."], "c": 3, "e": "Respuesta probable: no discriminación y eficacia y eficiencia son principios rectores.", "r": "Decreto 179/2019, de normalización del uso del euskera en el sector público vasco · batería oficial, pregunta 453"}, {"id": "ehu454", "q": "Indique la que no se corresponde con una tipología de documentos administrativos:", "o": ["Documentos administrativos de decisiones.", "Documentos administrativos de transmisión.", "Documentos administrativos de constancia.", "Documentos administrativos de petición."], "c": 3, "e": "Las tipologías son decisión, transmisión y constancia; «petición» no es una de ellas.", "r": "Tipología documental UPV/EHU · batería oficial, pregunta 454"}, {"id": "ehu455", "q": "Indique el documento que no es considerado de transmisión:", "o": ["El oficio.", "La instancia.", "La nota.", "La carta."], "c": 1, "e": "La instancia la presenta la ciudadanía; no es documento de transmisión (oficio, nota y carta sí lo son).", "r": "Tipología documental UPV/EHU · batería oficial, pregunta 455"}, {"id": "ehu456", "q": "Indique de las siguientes afirmaciones la que es propia de los documentos de apoyo informativo.", "o": ["Serán destruidos en la propia oficina donde se generan.", "Pasarán al Registro General (separadamente de los documentos de archivo) para su destrucción de forma segura y confidencial.", "Forman parte del Patrimonio Documental de la Universidad.", "La nota es considerada como documento de apoyo informativo."], "c": 0, "e": "Respuesta probable: los documentos de apoyo informativo se eliminan en la propia oficina.", "r": "Manual de Archivo de Gestión UPV/EHU · batería oficial, pregunta 456"}, {"id": "ehu457", "q": "Indique la opción que no se corresponde con la organización de archivos de gestión:", "o": ["En el archivo de gestión se conservarán los documentos generados o recibidos por la unidad administrativa en el ejercicio de sus funciones, mientras dure la tramitación de los asuntos.", "Es fundamental separar la documentación de archivo de la de apoyo informativo.", "La organización de los archivos de gestión debe basarse en el Cuadro de Clasificación Decimal Universal (CDU) y Calendario de Destrucción Documental de la Universidad.", "Los tipos documentales que integran las unidades documentales de las series estarán debidamente foliados con el fin de facilitar su ordenación, consulta y control."], "c": 2, "e": "Es incorrecta: la CDU es una clasificación bibliotecaria; el archivo usa el Cuadro de Clasificación propio.", "r": "Manual de Archivo de Gestión UPV/EHU · batería oficial, pregunta 457"}, {"id": "ehu458", "q": "El parámetro clasificador que se tiene en cuenta a la hora de diseñar una serie documental es:", "o": ["Su pertenencia a una línea de actividad concreta a desarrollar.", "La fase del procedimiento administrativo.", "El Grupo de titulación del cargo que genera el correspondiente documento.", "Como sólo conforman serie documentales los Órganos colegiados, el parámetro sería precisamente, el Órgano colegiado generador de los documentos."], "c": 0, "e": "La serie se define por su pertenencia a una línea de actividad concreta.", "r": "Manual de Archivo de Gestión UPV/EHU · batería oficial, pregunta 458"}, {"id": "ehu459", "q": "Según el Manual de archivo de gestión o archivo de oficina, los documentos depositados en el archivo central (señale la opción correcta):", "o": ["Sólo se prestarán documentos a la unidad que los haya generado.", "Se podrán prestar documentos a una unidad diferente a la que los ha generado, previa conformidad de ésta.", "Nunca podrán ser consultados por parte de solicitantes que no pertenezcan a la Universidad, ya que el Manual de archivo de gestión o archivo de oficina lo prohíbe expresamente.", "Pueden ser prestados a otras Administraciones Públicas siempre que acrediten un interés legítimo en la información contenida en los documentos objeto del préstamo."], "c": 1, "e": "Respuesta probable: pueden prestarse a otra unidad con la conformidad de la que los generó.", "r": "Manual de Archivo de Gestión UPV/EHU · batería oficial, pregunta 459"}, {"id": "ehu460", "q": "¿Qué duración tendrá el préstamo de una documentación custodiada por el archivo general de la EHU?", "o": ["Tendrá una duración máxima de un mes, prorrogable previa solicitud al Archivo General.", "Tendrá una duración máxima de quince días, prorrogable previa solicitud al Archivo General.", "Tendrá una duración máxima improrrogable de un mes.", "Tendrá una duración máxima improrrogable de quince días."], "c": 0, "e": "Respuesta probable: un mes como máximo, prorrogable si se solicita al Archivo General.", "r": "Manual de Archivo de Gestión UPV/EHU · batería oficial, pregunta 460"}, {"id": "ehu461", "q": "Según la tipología de documentos administrativos en la EHU, ¿Qué es un certificado?", "o": ["El documento que se utiliza para la comunicación entre órganos o unidades pertenecientes a un mismo órgano superior o entidad.", "El documento que acredita actos o situaciones de carácter administrativo, cuyo destinatario es una persona, Órgano o entidad que pretende la producción de efectos en un procedimiento administrativo o en el marco de relaciones jurídicas privadas.", "El documento que contiene comunicaciones de tipo personal y de contenido general, que no estén relacionadas directamente con la gestión habitual o con la tramitación de un procedimiento.", "El documento acreditativo de hechos, circunstancias, juicios o acuerdos."], "c": 1, "e": "El certificado acredita actos o situaciones administrativas para que surtan efecto ante un destinatario.", "r": "Tipología documental UPV/EHU · batería oficial, pregunta 461"}, {"id": "ehu462", "q": "La tipología de documentos administrativos en la EHU es:", "o": ["Decisiones, documentos de apoyo a la gestión administrativa, documentos administrativos de transmisión y documentos administrativos de constancia.", "Decisiones, documentos de apoyo a la gestión administrativa y documentos administrativos de constancia.", "Resoluciones, oficios, actas y certificados.", "Decisiones, documentos administrativos de transmisión y documentos administrativos de constancia."], "c": 3, "e": "Decisiones, documentos de transmisión y documentos de constancia.", "r": "Tipología documental UPV/EHU · batería oficial, pregunta 462"}, {"id": "ehu463", "q": "Según la tipología de documentos administrativos en la EHU, ¿Qué es un acta?", "o": ["El documento acreditativo de hechos, circunstancias, juicios o acuerdos.", "El documento que acredita actos o situaciones de carácter administrativo, cuyo destinatario es una persona, Órgano o entidad que pretende la producción de efectos en un procedimiento administrativo o en el marco de relaciones jurídicas privadas.", "El documento que se utiliza para la comunicación entre órganos o unidades pertenecientes a diferentes administraciones públicas.", "El documento que contiene una declaración de voluntad de un órgano administrativo sobre materias de su competencia."], "c": 0, "e": "El acta acredita hechos, circunstancias, juicios o acuerdos.", "r": "Tipología documental UPV/EHU · batería oficial, pregunta 463"}, {"id": "ehu464", "q": "Las entidades del sector público:", "o": ["No podrán contratar verbalmente, salvo que el contrato tenga carácter de necesidad.", "No podrán contratar verbalmente, salvo que el contrato tenga carácter de emergencia.", "No podrán contratar verbalmente en ningún caso.", "Podrán contratar verbalmente cuando exista una declaración de urgencia."], "c": 1, "e": "No se puede contratar verbalmente salvo en tramitación de emergencia.", "r": "LCSP art. 37.1 · batería oficial, pregunta 464"}, {"id": "ehu465", "q": "Los contratos del sector público podrán estar sometidos a:", "o": ["Solo a un régimen jurídico de derecho administrativo.", "Solo a un régimen jurídico de derecho fiscal.", "Aun régimen jurídico de derecho administrativo o de derecho privado.", "Solo a un régimen jurídico de derecho privado."], "c": 2, "e": "Los contratos pueden ser administrativos o privados.", "r": "LCSP art. 24 · batería oficial, pregunta 465"}, {"id": "ehu466", "q": "Según la tipología de documentos administrativos en la EHU, ¿Qué es un oficio?", "o": ["El documento que se utiliza para la comunicación entre órganos o unidades pertenecientes a un mismo órgano superior o entidad.", "El documento que acredita actos o situaciones de carácter administrativo, cuyo destinatario es una persona, Órgano o entidad que pretende la producción de efectos en un procedimiento administrativo o en el marco de relaciones jurídicas privadas", "El documento que se utiliza para la comunicación entre órganos o unidades pertenecientes a diferentes administraciones públicas, a diferentes entidades o departamentos y, dentro de éstos, a diferentes órganos superiores", "El documento que contiene una declaración de voluntad de un órgano administrativo sobre materias de su competencia"], "c": 2, "e": "El oficio comunica órganos de distintas administraciones, entidades, departamentos u órganos superiores (la nota, dentro del mismo).", "r": "Tipología documental UPV/EHU · batería oficial, pregunta 466"}, {"id": "ehu467", "q": "Según la Ley 9/2017, de 8 de noviembre de contratos del sector público, ¿Cuáles son los tipos de contratos del sector publico?", "o": ["Contratos administrativos y privados.", "Contratos administrativos, privados y mixtos.", "Contratos de obra, de suministros y de servicios.", "Contratos de obra, de suministros, de servicios, mixtos, de concesión de obras y de concesión de servicios."], "c": 3, "e": "Respuesta probable: obras, suministro, servicios, mixtos, concesión de obras y concesión de servicios (la a también la recoge la ley en el art. 24).", "r": "LCSP arts. 12-18 · batería oficial, pregunta 467"}, {"id": "ehu468", "q": "Según la Ley 9/2017, de 8 de noviembre de contratos del sector público, entre los contratos que deben remitirse, en los tres meses siguientes a su formalización, al Tribunal de cuentas u órgano de fiscalización de la comunidad autónoma, para el ejercicio de la función fiscalizadora, se encuentran:", "o": ["Los contratos de obras, siempre que la cuantía del contrato exceda de 450.000 euros.", "Los contratos de suministro, siempre que la cuantía del contrato exceda de 250.000 euros.", "Los contratos de gestión de servicios públicos, siempre que la cuantía del contrato exceda de 500.000 euros.", "Los contratos de servicios, siempre que la cuantía del contrato exceda de 150.000 euros."], "c": 3, "e": "Se remiten los de servicios de más de 150.000 €; obras y concesiones, más de 600.000 €; suministro, más de 450.000 €.", "r": "LCSP art. 335.1 · batería oficial, pregunta 468"}, {"id": "ehu469", "q": "Se consideran contratos menores:", "o": ["Los contratos de valor estimado inferior a 40.000 euros, cuando se trate de contratos de obras.", "Los contratos de valor estimado inferior a 25.000 euros, cuando se trate de contratos de servicios.", "Los contratos de valor estimado inferior a 15.000 euros, cuando se trate de contratos de concesión de servicios.", "Los contratos de valor estimado inferior a 40.000 euros, cuando se trate de contratos de suministro."], "c": 0, "e": "Contrato menor: obras de menos de 40.000 €; suministro y servicios, menos de 15.000 €.", "r": "LCSP art. 118.1 · batería oficial, pregunta 469"}, {"id": "ehu470", "q": "Según la Ley 9/2017, de 8 de noviembre de contratos del sector público, los contratos menores definidos en el apartado primero del artículo 118 no podrán tener una duración superior a:", "o": ["Cinco años ni ser objeto de prórroga.", "Un año niser objeto de prórroga.", "Un año con una prórroga de otro año.", "Dos años ni ser objeto de prórroga."], "c": 1, "e": "Duración máxima de un año, sin prórroga.", "r": "LCSP art. 29.8 · batería oficial, pregunta 470"}, {"id": "ehu471", "q": "Tendrán la consideración de contratos privados según LO indicado en los artículos 25 y 26 de la Ley 9/2017, de 8 de noviembre de contratos del sector público:", "o": ["Todos los que sean celebrados por entidades del sector público que siendo poder adjudicador no reúnan la condición de Administraciones públicas.", "Los contratos de servicios celebrados por la administración pública que tengan por objeto la creación e interpretación artística y literaria o espectáculos.", "Los contratos de servicios celebrados por la administración pública que tengan por objeto la suscripción a revistas, publicaciones periódicas y bases de datos.", "Todas las opciones anteriores son correctas"], "c": 3, "e": "Las tres situaciones son contratos privados.", "r": "LCSP arts. 25.1.a y 26.1 · batería oficial, pregunta 471"}, {"id": "ehu472", "q": "Señale la respuesta incorrecta. Con relación a la tramitación urgente de los expedientes de contratación:", "o": ["Podrán ser objeto de tramitación urgente los expedientes de contratación correspondientes a los contratos cuya celebración responda a una necesidad inaplazable.", "Podrán ser objeto de tramitación urgente los expedientes de contratación cuya adjudicación sea preciso acelerar por razones de interés público.", "Podrán ser objeto de tramitación urgente los expedientes de contratación cuando la Administración tenga que actuar de manera inmediata a causa de acontecimientos catastróficos, de situaciones que supongan grave peligro o de necesidades que afecten a la defensa nacional.", "El plazo de inicio de la ejecución del contrato no podrá exceder de un mes, contado desde la formalización."], "c": 2, "e": "Es incorrecta: esa situación (catástrofes, grave peligro, defensa nacional) es la tramitación de emergencia, no la urgente.", "r": "LCSP arts. 119 y 120 · batería oficial, pregunta 472"}, {"id": "ehu473", "q": "En toda contratación del sector público:", "o": ["Se incorporarán de manera facultativa criterios sociales y medioambientales siempre que guarden relación con el objeto del contrato.", "Se incorporarán de manera potestativa criterios sociales y medioambientales en la convicción de que su inclusión proporciona una mejor relación calidad-precio.", "Se incorporarán de manera transversal y preceptiva criterios sociales y medioambientales siempre que guarde relación con el objeto del contrato.", "Se facilitará el acceso a la contratación pública de las grandes y pequeñas empresas, así como de las empresas de economía social."], "c": 2, "e": "Los criterios sociales y medioambientales se incorporan de manera transversal y preceptiva.", "r": "LCSP art. 1.3 · batería oficial, pregunta 473"}, {"id": "ehu474", "q": "Señale la respuesta incorrecta. A los efectos de la Ley de contratos del sector publico, forman parte del sector publico:", "o": ["Las Entidades Gestoras y los Servicios Comunes de la Seguridad Social.", "Las Universidades Públicas y Privadas.", "Las Mutuas colaboradoras con la Seguridad Social.", "Las Juntas Generales de los Territorios Históricos del País Vasco en lo que respecta a su actividad de contratación."], "c": 1, "e": "Es incorrecta: solo las universidades públicas forman parte del sector público.", "r": "LCSP art. 3.1 · batería oficial, pregunta 474"}, {"id": "ehu475", "q": "De acuerdo con la legislación vigente en materia de contratos del sector público, los contratos de servicios:", "o": ["No podrán ser objeto de estos contratos los servicios que impliquen ejercicio de la autoridad inherente a los poderes públicos.", "Son aquellos en cuya virtud uno o varios poderes adjudicadores encomiendan a título oneroso a una o varias personas, naturales o jurídicas, la gestión de un servicio cuya prestación sea de su titularidad o competencia.", "Tienen por objeto la adquisición, el arrendamiento financiero, o el arrendamiento, con o sin opción de compra, de productos o bienes muebles.", "Su contrapartida viene constituida bien por el derecho a explotar los servicios objeto del contrato o bien por dicho derecho acompañado del de percibir un precio."], "c": 0, "e": "Los servicios que impliquen ejercicio de autoridad no pueden ser objeto de estos contratos.", "r": "LCSP art. 17 · batería oficial, pregunta 475"}, {"id": "ehu476", "q": "De acuerdo con la legislación vigente en materia de contratos del sector público, los contratos de servicios:", "o": ["Podrán ser objeto de estos contratos los servicios que impliquen ejercicio de la autoridad inherente a los poderes públicos.", "Es aquel en cuya virtud uno o varios poderes adjudicadores encomiendan a título oneroso a una o varias personas, naturales o jurídicas, la gestión de un servicio cuya prestación sea de su titularidad o competencia,", "Son aquellos cuyo objeto son prestaciones de hacer consistentes en el desarrollo de una actividad o dirigidas a la obtención de un resultado distinto de una obra o suministro, incluyendo aquellos en que el adjudicatario se obligue a ejecutar el servicio de forma sucesiva y por precio unitario.", "Su contrapartida viene constituida bien por el derecho a explotar los servicios objeto del contrato o bien por dicho derecho acompañado del de percibir un precio."], "c": 2, "e": "Contrato de servicios: prestaciones de hacer para una actividad o un resultado distinto de obra o suministro.", "r": "LCSP art. 17 · batería oficial, pregunta 476"}, {"id": "ehu477", "q": "Señale la respuesta incorrecta. Quedan excluidos del ámbito de la Ley de contratos del sector público:", "o": ["Las relaciones jurídicas consistentes en la prestación de un servicio público cuya utilización por los usuarios requiera el abono de una tarifa, tasa o precio público de aplicación general.", "Los contratos regulados en la legislación laboral.", "Los contratos mixtos.", "Las encomiendas de gestión reguladas en la legislación vigente en materia de régimen jurídico del sector público."], "c": 2, "e": "Es incorrecta: los contratos mixtos están incluidos en la ley.", "r": "LCSP arts. 11 y 18 · batería oficial, pregunta 477"}, {"id": "ehu478", "q": "Señale la opción incorrecta. En el perfil del contratante, en el caso de la información relativa a los contratos, debera publicarse al menos:", "o": ["El objeto detallado del contrato.", "Su duración.", "El presupuesto base de licitación.", "El importe de adjudicación, sin IVA."], "c": 3, "e": "Es incorrecta: el importe de adjudicación se publica con el IVA incluido.", "r": "LCSP art. 63.3 · batería oficial, pregunta 478"}, {"id": "ehu479", "q": "Solo podrán contratar con el sector público:", "o": ["Las personas jurídicas que tengan plena capacidad de obrar, no estén incursas en alguna prohibición de contratar, y acrediten su solvencia económica y financiera y técnica o profesional o, en los casos en que así lo exija esta Ley, se encuentren debidamente clasificadas.", "Las personas naturales o jurídicas, españolas o extranjeras, que tengan plena capacidad de obrar, no estén incursas en alguna prohibición de contratar, y acrediten su solvencia económica y financiera y técnica o profesional o, en los casos en que así lo exija esta Ley, se encuentren debidamente clasificadas.", "Las personas naturales o jurídicas, españolas o comunitarias, que tengan plena capacidad de obrar, no estén incursas en alguna prohibición de contratar, y acrediten su solvencia económica y financiera y técnica o profesional o, en los casos en que así lo exija esta Ley, se encuentren debidamente clasificadas.", "Las personas naturales que tengan plena capacidad de obrar, no estén incursas en alguna prohibición de contratar, y acrediten su solvencia económica y financiera y técnica o profesional o, en los casos en que así lo exija esta Ley, se encuentren debidamente clasificadas."], "c": 1, "e": "Personas naturales o jurídicas, españolas o extranjeras, con capacidad, sin prohibición y con solvencia.", "r": "LCSP art. 65.1 · batería oficial, pregunta 479"}, {"id": "ehu480", "q": "No podrán contratar las personas en quiénes concurra alguna de las siguientes circunstancias:", "o": ["Haber sido condenadas civilmente mediante sentencia.", "No cumplir el requisito de que al menos el 5 por ciento de sus empleados sean trabajadores con discapacidad.", "Haber solicitado la declaración de concurso voluntario.", "Hallarse al corriente en el cumplimiento de las obligaciones tributarias o de Seguridad Social."], "c": 2, "e": "Haber solicitado la declaración de concurso voluntario es prohibición de contratar. Ojo: la cuota de personas con discapacidad es del 2%, no del 5%.", "r": "LCSP art. 71.1.c · batería oficial, pregunta 480"}, {"id": "ehu481", "q": "El objeto de los contratos del sector público:", "o": ["Podrá fraccionarse con la finalidad de disminuir la cuantía del mismo.", "Deberá ser determinado.", "Siempre que la naturaleza o el objeto del contrato lo permitan, deberá preverse la realización independiente de cada una de sus partes mediante su división en lotes, salvo en el contrato de obras.", "El órgano de contratación que proceda a la división en lotes del objeto del contrato, no podrá limitar el número de lotes que pueden adjudicarse a cada licitador."], "c": 1, "e": "El objeto del contrato debe ser determinado; no puede fraccionarse para rebajar la cuantía.", "r": "LCSP art. 99 · batería oficial, pregunta 481"}, {"id": "ehu482", "q": "DADAS LAS SIGUIENTES REFERENCIAS BIBLIOGRÁFICAS: 1. Manzanos Bilbao, C. (1998). Salir de prisión: la otra condena. Zerbitzuan, 35, 64-70. 2. Moix Martínez, M. (2006). Teoría del trabajo social. Madrid: Síntesis. 3. Rodríguez Martín, V. (2003). Los recursos sociales. En T. Fernández García y M.C. Alemán Bracho (Coords.), Introducción al trabajo social (pp. 373-393). Madrid: Alianza. IDENTIFIQUE LA CLASE DE DOCUMENTO A LA QUE CORRESPONDE CADA UNA:", "o": ["1.Libro; 2. Artículo de revista; 3. Capítulo de libro.", "1. Artículo de revista; 2. Libro; 3. Capítulo de libro.", "1.Capítulo de libro; 2. Artículo de periódico; 3. Ponencia en congreso.", "1.Capítulo de libro; 2. Ponencia de congreso; 3. Artículo de periódico."], "c": 1, "e": "1: revista (Zerbitzuan); 2: libro; 3: capítulo de libro («En… (Coords.)»).", "r": "Normas APA · batería oficial, pregunta 482"}, {"id": "ehu483", "q": "En el módulo de circulación de un sistema integrado de gestión bibliotecaria el préstamo de un libro vincula:", "o": ["Un registro bibliográfico con un registro de persona usuaria.", "Un registro de ejemplar con un registro de persona usuaria.", "Un registro de persona usuaria con un registro de autoridad.", "Un registro bibliográfico con un registro de ejemplar."], "c": 1, "e": "El préstamo vincula un registro de ejemplar con uno de persona usuaria.", "r": "Sistemas integrados de gestión bibliotecaria · batería oficial, pregunta 483"}, {"id": "ehu484", "q": "Como regla general, en la biblioteca de la EHU se excluyen del préstamo a domicilio:", "o": ["Los cómics.", "Los videos.", "Las tesis no publicadas.", "Los CD-ROM."], "c": 2, "e": "Respuesta probable: las tesis no publicadas se excluyen del préstamo a domicilio.", "r": "Normativa de préstamo de la Biblioteca UPV/EHU · batería oficial, pregunta 484"}, {"id": "ehu485", "q": "Una biblioteca que recoge, trata y difunde información relativa a un tema o grupo de temas afines, cuya colección se centra en una materia o area concreta del conocimiento es:", "o": ["Una biblioteca local.", "Una biblioteca especializada.", "Una biblioteca universitaria.", "Una biblioteca nacional"], "c": 1, "e": "Es una biblioteca especializada.", "r": "Tipos de bibliotecas · batería oficial, pregunta 485"}, {"id": "ehu486", "q": "En la CDU, ¿Qué tienen en común los auxiliares de forma y lugar?", "o": ["Van entre paréntesis.", "Van entre comillas.", "Van entre corchetes.", "Ninguna de las respuestas anteriores es cierta."], "c": 0, "e": "Los auxiliares de forma (0…) y de lugar (1/9) van entre paréntesis.", "r": "CDU · batería oficial, pregunta 486"}, {"id": "ehu487", "q": "Según la normativa de préstamo de la biblioteca de la EHU, las condiciones de préstamo de ejemplares:", "o": ["Son las mismas para todas las categorías de personas usuarias de la biblioteca", "Solo dependen del tipo de ejemplar.", "Solo son diferentes para las personas usuarias externas de la biblioteca.", "Dependen tanto del tipo de ejemplar como de la categoría de persona usuaria."], "c": 3, "e": "Dependen del tipo de ejemplar y de la categoría de la persona usuaria.", "r": "Normativa de préstamo de la Biblioteca UPV/EHU · batería oficial, pregunta 487"}, {"id": "ehu488", "q": "En el marco del espacio europeo de enseñanza superior, ¿Cuál de las siguientes definiciones corresponde al modelo de biblioteca universitaria que introduce el concepto de CRAI y queda reflejada en el artículo 103 de los Estatutos de la EHU?", "o": ["Gran espacio multifuncional, con áreas de silencio, de ruido y para trabajo en grupo, así como con instalaciones tecnológicas de última generación y colecciones multidisciplinares, orientado al autoaprendizaje del alumnado.", "Combinación de biblioteca digital y física, tal y como lo describe la línea 1 de REBIUN.", "Centro de recursos para el aprendizaje, la docencia, la investigación y las actividades relacionadas con el funcionamiento y la gestión de la Universidad en su conjunto.", "El modelo de Biblioteca Universitaria que introduce el CRAI es exclusivamente el que integra todos los servicios de la Universidad que tienen relación directa con la investigación."], "c": 2, "e": "El CRAI es un centro de recursos para el aprendizaje, la docencia, la investigación y la gestión.", "r": "Estatutos UPV/EHU art. 103 · batería oficial, pregunta 488"}, {"id": "ehu489", "q": "Según el artículo 52 del Reglamento de la biblioteca universitaria de la EHU, únicamente serán personas usuarias de pleno derecho de la misma:", "o": ["Profesorado y alumnado de la EHU.", "Profesorado, alumnado, personal investigador y personal del servicio de seguridad de la EHU.", "Toda la comunidad universitaria y cualquier persona ajena a la Universidad que lo solicite debidamente.", "Personal docente e investigador, alumnado y PERSONAL técnico, de gestión y administración y servicios de la EHU."], "c": 3, "e": "Son usuarias de pleno derecho el PDI, el alumnado y el PTGAS.", "r": "Reglamento de la Biblioteca UPV/EHU art. 52 · batería oficial, pregunta 489"}, {"id": "ehu490", "q": "En el control de recepción de documentos, el \"kardex\" se usa para el:", "o": ["Registro de publicaciones monográficas en entornos automatizados.", "Control de duplicados", "Registro de publicaciones periódicas.", "Registro de publicaciones monográficas, pero solo en entornos no automatizados."], "c": 2, "e": "El kardex controla la recepción de publicaciones periódicas.", "r": "Gestión de publicaciones seriadas · batería oficial, pregunta 490"}, {"id": "ehu491", "q": "¿Cuál de las siguientes opciones es una ventaja del libre acceso a los fondos de la biblioteca?", "o": ["Los materiales se conservan mejor.", "Se pueden hacer estadísticas sobre el nivel de lectura.", "Las personas usuarias pueden encontrar obras en principio no buscadas.", "Las personas usuarias no necesitan señalización y orientación para localizar los fondos."], "c": 2, "e": "El libre acceso permite encontrar obras que no se buscaban (serendipia).", "r": "Biblioteconomía · batería oficial, pregunta 491"}, {"id": "ehu492", "q": "La biblioteca de la escuela de ingeniería de Bilbao-náutica recibe en donación una colección de mapas y cartas náuticas del siglo xix. En atención a sus características físicas, ¿Cual sería la forma mas adecuada de conservar este material cartográfico?", "o": ["Plegados en archivadores.", "Enrollados en tubos de cartón.", "En planeros.", "En estanterías inclinadas."], "c": 2, "e": "Los mapas antiguos se guardan en planeros, en horizontal y sin doblar.", "r": "Conservación de fondos cartográficos · batería oficial, pregunta 492"}, {"id": "ehu493", "q": "¿Cuál de los siguientes métodos no es conveniente para la prevención de robos en el fondo antiguo de la biblioteca, desde el punto de vista de la conservación?", "o": ["Instalación de cámaras de seguridad.", "Vigilancia directa en sala", "Colocación de bandas magnéticas adhesivas.", "Instalación de cajas de seguridad."], "c": 2, "e": "Las bandas magnéticas adhesivas dañan el fondo antiguo.", "r": "Conservación de fondo antiguo · batería oficial, pregunta 493"}, {"id": "ehu494", "q": "¿Qué significa que la CDU es extensible?", "o": ["Que abarca todos los campos del conocimiento existentes.", "Que cada categoría se subdivide en otras, presentando el conocimiento jerárquicamente.", "Que es susceptible de adaptación y ampliación.", "Que su sistema de notación decimal elimina las barreras linguísticas."], "c": 2, "e": "Respuesta probable: extensible significa que admite adaptación y ampliación.", "r": "CDU · batería oficial, pregunta 494"}, {"id": "ehu495", "q": "La Comisión de calidad estará integrada, al menos, por:", "o": ["Uno/a o varios/as representantes del Equipo Decanal/Dirección, varios representantes de PDI y un/a representante del personal técnico, de gestión y administración y servicios.", "Uno/a o varios/as representantes del Equipo Decanal/Dirección, varios representantes de PDI y un/a representante del Alumnado.", "Uno/a o varios/as representantes del Equipo Decanal/Dirección, varios representantes de PDI, un/a representante del personal técnico, de gestión y administración y servicios, las y los coordinadores de titulación en caso de que los hubiere y un/a representante del Alumnado.", "Uno/a o varios/as representantes del Equipo Decanal/Dirección, varios representantes de PDI, un/a representante del personal técnico, de gestión y administración y servicios y un/a representante del Alumnado."], "c": 3, "e": "Respuesta probable: Dirección, PDI, PTGAS y alumnado.", "r": "Sistema de Garantía de Calidad de los centros UPV/EHU · batería oficial, pregunta 495"}, {"id": "ehu496", "q": "Respecto a la evaluación del desempeño en la Ley 11/2022, de 1 de diciembre, de empleo público Vasco:", "o": ["Es voluntaria para las administraciones.", "Solo afecta al personal interino.", "Tiene efectos en la carrera profesional y retribuciones.", "Se realiza únicamente al final De la vida profesional."], "c": 2, "e": "La evaluación del desempeño tiene efectos en la carrera profesional y en las retribuciones.", "r": "Ley 11/2022 de Empleo Público Vasco · batería oficial, pregunta 496"}, {"id": "ehu497", "q": "Los perfiles linguísticos acreditados en procesos selectivos o de provisión por aquellas personas aspirantes que, en virtud de dichos procedimientos, no llegaran a acceder a la condición de persona empleada al servicio de la entidad del sector público Vasco", "o": ["Perderán su validez a los dos años.", "La parte escrita mantendrá su validez por tiempo indefinido, mientras que la parte oral contará con tres llamamientos extraordinarios para ser superada.", "Tendrán validez por tiempo indefinido.", "Ninguna de las respuestas es correcta."], "c": 2, "e": "Respuesta probable: los perfiles acreditados tienen validez indefinida.", "r": "Ley 11/2022 de Empleo Público Vasco; Decreto 179/2019 · batería oficial, pregunta 497"}, {"id": "ehu498", "q": "¿Qué colectivo ve reforzada su participación en órganos colegiados según la LOSU?", "o": ["Empresas colaboradoras", "Estudiantado.", "Personal Jubilado.", "Personal investigador visitante."], "c": 1, "e": "La LOSU refuerza la participación del estudiantado.", "r": "LOSU (LO 2/2023) · batería oficial, pregunta 498"}, {"id": "ehu499", "q": "En relación con las competencias de la administración de la comunidad autónoma, señale la afirmación incorrecta:", "o": ["Corresponde a la Administración autonómica la planificación y coordinación general, así como la elaboración de normas y directrices generales en materia de igualdad.", "La Administración autonómica tiene competencia para la evaluación de las políticas de igualdad en el ámbito de la Comunidad Autónoma.", "La asistencia técnica especializada en materia de igualdad a las entidades locales y al resto de poderes públicos vascos corresponde a la Administración autonómica.", "La Administración autonómica carece de potestad sancionadora en materia de igualdad de mujeres y hombres, correspondiendo esta exclusivamente a las administraciones forales."], "c": 3, "e": "Es incorrecta: la Administración autonómica sí tiene potestad sancionadora en igualdad.", "r": "DL 1/2023 (Igualdad de Mujeres y Hombres) art. 5 · batería oficial, pregunta 499"}, {"id": "ehu500", "q": "El IV Plan de igualdad de mujeres y hombres de la EHU se alinea con:", "o": ["0DS 3", "ODS 4", "ODS 5", "ODS 10"], "c": 2, "e": "ODS 5: Igualdad de género.", "r": "IV Plan de Igualdad UPV/EHU · batería oficial, pregunta 500"}]}]});
